abstract sig Sem {}
one sig ErfGelu, TanhGelu, LowerTri, Id, Unknown, SoftmaxLast, SoftmaxAxis0 extends Sem {}
abstract sig Kern {}
one sig KGelu, KIdentity, KSoftmax extends Kern {}
