    abstainer.SetConfidenceThresholds(0.65, 0.88)

    // Process request with uncertainty
    request := "Is this code correct?"
    result, _ := abstainer.ClassifyWithAbstention(request)

    switch result {
    case "ABSTAIN":
        fmt.Println("Low confidence - abstaining")
    case "ERROR":
