import re
from dataclasses import dataclass

DIRECTIVE_MARKERS = [
    r"ignore\s+(all\s+)?previous\s+instructions",
    r"system\s*:\s*override",
    r"developer\s*mode",
    r"jailbreak",
    r"role\s*=\s*system",
