class Route(Enum):
    LOCAL = "local"
    REMOTE = "remote"


@dataclass(frozen=True)
class RoutePolicy:
    h_max: float = 1.8
    min_margin: float = 0.05
    max_prompt_bytes: int = 16384


@dataclass
class RequestEnvelope:
    session_id: str
    prompt: str
    max_tokens: int
