"""Policy execution, mutation, validation, and incumbent-safe selection."""
from dataclasses import dataclass, replace
from typing import Any, Dict, Iterable, List, Sequence, Tuple
import copy
import hashlib
import json
import math


@dataclass(frozen=True)
class PolicyDecision:
    stop: bool
    reason: str = ""
    branch_count: int = 0
    ordering: str = "score_desc"
    parallel_group_size: int = 1
    remaining_budget: float = 0.0


@dataclass(frozen=True)
class SearchPolicy:
    """Executable exploration controller, not a passive configuration object."""
    name: str = "baseline"
    max_depth: int = 3
    max_nodes: int = 32
    branch_factor: int = 2
    budget: float = 32.0
    stop_score: float = 0.98
    ordering: str = "score_desc"
    parallel_group_size: int = 1

    def __post_init__(self):
        if any(type(value) is not int for value in (self.max_depth, self.max_nodes, self.branch_factor, self.parallel_group_size)):
            raise ValueError("search limits must be integers")
        if self.max_depth < 0 or self.max_nodes < 1 or self.branch_factor < 1:
            raise ValueError("invalid search limits")
        if not math.isfinite(self.budget) or self.budget <= 0 or not 0 <= self.stop_score <= 1 or self.parallel_group_size < 1:
            raise ValueError("invalid budget or stop score")
        if self.ordering not in ("score_desc", "score_asc", "fifo"):
            raise ValueError("unknown branch ordering")

    def decide(self, *, depth: int, current_score: float, frontier_size: int, spent: float) -> PolicyDecision:
        remaining = max(0.0, self.budget - spent)
        if remaining <= 0:
            return PolicyDecision(True, "budget", remaining_budget=remaining)
        if depth >= self.max_depth:
            return PolicyDecision(True, "depth", remaining_budget=remaining)
        if current_score >= self.stop_score:
            return PolicyDecision(True, "score", remaining_budget=remaining)
        count = min(self.branch_factor, self.max_nodes - frontier_size, int(remaining))
        if count <= 0:
            return PolicyDecision(True, "node_limit", remaining_budget=remaining)
        return PolicyDecision(False, "continue", count, self.ordering,
                              self.parallel_group_size, remaining)

    def fingerprint(self) -> str:
        payload = json.dumps(self.__dict__, sort_keys=True)
        return hashlib.sha256(payload.encode()).hexdigest()

    def mutated(self, **changes) -> "SearchPolicy":
        values = copy.deepcopy(self.__dict__)
        values.update(changes)
        values["name"] = f"{self.name}*"
        return SearchPolicy(**values)


@dataclass(frozen=True)
class ScoredPolicy:
    policy: SearchPolicy
    score: float
    cost: float = 0.0
    worlds: int = 0


class PolicyDeveloper:
    """Creates a bounded candidate set and never edits the discovery agent."""
    def __init__(self, maximum_candidates: int = 8):
        self.maximum_candidates = max(0, int(maximum_candidates))

    def generate(self, incumbent: SearchPolicy, limit: int = None) -> List[SearchPolicy]:
        if limit is not None and (type(limit) is not int or limit < 0):
            raise ValueError("revision limit must be a non-negative integer")
        limit = self.maximum_candidates if limit is None else min(limit, self.maximum_candidates)
        mutations = (
            {"branch_factor": min(8, incumbent.branch_factor + 1)},
            {"branch_factor": max(1, incumbent.branch_factor - 1)},
            {"max_depth": min(16, incumbent.max_depth + 1)},
            {"ordering": "score_asc" if incumbent.ordering == "score_desc" else "score_desc"},
            {"parallel_group_size": min(8, incumbent.parallel_group_size + 1)},
            {"stop_score": max(0.1, incumbent.stop_score - 0.05)},
            {"budget": min(256.0, incumbent.budget * 1.25)},
            {"max_nodes": min(512, incumbent.max_nodes + 8)},
        )
        return [incumbent.mutated(**mutations[i % len(mutations)]) for i in range(limit)]

    def select(self, candidates: Sequence[ScoredPolicy]) -> ScoredPolicy:
        if not candidates:
            raise ValueError("candidate set cannot be empty")
        incumbent = candidates[0]
        winner = max(candidates, key=lambda item: (item.score, -item.cost))
        return incumbent if winner.score < incumbent.score else winner

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Tuple
import copy
import hashlib
import json
import math


@dataclass(frozen=True)
class ExplorationPolicy:
    name: str = "baseline"
    branch_factor: int = 2
    max_depth: int = 3
    max_nodes: int = 8
    branch_order: str = "score_desc"
    stop_threshold: float = 0.95
    parallel_groups: int = 1
    budget: float = 8.0
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self):
        if any(type(value) is not int for value in (self.branch_factor, self.max_depth, self.max_nodes, self.parallel_groups)):
            raise ValueError("search limits must be integers")
        if not 0 <= self.stop_threshold <= 1 or self.branch_order not in ("score_desc", "score_asc", "fifo"):
            raise ValueError("invalid score threshold or ordering")
        if self.branch_factor < 1:
            raise ValueError("branch_factor must be >= 1")
        if self.max_depth < 0:
            raise ValueError("max_depth must be >= 0")
        if self.max_nodes < 1:
            raise ValueError("max_nodes must be >= 1")
        if self.parallel_groups < 1:
            raise ValueError("parallel_groups must be >= 1")
        if not math.isfinite(self.budget) or self.budget <= 0:
            raise ValueError("budget must be > 0")

    def decide(self, node, frontier, spent: float) -> Dict[str, Any]:
        """Executable policy logic; it decides when to branch and stop."""
        depth = int(node.metadata.get("depth", 0))
        if spent >= self.budget:
            return {"stop": True, "reason": "budget"}
        if depth >= self.max_depth:
            return {"stop": True, "reason": "depth"}
        if node.score >= self.stop_threshold:
            return {"stop": True, "reason": "threshold"}
        branches = min(self.branch_factor, max(0, self.max_nodes - len(frontier)), int(self.budget - spent))
        return {
            "stop": branches <= 0,
            "branch_count": max(0, branches),
            "order": self.branch_order,
            "parallel_group": self.parallel_groups,
            "budget": self.budget,
        }

    def fingerprint(self) -> str:
        payload = json.dumps(self.__dict__, sort_keys=True, default=str)
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def mutate(self, update: Dict[str, Any]) -> "ExplorationPolicy":
        values = copy.deepcopy(self.__dict__)
        values.update(update)
        values["name"] = values.get("name", self.name) + "*"
        return ExplorationPolicy(**values)


class PolicyDeveloper:
    """Produces candidate policy revisions while the discovery agent stays fixed."""

    def __init__(self, max_candidates: int = 4):
        self.max_candidates = max(1, int(max_candidates))

    def revise(self, policy: ExplorationPolicy, index: int = 0) -> ExplorationPolicy:
        updates = [
            {"branch_factor": min(policy.branch_factor + 1, 8)},
            {"max_depth": min(policy.max_depth + 1, 12)},
            {"branch_order": "score_asc" if policy.branch_order == "score_desc" else "score_desc"},
            {"stop_threshold": max(0.10, policy.stop_threshold - 0.05)},
            {"parallel_groups": min(policy.parallel_groups + 1, 4)},
        ]
        chosen = updates[index % len(updates)]
        return policy.mutate(chosen)

    def candidates(self, policy: ExplorationPolicy) -> List[ExplorationPolicy]:
        return [self.revise(policy, i) for i in range(self.max_candidates)]

    @staticmethod
    def select_best(candidates: Iterable[Tuple[ExplorationPolicy, float]]):
        if not candidates:
            raise ValueError("candidate set cannot be empty")
        items = list(candidates)
        incumbent = items[0]
        best = max(items, key=lambda pair: pair[1])
        if best[1] < incumbent[1]:
            return incumbent
        return best

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from ..tree import DiscoveryTree
from ..policy.legacy import ExplorationPolicy


@dataclass
class ReplayResult:
    score: float
    visited_nodes: int
    branches: int
    cost: float
    sparse_requests: int = 0
    worlds: int = 0
    details: Dict[str, Any] = field(default_factory=dict)


class SimulatorPool:
    def __init__(self, trees: Optional[List[DiscoveryTree]] = None):
        self.trees: List[DiscoveryTree] = []
        for tree in trees or []:
            self.add(tree)

    def add(self, tree: DiscoveryTree):
        valid, reason = tree.validate()
        if not valid:
            raise ValueError(reason)
        self.trees.append(DiscoveryTree.from_dict(tree.to_dict()))

    def __len__(self) -> int:
        return len(self.trees)


class ReplayEngine:
    """Readable offline replayer: no live discovery-agent calls."""

    def replay(self, policy: ExplorationPolicy, pool: SimulatorPool) -> ReplayResult:
        if not pool.trees:
            return ReplayResult(0.0, 0, 0, 0.0, worlds=0)

        world_scores = []
        visited_nodes = 0
        branches = 0
        cost = 0.0
        sparse = 0

        for tree in pool.trees:
            value = self._replay_tree(policy, tree)
            world_scores.append(value["score"])
            visited_nodes += value["visited_nodes"]
            branches += value["branches"]
            cost += value["cost"]
            sparse += value["sparse_requests"]

        score = sum(world_scores) / len(world_scores)
        return ReplayResult(score, visited_nodes, branches, cost, sparse, len(pool.trees), {"world_scores": world_scores})

    def _replay_tree(self, policy: ExplorationPolicy, tree: DiscoveryTree) -> Dict[str, Any]:
        valid, reason = tree.validate()
        if not valid:
            raise ValueError(reason)
        frontier = [tree.get(tree.root_id)]
        visited = 0
        branch_count = 0
        total_cost = 0.0
        sparse = 0
        best = 0.0

        while frontier and visited < policy.max_nodes:
            node = frontier.pop(0)
            if node.cost > policy.budget - total_cost:
                break
            visited += 1
            best = max(best, float(node.score))
            total_cost += float(node.cost)
            decision = policy.decide(node, frontier, total_cost)
            if decision.get("stop"):
                continue

            children = [tree.get(child_id) for child_id in node.children]
            requested = int(decision.get("branch_count", 0))
            if requested > len(children):
                sparse += requested - len(children)
                requested = len(children)
            if requested <= 0:
                continue

            if policy.branch_order == "score_desc":
                children.sort(key=lambda item: item.score, reverse=True)
            elif policy.branch_order == "score_asc":
                children.sort(key=lambda item: item.score)

            frontier.extend(children[:requested])
            branch_count += requested

        return {
            "score": best,
            "visited_nodes": visited,
            "branches": branch_count,
            "cost": total_cost,
            "sparse_requests": sparse,
        }

"""Bounded simulation primitives for historical-world replay."""
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Tuple
import math

from ..tree import DiscoveryTree, TreeNode
from ..policy.engine import PolicyDecision, SearchPolicy


@dataclass(frozen=True)
class SimulationBudget:
    max_nodes: int = 128
    max_cost: float = 128.0
    max_worlds: int = 128

    def __post_init__(self):
        if type(self.max_nodes) is not int or type(self.max_worlds) is not int:
            raise ValueError("node and world limits must be integers")
        if self.max_nodes < 1 or not math.isfinite(self.max_cost) or self.max_cost <= 0 or self.max_worlds < 1:
            raise ValueError("simulation limits must be positive")


@dataclass
class SimulationState:
    visited_nodes: int = 0
    selected_branches: int = 0
    sparse_requests: int = 0
    cost: float = 0.0
    best_score: float = 0.0
    stop_reasons: List[str] = field(default_factory=list)

    def exhausted(self, budget: SimulationBudget) -> bool:
        return self.visited_nodes >= budget.max_nodes or self.cost >= budget.max_cost


class HistoricalWorld:
    """Validated immutable-by-convention wrapper around a discovery tree."""
    def __init__(self, tree: DiscoveryTree):
        valid, error = tree.validate()
        if not valid:
            raise ValueError(error)
        self.tree = DiscoveryTree.from_dict(tree.to_dict())

    @property
    def world_id(self):
        return self.tree.tree_id

    def root(self):
        return self.tree.get(self.tree.root_id)

    def node(self, node_id):
        return self.tree.get(node_id)


class BranchSelector:
    def select(self, children: List[TreeNode], decision: PolicyDecision) -> List[TreeNode]:
        if decision.ordering == "score_desc":
            children = sorted(children, key=lambda item: item.score, reverse=True)
        elif decision.ordering == "score_asc":
            children = sorted(children, key=lambda item: item.score)
        return children[:decision.branch_count]


class WorldSimulator:
    """Replays a world using only nodes already present in its tree."""
    def __init__(self, selector: Optional[BranchSelector] = None):
        self.selector = selector or BranchSelector()

    def run(self, policy: SearchPolicy, world: HistoricalWorld,
            budget: Optional[SimulationBudget] = None) -> SimulationState:
        valid, error = world.tree.validate()
        if not valid:
            raise ValueError(error)
        budget = budget or SimulationBudget(max_nodes=policy.max_nodes, max_cost=policy.budget)
        budget = SimulationBudget(min(budget.max_nodes, policy.max_nodes),
                                  min(budget.max_cost, policy.budget), budget.max_worlds)
        state = SimulationState()
        frontier = [world.root()]
        while frontier and not state.exhausted(budget):
            node = frontier.pop(0)
            if node.cost > budget.max_cost - state.cost:
                state.stop_reasons.append("simulation_budget")
                break
            state.visited_nodes += 1
            state.cost += max(0.0, float(node.cost))
            state.best_score = max(state.best_score, float(node.score))
            if state.exhausted(budget):
                state.stop_reasons.append("simulation_budget")
                break
            decision = policy.decide(
                depth=int(node.metadata.get("depth", 0)),
                current_score=float(node.score),
                frontier_size=len(frontier),
                spent=state.cost,
            )
            if decision.stop:
                state.stop_reasons.append(decision.reason)
                continue
            children = [world.node(child_id) for child_id in node.children]
            if decision.branch_count > len(children):
                state.sparse_requests += decision.branch_count - len(children)
            selected = self.selector.select(children, decision)
            frontier.extend(selected)
            state.selected_branches += len(selected)
        if not frontier and not state.stop_reasons:
            state.stop_reasons.append("frontier_empty")
        return state


class SimulatorPool:
    """Accumulated historical worlds with bounded multi-world execution."""
    def __init__(self, worlds: Iterable[DiscoveryTree] = ()):
        self.worlds: List[HistoricalWorld] = []
        self.extend(worlds)

    def add(self, world):
        if isinstance(world, DiscoveryTree):
            world = HistoricalWorld(world)
        if not isinstance(world, HistoricalWorld):
            raise TypeError("world must be a DiscoveryTree or HistoricalWorld")
        self.worlds.append(world)

    def extend(self, worlds):
        for world in worlds:
            self.add(world)

    def snapshot(self):
        return tuple(self.worlds)

    def bounded(self, maximum):
        if type(maximum) is not int or maximum < 0:
            raise ValueError("world limit must be a non-negative integer")
        if maximum == 0:
            return SimulatorPool()
        return SimulatorPool(item.tree for item in self.worlds[-maximum:])

    def __len__(self):
        return len(self.worlds)

from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
import json
import uuid
import math


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


@dataclass
class TreeNode:
    node_id: str = field(default_factory=lambda: "node_" + uuid.uuid4().hex[:12])
    parent_id: Optional[str] = None
    children: List[str] = field(default_factory=list)
    policy_decision: Dict[str, Any] = field(default_factory=dict)
    branch_id: str = "root"
    candidate: Dict[str, Any] = field(default_factory=dict)
    execution_trace: List[Dict[str, Any]] = field(default_factory=list)
    evaluator_result: Dict[str, Any] = field(default_factory=dict)
    score: float = 0.0
    status: str = "created"
    cost: float = 0.0
    timestamp: str = field(default_factory=utc_now)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, payload: Dict[str, Any]) -> "TreeNode":
        return cls(**payload)


class DiscoveryTree:
    """Serializable historical world and discovery tree."""

    def __init__(self, tree_id: Optional[str] = None, metadata: Optional[Dict[str, Any]] = None):
        self.tree_id = tree_id or "tree_" + uuid.uuid4().hex[:12]
        self.metadata = dict(metadata or {})
        self.created_at = utc_now()
        self.nodes: Dict[str, TreeNode] = {}
        root = TreeNode(branch_id="root", status="root", metadata={"depth": 0})
        self.root_id = root.node_id
        self.nodes[root.node_id] = root

    def add(self, parent_id: str, **fields: Any) -> TreeNode:
        if parent_id not in self.nodes:
            raise KeyError(f"unknown parent node: {parent_id}")
        node = TreeNode(parent_id=parent_id, **fields)
        if node.node_id in self.nodes:
            raise ValueError("duplicate node ID")
        self.nodes[node.node_id] = node
        self.nodes[parent_id].children.append(node.node_id)
        return node

    def get(self, node_id: str) -> TreeNode:
        return self.nodes[node_id]

    def leaves(self) -> List[TreeNode]:
        return [node for node in self.nodes.values() if not node.children and node.status != "root"]

    def validate(self):
        if self.root_id not in self.nodes:
            return False, "missing root"
        if self.nodes[self.root_id].parent_id is not None:
            return False, "root must not have a parent"
        for key, node in self.nodes.items():
            if key != node.node_id:
                return False, "node ID does not match dictionary key"
            if (not isinstance(node.cost, (int, float)) or not isinstance(node.score, (int, float))
                    or not math.isfinite(node.cost) or node.cost < 0 or not math.isfinite(node.score)):
                return False, "node cost and score must be finite; cost must be non-negative"
            if len(node.children) != len(set(node.children)):
                return False, "duplicate child link"
            if key != self.root_id:
                parent = self.nodes.get(node.parent_id)
                if parent is None or key not in parent.children:
                    return False, "missing reverse parent link"
            for child_id in node.children:
                child = self.nodes.get(child_id)
                if child is None:
                    return False, f"child {child_id} missing"
                if child.parent_id != node.node_id:
                    return False, f"broken parent link for {child_id}"
        visited = set()
        pending = [self.root_id]
        while pending:
            node_id = pending.pop()
            if node_id in visited:
                return False, "cycle or repeated node"
            visited.add(node_id)
            pending.extend(self.nodes[node_id].children)
        if len(visited) != len(self.nodes):
            return False, "disconnected nodes"
        return True, None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "tree_id": self.tree_id,
            "created_at": self.created_at,
            "metadata": self.metadata,
            "root_id": self.root_id,
            "nodes": [node.to_dict() for node in self.nodes.values()],
        }

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), sort_keys=True, indent=2)

    @classmethod
    def from_dict(cls, payload: Dict[str, Any]) -> "DiscoveryTree":
        tree = cls(payload.get("tree_id"), payload.get("metadata"))
        tree.created_at = payload.get("created_at", utc_now())
        tree.root_id = payload.get("root_id", tree.root_id)
        tree.nodes = {}
        for node in payload.get("nodes", []):
            if node["node_id"] in tree.nodes:
                raise ValueError("duplicate node ID")
            tree.nodes[node["node_id"]] = TreeNode.from_dict(node)
        valid, error = tree.validate()
        if not valid:
            raise ValueError(error)
        return tree

    @classmethod
    def from_json(cls, raw: str) -> "DiscoveryTree":
        return cls.from_dict(json.loads(raw))

