    def characterize_bit_flip(self, circuit_fn, n_shots: int = 1000) -> float:
        errors = 0
        for _ in range(n_shots):
            result = circuit_fn()
            measured = result.get("measured", [0])
            expected = result.get("expected", [0])
            if measured != expected:
                errors += 1
        return errors / n_shots
