        assert(ins.rs1 < 32);
        assert(ins.rs2 < 32);
    }
}

void harness_register_file_bounds(void) {
    VSMRegisters regs;
    memset(&regs, 0, sizeof(regs));

    for (int i = 0; i < 32; i++) {
        regs.r[i] = (vsm_u64)i * 0x1111111111111111ULL;
    }

