void harness_nent_bounded(void) {
    ledger_t L;
    memset(&L, 0, sizeof(L));

    word_t w = { .w = {1}, .len = 1 };

    for (int i = 0; i < NENT; i++) {
        err_t rc = ledger_append(&L, (uint8_t)(i % (MAXN + 1)), 0, &w);
        if (rc != OK) break;
    }
    assert(L.nent <= NENT);

    err_t rc = ledger_append(&L, 0, 0, &w);
    if (L.nent == NENT) {
        assert(rc == FULL);
    }
