#define MAX_ERRORS 0x05
#define OP_NOP     0x00
#define OP_EXEC    0x01
#define OP_RESET   0x02

typedef enum { PHASE_RUN=0x0, PHASE_FAULT=0x1, PHASE_RECOVER=0x2 } worker_phase_t;

typedef struct __attribute__((__packed__)) {
    uint32_t payload : 24;
    uint32_t opcode  : 8;
} cmd_word_t;

typedef struct {
    uint32_t epoch;
    uint8_t err_count;
    worker_phase_t phase;
    uint16_t seq_parity;
} worker_state_t;

static inline bool validate_cmd(cmd_word_t cmd);
static inline worker_state_t transition(worker_state_t s, cmd_word_t m);
int dispatch_worker(worker_state_t *s, cmd_word_t m);

void harness_err_count_bounded(void) {
    worker_state_t s = { .epoch = 0, .err_count = 0, .phase = PHASE_RUN, .seq_parity = 0 };
    cmd_word_t bad = { .payload = 0xFFFFFF, .opcode = 0xFF };

    for (int i = 0; i < MAX_ERRORS + 5; i++) {
        dispatch_worker(&s, bad);
    }
    assert(s.err_count <= MAX_ERRORS);
}

void harness_fault_phase(void) {
    worker_state_t s = { .epoch = 0, .err_count = 0, .phase = PHASE_RUN, .seq_parity = 0 };
    cmd_word_t bad = { .payload = 0, .opcode = 0xFF };

    for (int i = 0; i < MAX_ERRORS; i++) {
        dispatch_worker(&s, bad);
    }
    assert(s.phase == PHASE_FAULT);
}

void harness_epoch_monotonic(void) {
    worker_state_t s = { .epoch = 0, .err_count = 0, .phase = PHASE_RUN, .seq_parity = 0 };
    cmd_word_t exec = { .payload = 0x01, .opcode = OP_EXEC };

    uint32_t prev_epoch = s.epoch;
    for (int i = 0; i < 10; i++) {
        dispatch_worker(&s, exec);
        assert(s.epoch >= prev_epoch);
        prev_epoch = s.epoch;
    }
}

void harness_reset_recovers(void) {
    worker_state_t s = { .epoch = 0, .err_count = MAX_ERRORS, .phase = PHASE_FAULT, .seq_parity = 0 };
    cmd_word_t reset = { .payload = 0, .opcode = OP_RESET };

    dispatch_worker(&s, reset);
    assert(s.phase == PHASE_RECOVER || s.phase == PHASE_RUN);
}

void harness_nop_idempotent(void) {
    worker_state_t s = { .epoch = 5, .err_count = 0, .phase = PHASE_RUN, .seq_parity = 0 };
    cmd_word_t nop = { .payload = 0, .opcode = OP_NOP };

    worker_state_t before = s;
    dispatch_worker(&s, nop);
    assert(s.err_count == before.err_count);
    assert(s.phase == before.phase);
}

#include <assert.h>
#include <stdint.h>
#include <string.h>

#define WORM_MAGIC_SIZE   4
#define WORM_HASH_SIZE    64
#define WORM_PAYLOAD_SIZE 4096

typedef struct {
    char magic[WORM_MAGIC_SIZE];
    char prev_hash[WORM_HASH_SIZE];
    char current_hash[WORM_HASH_SIZE];
    uint32_t record_count;
    unsigned char payload[WORM_PAYLOAD_SIZE];
} WormBlock;

static void deterministic_hash(const char *prev, const unsigned char *payload,
                                uint32_t payload_len, char *out_hash) {
    uint32_t acc = 0;
    for (uint32_t i = 0; i < 64; i++) {
        acc = acc * 31 + (unsigned char)prev[i];
        acc = acc * 17 + i;
    }
    for (uint32_t i = 0; i < payload_len; i++) {
        acc = acc * 33 + payload[i];
        acc = acc + (i + 1) * 17;
    }
    const char hex[] = "0123456789abcdef";
    for (int i = 0; i < 64; i++) {
        out_hash[i] = hex[(acc >> (i % 8 * 4)) & 0xf];
    }
}

void harness_hash_output_is_hex(void) {
    WormBlock block;
    memcpy(block.magic, "WORM", 4);
    memset(block.prev_hash, '0', 64);
    memset(block.payload, 0, WORM_PAYLOAD_SIZE);

    deterministic_hash(block.prev_hash, block.payload,
                       WORM_PAYLOAD_SIZE, block.current_hash);

    for (int i = 0; i < 64; i++) {
        char c = block.current_hash[i];
        assert((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'));
    }
}

void harness_magic_preserved(void) {
    WormBlock block;
    memcpy(block.magic, "WORM", 4);
    memset(block.prev_hash, '0', 64);
    block.record_count = 0;
    memset(block.payload, 0, WORM_PAYLOAD_SIZE);

    deterministic_hash(block.prev_hash, block.payload,
                       WORM_PAYLOAD_SIZE, block.current_hash);

    assert(block.magic[0] == 'W');
    assert(block.magic[1] == 'O');
    assert(block.magic[2] == 'R');
    assert(block.magic[3] == 'M');
}

void harness_record_count_fits(void) {
    WormBlock block;
    block.record_count = 0;
    uint32_t prev = block.record_count;
    block.record_count++;
    assert(block.record_count == prev + 1);
    assert(block.record_count > 0);
}

void harness_hash_deterministic(void) {
    WormBlock b1, b2;
    memcpy(b1.magic, "WORM", 4);
    memcpy(b2.magic, "WORM", 4);
    memset(b1.prev_hash, 'a', 64);
    memset(b2.prev_hash, 'a', 64);
    memset(b1.payload, 0x42, WORM_PAYLOAD_SIZE);
    memset(b2.payload, 0x42, WORM_PAYLOAD_SIZE);

    deterministic_hash(b1.prev_hash, b1.payload, WORM_PAYLOAD_SIZE, b1.current_hash);
    deterministic_hash(b2.prev_hash, b2.payload, WORM_PAYLOAD_SIZE, b2.current_hash);

    assert(memcmp(b1.current_hash, b2.current_hash, 64) == 0);
}

void harness_different_input_different_hash(void) {
    WormBlock b1, b2;
    memset(b1.prev_hash, '0', 64);
    memset(b2.prev_hash, '0', 64);
    memset(b1.payload, 0x00, WORM_PAYLOAD_SIZE);
    memset(b2.payload, 0xFF, WORM_PAYLOAD_SIZE);

    deterministic_hash(b1.prev_hash, b1.payload, WORM_PAYLOAD_SIZE, b1.current_hash);
    deterministic_hash(b2.prev_hash, b2.payload, WORM_PAYLOAD_SIZE, b2.current_hash);

    assert(memcmp(b1.current_hash, b2.current_hash, 64) != 0);
}

/*
 * TLM JXCL ISA — Binary parser stub implementations
 * Frama-C / ACSL formal verification target  (Frama-C 26+)
 *
 * The stubs are complete enough to satisfy WP's syntactic checks and to
 * supply proof obligations for the contracts in binary_parser.h.
 */

#include "binary_parser.h"
#include <stdint.h>
#include <stddef.h>

/* -------------------------------------------------------------------------
 * Little-endian decoders
 * --------------------------------------------------------------------- */

/*@ requires \valid(p + (0 .. 1));
  @ assigns  \nothing;
  @ ensures  \result == (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
  @*/
uint16_t read_le16(const uint8_t *p)
{
    return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

/*@ requires \valid(p + (0 .. 3));
  @ assigns  \nothing;
  @ ensures  \result ==
  @   (uint32_t)((uint32_t)p[0]       |
  @              ((uint32_t)p[1] << 8)  |
  @              ((uint32_t)p[2] << 16) |
  @              ((uint32_t)p[3] << 24));
  @*/
uint32_t read_le32(const uint8_t *p)
{
    return (uint32_t)((uint32_t)p[0]        |
                      ((uint32_t)p[1] << 8)  |
                      ((uint32_t)p[2] << 16) |
                      ((uint32_t)p[3] << 24));
}

/*@ requires \valid(p + (0 .. 7));
  @ assigns  \nothing;
  @ ensures  \result ==
  @   (uint64_t)((uint64_t)p[0]       |
  @              ((uint64_t)p[1] << 8)  |
  @              ((uint64_t)p[2] << 16) |
  @              ((uint64_t)p[3] << 24) |
  @              ((uint64_t)p[4] << 32) |
  @              ((uint64_t)p[5] << 40) |
  @              ((uint64_t)p[6] << 48) |
  @              ((uint64_t)p[7] << 56));
  @*/
uint64_t read_le64(const uint8_t *p)
{
    return (uint64_t)((uint64_t)p[0]        |
                      ((uint64_t)p[1] << 8)  |
                      ((uint64_t)p[2] << 16) |
                      ((uint64_t)p[3] << 24) |
                      ((uint64_t)p[4] << 32) |
                      ((uint64_t)p[5] << 40) |
                      ((uint64_t)p[6] << 48) |
                      ((uint64_t)p[7] << 56));
}

/* -------------------------------------------------------------------------
 * validate_section_bounds
 * --------------------------------------------------------------------- */

/*@ requires total_len <= (uint64_t)0xFFFFFFFFFFFFFFFFULL;
  @ assigns  \nothing;
  @ behavior fits:
  @   assumes offset <= total_len && size <= total_len - offset;
  @   ensures \result == 1;
  @ behavior overflow_or_oob:
  @   assumes offset > total_len || size > total_len - offset;
  @   ensures \result == 0;
  @ complete behaviors;
  @ disjoint behaviors;
  @*/
int validate_section_bounds(uint64_t offset, uint64_t size, uint64_t total_len)
{
    if (offset > total_len) {
        return 0;
    }
    /* offset <= total_len, so total_len - offset does not underflow */
    if (size > total_len - offset) {
        return 0;
    }
    return 1;
}

/* -------------------------------------------------------------------------
 * parse_header
 *
 * Layout (all fields little-endian):
 *   [0]   uint16_t  version        (must == 1)
 *   [2]   uint16_t  architecture   (must == 0x4A58)
 *   [4]   4 bytes   padding
 *   [8]   uint64_t  entry_point
 *   [16]  uint64_t  code_offset
 *   [24]  uint64_t  code_size
 *   [32]  uint64_t  data_offset
 *   [40]  uint64_t  data_size
 *   [48]  uint32_t  reserved       (must == 0)
 * --------------------------------------------------------------------- */

/*@ requires \valid(bytes + (0 .. len - 1));
  @ requires len >= HEADER_SIZE;
  @ requires \valid(out);
  @ assigns  *out;
  @ behavior valid_header:
  @   assumes bytes[0] == 'J' && bytes[1] == 'X' &&
  @           bytes[2] == 'C' && bytes[3] == 'L';
  @   ensures \result == 0;
  @   ensures BinaryHeaderValid(out, len);
  @ behavior invalid_magic:
  @   assumes bytes[0] != 'J' || bytes[1] != 'X' ||
  @           bytes[2] != 'C' || bytes[3] != 'L';
  @   ensures \result != 0;
  @ complete behaviors;
  @ disjoint behaviors;
  @*/
int parse_header(const uint8_t *bytes, uint64_t len, BinaryHeader *out)
{
    /* Magic check */
    if (bytes[0] != (uint8_t)'J' || bytes[1] != (uint8_t)'X' ||
        bytes[2] != (uint8_t)'C' || bytes[3] != (uint8_t)'L') {
        return -1;
    }

    /* Decode fields from raw bytes (avoids alignment concerns) */
    out->version       = read_le16(bytes + 0);
    out->architecture  = read_le16(bytes + 2);
    /* bytes[4..7]: padding, skip */
    out->entry_point   = read_le64(bytes + 8);
    out->code_offset   = read_le64(bytes + 16);
    out->code_size     = read_le64(bytes + 24);
    out->data_offset   = read_le64(bytes + 32);
    out->data_size     = read_le64(bytes + 40);
    out->reserved      = read_le32(bytes + 48);

    /* Semantic validation */
    if (out->version != 1) {
        return -2;
    }
    if (out->architecture != 0x4A58U) {
        return -3;
    }
    if (out->reserved != 0U) {
        return -4;
    }
    if (!validate_section_bounds(out->code_offset, out->code_size, len)) {
        return -5;
    }
    if (!validate_section_bounds(out->data_offset, out->data_size, len)) {
        return -6;
    }
    /* Entry point must lie within the code section */
    if (out->entry_point < out->code_offset ||
        out->entry_point >= out->code_offset + out->code_size) {
        return -7;
    }

    return 0;
}

/*
 * TLM JXCL ISA — Execution stack stub implementations
 * Frama-C / ACSL formal verification target  (Frama-C 26+)
 */

#include "execution_stack.h"
#include <stdint.h>

/* -------------------------------------------------------------------------
 * exec_push
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp >= 8;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp - 8, 8);
  @ requires InBounds(&state->memory, state->regs.sp - 8, 8);
  @ assigns  state->regs.sp,
  @          state->memory.data[state->regs.sp - 8 .. state->regs.sp - 1];
  @ ensures  state->regs.sp == \old(state->regs.sp) - 8;
  @ ensures  ValidStack(state);
  @ ensures  ValidMemory(&state->memory);
  @ ensures  state->memory.data[state->regs.sp]     == (uint8_t)(value);
  @ ensures  state->memory.data[state->regs.sp + 1] == (uint8_t)(value >> 8);
  @ ensures  state->memory.data[state->regs.sp + 2] == (uint8_t)(value >> 16);
  @ ensures  state->memory.data[state->regs.sp + 3] == (uint8_t)(value >> 24);
  @ ensures  state->memory.data[state->regs.sp + 4] == (uint8_t)(value >> 32);
  @ ensures  state->memory.data[state->regs.sp + 5] == (uint8_t)(value >> 40);
  @ ensures  state->memory.data[state->regs.sp + 6] == (uint8_t)(value >> 48);
  @ ensures  state->memory.data[state->regs.sp + 7] == (uint8_t)(value >> 56);
  @*/
void exec_push(MachineState *state, uint64_t value)
{
    state->regs.sp -= 8;

    state->memory.data[state->regs.sp]     = (uint8_t)(value);
    state->memory.data[state->regs.sp + 1] = (uint8_t)(value >> 8);
    state->memory.data[state->regs.sp + 2] = (uint8_t)(value >> 16);
    state->memory.data[state->regs.sp + 3] = (uint8_t)(value >> 24);
    state->memory.data[state->regs.sp + 4] = (uint8_t)(value >> 32);
    state->memory.data[state->regs.sp + 5] = (uint8_t)(value >> 40);
    state->memory.data[state->regs.sp + 6] = (uint8_t)(value >> 48);
    state->memory.data[state->regs.sp + 7] = (uint8_t)(value >> 56);
}

/* -------------------------------------------------------------------------
 * exec_pop
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp + 8 <= state->memory.size;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp, 8);
  @ requires InBounds(&state->memory, state->regs.sp, 8);
  @ requires \valid(out);
  @ assigns  state->regs.sp, *out;
  @ ensures  state->regs.sp == \old(state->regs.sp) + 8;
  @ ensures  ValidStack(state);
  @ ensures  *out ==
  @   (uint64_t)(
  @     (uint64_t)\old(state->memory.data[\old(state->regs.sp)])       |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 1]) << 8)  |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 2]) << 16) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 3]) << 24) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 4]) << 32) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 5]) << 40) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 6]) << 48) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 7]) << 56));
  @*/
void exec_pop(MachineState *state, uint64_t *out)
{
    uint64_t sp = state->regs.sp;

    *out = (uint64_t)((uint64_t)state->memory.data[sp]       |
                      ((uint64_t)state->memory.data[sp + 1] << 8)  |
                      ((uint64_t)state->memory.data[sp + 2] << 16) |
                      ((uint64_t)state->memory.data[sp + 3] << 24) |
                      ((uint64_t)state->memory.data[sp + 4] << 32) |
                      ((uint64_t)state->memory.data[sp + 5] << 40) |
                      ((uint64_t)state->memory.data[sp + 6] << 48) |
                      ((uint64_t)state->memory.data[sp + 7] << 56));

    state->regs.sp += 8;
}

/* -------------------------------------------------------------------------
 * exec_call
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp >= 8;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp - 8, 8);
  @ requires InBounds(&state->memory, state->regs.sp - 8, 8);
  @ assigns  state->regs.sp,
  @          state->regs.pc,
  @          state->memory.data[state->regs.sp - 8 .. state->regs.sp - 1];
  @ ensures  state->regs.sp == \old(state->regs.sp) - 8;
  @ ensures  state->regs.pc == target;
  @ ensures  ValidStack(state);
  @ ensures  ValidMemory(&state->memory);
  @ ensures  state->memory.data[state->regs.sp]     == (uint8_t)(return_addr);
  @ ensures  state->memory.data[state->regs.sp + 1] == (uint8_t)(return_addr >> 8);
  @ ensures  state->memory.data[state->regs.sp + 2] == (uint8_t)(return_addr >> 16);
  @ ensures  state->memory.data[state->regs.sp + 3] == (uint8_t)(return_addr >> 24);
  @ ensures  state->memory.data[state->regs.sp + 4] == (uint8_t)(return_addr >> 32);
  @ ensures  state->memory.data[state->regs.sp + 5] == (uint8_t)(return_addr >> 40);
  @ ensures  state->memory.data[state->regs.sp + 6] == (uint8_t)(return_addr >> 48);
  @ ensures  state->memory.data[state->regs.sp + 7] == (uint8_t)(return_addr >> 56);
  @*/
void exec_call(MachineState *state, uint64_t target, uint64_t return_addr)
{
    /* Push return address */
    state->regs.sp -= 8;

    state->memory.data[state->regs.sp]     = (uint8_t)(return_addr);
    state->memory.data[state->regs.sp + 1] = (uint8_t)(return_addr >> 8);
    state->memory.data[state->regs.sp + 2] = (uint8_t)(return_addr >> 16);
    state->memory.data[state->regs.sp + 3] = (uint8_t)(return_addr >> 24);
    state->memory.data[state->regs.sp + 4] = (uint8_t)(return_addr >> 32);
    state->memory.data[state->regs.sp + 5] = (uint8_t)(return_addr >> 40);
    state->memory.data[state->regs.sp + 6] = (uint8_t)(return_addr >> 48);
    state->memory.data[state->regs.sp + 7] = (uint8_t)(return_addr >> 56);

    /* Jump */
    state->regs.pc = target;
}

