  @ behavior non_empty_range:
  @   assumes len != 0;
  @   ensures \result == 1 <==>
  @     (addr < end && start < addr + len);
  @ complete behaviors;
  @ disjoint behaviors;
  @*/
int overlaps(uint64_t addr, uint64_t len, uint64_t start, uint64_t end)
{
    if (len == 0) {
        return 0;
