#include <stdint.h>
#include <stdbool.h>

#define MAX_ERRORS 0x05
#define OP_NOP     0x00
#define OP_EXEC    0x01
#define OP_RESET   0x02

typedef enum {
    PHASE_RUN    = 0x0,
    PHASE_FAULT  = 0x1,
    PHASE_RECOVER= 0x2
} worker_phase_t;

typedef struct __attribute__((__packed__)) {
    uint32_t payload : 24;
    uint32_t opcode  : 8;
} cmd_word_t;

typedef struct {
    uint32_t epoch;
    uint8_t  err_count;
    worker_phase_t phase;
    uint16_t seq_parity;
} worker_state_t;

static inline bool validate_cmd(cmd_word_t cmd) {
    return (cmd.opcode == OP_NOP || cmd.opcode == OP_EXEC || cmd.opcode == OP_RESET)
        && (cmd.payload <= 0xFFFF);
}

static inline worker_state_t transition(worker_state_t s, cmd_word_t m) {
    if (!validate_cmd(m)) {
        s.err_count = (s.err_count < MAX_ERRORS) ? s.err_count + 1 : MAX_ERRORS;
        s.phase = (s.err_count >= MAX_ERRORS) ? PHASE_FAULT : PHASE_RECOVER;
        return s;
    }

    switch (s.phase) {
        case PHASE_RUN:
            if (m.opcode == OP_RESET) {
                s.phase = PHASE_RECOVER;
            } else {
                s.epoch++;
                s.seq_parity ^= (uint16_t)(m.payload & 0x1);
            }
            break;
        case PHASE_FAULT:
            if (m.opcode == OP_RESET) {
                s.err_count = 0;
                s.phase = PHASE_RECOVER;
            }
            break;
        case PHASE_RECOVER:
            s.epoch = 0;
            s.phase = PHASE_RUN;
            break;
    }
    return s;
}

int dispatch_worker(worker_state_t *s, cmd_word_t m) {
    worker_state_t next = transition(*s, m);
    if (next.phase == PHASE_FAULT && s->phase != PHASE_FAULT) {
        *s = next;
        return -1;  // Fault containment boundary tripped
    }
    *s = next;
    return 0;
}

#include "cpl_bridge.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cpl_initialized = 0;
static int cpl_device = -1;

const char *cpl_status_string(cpl_status_t s) {
    switch (s) {
    case CPL_OK: return "OK";
    case CPL_ERR_NOMEM: return "NOMEM";
    case CPL_ERR_INVALID: return "INVALID";
    case CPL_ERR_DEVICE: return "DEVICE";
    case CPL_ERR_TIMEOUT: return "TIMEOUT";
    case CPL_ERR_NOTIMPL: return "NOTIMPL";
    default: return "?";
    }
}

cpl_status_t cpl_init(int device_id) {
    if (cpl_initialized) return CPL_OK;
    cpl_device = device_id;
    cpl_initialized = 1;
    return CPL_OK;
}

void cpl_shutdown(void) {
    cpl_initialized = 0;
    cpl_device = -1;
}

cpl_status_t cpl_buffer_alloc(cpl_buffer_t *b, size_t bytes, cpl_memspace_t sp) {
    if (!b || bytes == 0) return CPL_ERR_INVALID;
    memset(b, 0, sizeof(*b));
    b->bytes = bytes;
    b->space = sp;
    if (sp == CPL_MEM_HOST || sp == CPL_MEM_ABSOLUTE) {
        b->host_ptr = malloc(bytes);
        if (!b->host_ptr) return CPL_ERR_NOMEM;
        memset(b->host_ptr, 0, bytes);
    } else {
        b->device_ptr = 0;
        b->host_ptr = malloc(bytes);
        if (!b->host_ptr) return CPL_ERR_NOMEM;
    }
    b->registered = 1;
    return CPL_OK;
}

cpl_status_t cpl_buffer_free(cpl_buffer_t *b) {
    if (!b || !b->registered) return CPL_ERR_INVALID;
    free(b->host_ptr);
    b->host_ptr = NULL;
    b->device_ptr = 0;
    b->registered = 0;
    return CPL_OK;
}

cpl_status_t cpl_buffer_upload(cpl_buffer_t *b, const void *src, size_t n) {
    if (!b || !b->registered || !src) return CPL_ERR_INVALID;
    if (n > b->bytes) n = b->bytes;
    memcpy(b->host_ptr, src, n);
    return CPL_OK;
}

cpl_status_t cpl_buffer_download(cpl_buffer_t *b, void *dst, size_t n) {
    if (!b || !b->registered || !dst) return CPL_ERR_INVALID;
    if (n > b->bytes) n = b->bytes;
    memcpy(dst, b->host_ptr, n);
    return CPL_OK;
}

cpl_status_t cpl_kernel_register(cpl_kernel_t *k,
                                 const void *sass_image, size_t image_bytes,
                                 const char *name) {
    if (!k) return CPL_ERR_INVALID;
    memset(k, 0, sizeof(*k));
    k->name = name ? name : "anon";
    k->entry = (cpl_addr)(uintptr_t)sass_image;
    k->n_regs = 32;
    k->n_preds = 4;
    k->shared_bytes = 0;
    k->priority = 0;
    k->deadline = 0;
    (void)image_bytes;
    return CPL_OK;
}

cpl_status_t cpl_kernel_set_annot(cpl_kernel_t *k, void *ml_annot) {
    if (!k) return CPL_ERR_INVALID;
    k->ml_annot = ml_annot;
    return CPL_OK;
}

cpl_status_t cpl_kernel_set_priority(cpl_kernel_t *k, int prio) {
    if (!k) return CPL_ERR_INVALID;
    k->priority = prio;
    return CPL_OK;
}

cpl_status_t cpl_kernel_set_deadline(cpl_kernel_t *k, int deadline_us) {
    if (!k) return CPL_ERR_INVALID;
    k->deadline = deadline_us;
    return CPL_OK;
}

cpl_status_t cpl_launch(cpl_kernel_t *k, const cpl_launch_t *cfg,
                        cpl_buffer_t **args, int nargs) {
    if (!k || !cfg) return CPL_ERR_INVALID;
    if (!cpl_initialized) return CPL_ERR_DEVICE;

    fprintf(stderr, "[cpl] launch %s grid=(%d,%d,%d) block=(%d,%d,%d) args=%d\n",
            k->name ? k->name : "?",
            cfg->grid_x, cfg->grid_y, cfg->grid_z,
            cfg->block_x, cfg->block_y, cfg->block_z,
            nargs);

    /* In a real system: cuLaunchKernel or custom command buffer */
    (void)args;
    return CPL_OK;
}

cpl_status_t cpl_device_sync(void) {
    if (!cpl_initialized) return CPL_ERR_DEVICE;
    return CPL_OK;
}

cpl_status_t cpl_stream_sync(void *stream) {
    if (!cpl_initialized) return CPL_ERR_DEVICE;
    (void)stream;
    return CPL_OK;
}

void cpl_print_kernel(const cpl_kernel_t *k) {
    if (!k) return;
    fprintf(stderr, "[cpl] kernel: %s  regs=%d  preds=%d  shared=%d  prio=%d  dl=%d\n",
            k->name ? k->name : "?",
            k->n_regs, k->n_preds, k->shared_bytes,
            k->priority, k->deadline);
}

/* Minimal Smalltalk-80 inspired object runtime - dense hand-rolled.
   Used only for thick annotation objects and host-side metadata;
   the KERNEL LANGUAGE itself stays BLISS/PLM/CORAL.
   No GC in the device path. Systems style. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define ST_MAX_OBJECTS 512
#define ST_MAX_SLOTS 32
#define ST_MAX_METHODS 64
#define ST_MAX_CLASSES 32

typedef struct STObject STObject;
typedef struct STClass STClass;
typedef struct STMethod STMethod;

struct STMethod {
    char name[32];
    STObject *(*fn)(STObject *self, STObject **args, int argc);
};

struct STClass {
    char name[32];
    STClass *super;
    STMethod methods[ST_MAX_METHODS];
    int n_methods;
    int n_inst_vars;
};

struct STObject {
    STClass *class;
    STObject *slots[ST_MAX_SLOTS];
    int64_t ival;
    char *bytes;
    int size;
};

static STClass classes[ST_MAX_CLASSES];
static int n_classes = 0;
static STObject objects[ST_MAX_OBJECTS];
static int n_objects = 0;

STClass *st_class(const char *name, STClass *super, int n_ivars) {
    if (n_classes >= ST_MAX_CLASSES) return NULL;
    STClass *c = &classes[n_classes++];
    memset(c, 0, sizeof(*c));
    strncpy(c->name, name, 31);
    c->super = super;
    c->n_inst_vars = n_ivars;
    return c;
}

void st_add_method(STClass *c, const char *name,
                   STObject *(*fn)(STObject *, STObject **, int)) {
    if (c->n_methods >= ST_MAX_METHODS) return;
    STMethod *m = &c->methods[c->n_methods++];
    strncpy(m->name, name, 31);
    m->fn = fn;
}

STObject *st_new(STClass *c) {
    if (n_objects >= ST_MAX_OBJECTS) return NULL;
    STObject *o = &objects[n_objects++];
    memset(o, 0, sizeof(*o));
    o->class = c;
    return o;
}

STObject *st_integer(int64_t v) {
    STObject *o = st_new(NULL);
    o->ival = v;
    return o;
}

STObject *st_send(STObject *self, const char *selector,
                  STObject **args, int argc) {
    if (!self || !self->class) return NULL;
    for (STClass *c = self->class; c; c = c->super) {
        for (int i = 0; i < c->n_methods; i++) {
            if (strcmp(c->methods[i].name, selector) == 0)
                return c->methods[i].fn(self, args, argc);
        }
    }
    fprintf(stderr, "doesNotUnderstand: %s\n", selector);
    return NULL;
}

static STObject *annot_set_priority(STObject *self, STObject **args, int argc) {
    if (argc >= 1) self->slots[0] = args[0];
    return self;
}
static STObject *annot_set_deadline(STObject *self, STObject **args, int argc) {
    if (argc >= 1) self->slots[1] = args[0];
    return self;
}
static STObject *annot_priority(STObject *self, STObject **args, int argc) {
    (void)args; (void)argc;
    return self->slots[0] ? self->slots[0] : st_integer(0);
}
static STObject *annot_deadline(STObject *self, STObject **args, int argc) {
    (void)args; (void)argc;
    return self->slots[1] ? self->slots[1] : st_integer(0);
}

STClass *st_AnnotationClass;

void st_boot(void) {
    st_AnnotationClass = st_class("Annotation", NULL, 4);
    st_add_method(st_AnnotationClass, "priority:", annot_set_priority);
    st_add_method(st_AnnotationClass, "deadline:", annot_set_deadline);
    st_add_method(st_AnnotationClass, "priority", annot_priority);
    st_add_method(st_AnnotationClass, "deadline", annot_deadline);
}

STObject *st_new_annotation(int priority, int deadline) {
    STObject *a = st_new(st_AnnotationClass);
    STObject *p = st_integer(priority);
    STObject *d = st_integer(deadline);
    st_send(a, "priority:", &p, 1);
    st_send(a, "deadline:", &d, 1);
    return a;
}

#ifdef ST80_MAIN
int main(void) {
    st_boot();
    STObject *a = st_new_annotation(5, 1000);
    STObject *p = st_send(a, "priority", NULL, 0);
    STObject *d = st_send(a, "deadline", NULL, 0);
    printf("annotation: priority=%ld deadline=%ld\n",
           p ? p->ival : -1, d ? d->ival : -1);
    return 0;
}
#endif

#include "codegen.h"
#include "symtab.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *xstrdup(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

typedef struct {
    IrFunc *func;
    SymTab *st;
    int next_label;
} Gen;

static int fresh_label(Gen *g) {
    return g->next_label++;
}

static char *labname(int id, const char *pref) {
    char buf[64];
    snprintf(buf, sizeof(buf), "%s%d", pref, id);
    return xstrdup(buf);
}

static int load_symbol(Gen *g, Symbol *sym) {
    if (!sym) return -1;
    if (sym->reg >= 0)
        return sym->reg;

    int dst = g->st->next_reg++;
    IrInst *i;

    if (sym->storage == STOR_ABSOLUTE) {
        int addr = g->st->next_reg++;
        i = ir_emit(g->func, IR_MOV);
        i->dst = ir_reg(addr);
        i->src0 = ir_imm(sym->absolute);
        i = ir_emit(g->func, IR_LD);
        i->dst = ir_reg(dst);
        i->src0 = ir_mem(AS_ABS, addr, 0);
        i->comment = xstrdup(sym->name);
    } else if (sym->storage == STOR_BASED && sym->based_on) {
        int base_r = sym->reg >= 0 ? sym->reg : 0;
        i = ir_emit(g->func, IR_LD);
        i->dst = ir_reg(dst);
        i->src0 = ir_mem(AS_GLOBAL, base_r, 0);
        i->comment = xstrdup(sym->name);
    } else if (sym->storage == STOR_SHARED) {
        i = ir_emit(g->func, IR_LD);
        i->dst = ir_reg(dst);
        i->src0 = ir_mem(AS_SHARED, 0, sym->slot * 4);
        i->comment = xstrdup(sym->name);
    } else if (sym->storage == STOR_GLOBAL || sym->storage == STOR_PARAM) {
        i = ir_emit(g->func, IR_LD);
        i->dst = ir_reg(dst);
        i->src0 = ir_mem(sym->storage == STOR_PARAM ? AS_PARAM : AS_GLOBAL,
                         0, sym->slot * 4);
        i->comment = xstrdup(sym->name);
    } else {
        sym->reg = dst;
    }
    return dst;
}

static void store_symbol(Gen *g, Symbol *sym, int src_reg) {
    if (!sym) return;
    IrInst *i;
    if (sym->reg >= 0 && sym->storage != STOR_SHARED &&
        sym->storage != STOR_GLOBAL && sym->storage != STOR_ABSOLUTE) {
        i = ir_emit(g->func, IR_MOV);
        i->dst = ir_reg(sym->reg);
        i->src0 = ir_reg(src_reg);
        return;
    }
    if (sym->storage == STOR_ABSOLUTE) {
        int addr = g->st->next_reg++;
        i = ir_emit(g->func, IR_MOV);
        i->dst = ir_reg(addr);
        i->src0 = ir_imm(sym->absolute);
        i = ir_emit(g->func, IR_ST);
        i->dst = ir_mem(AS_ABS, addr, 0);
        i->src0 = ir_reg(src_reg);
    } else if (sym->storage == STOR_SHARED) {
        i = ir_emit(g->func, IR_ST);
        i->dst = ir_mem(AS_SHARED, 0, sym->slot * 4);
        i->src0 = ir_reg(src_reg);
    } else if (sym->storage == STOR_GLOBAL || sym->storage == STOR_PARAM) {
        i = ir_emit(g->func, IR_ST);
        i->dst = ir_mem(sym->storage == STOR_PARAM ? AS_PARAM : AS_GLOBAL,
                        0, sym->slot * 4);
        i->src0 = ir_reg(src_reg);
    } else {
        if (sym->reg < 0) sym->reg = g->st->next_reg++;
        i = ir_emit(g->func, IR_MOV);
        i->dst = ir_reg(sym->reg);
        i->src0 = ir_reg(src_reg);
    }
}

static int gen_expr(Gen *g, AstNode *e) {
    if (!e) return -1;
    switch (e->kind) {
    case AST_NUMBER: {
        int r = g->st->next_reg++;
        IrInst *i = ir_emit(g->func, IR_MOV);
        i->dst = ir_reg(r);
        i->src0 = ir_imm(e->u.number.ival);
        return r;
    }
    case AST_IDENT: {
        Symbol *sym = symtab_lookup(g->st, e->u.ident.name);
        if (!sym) {
            int r = g->st->next_reg++;
            IrInst *i = ir_emit(g->func, IR_MOV);
            i->dst = ir_reg(r);
            i->src0 = ir_imm(0);
            i->comment = xstrdup(e->u.ident.name);
            return r;
        }
        return load_symbol(g, sym);
    }
    case AST_BINARY: {
        int left = gen_expr(g, e->u.binary.left);
        int right = gen_expr(g, e->u.binary.right);
        int dst = g->st->next_reg++;
        IrOpcode op = IR_ADD;
        int is_cmp = 0;
        switch (e->u.binary.op) {
        case TOK_PLUS: op = IR_ADD; break;
        case TOK_MINUS: op = IR_SUB; break;
        case TOK_STAR: op = IR_MUL; break;
        case TOK_SLASH: op = IR_DIV; break;
        case TOK_AND: op = IR_AND; break;
        case TOK_OR: op = IR_OR; break;
        case TOK_XOR: op = IR_XOR; break;
        case TOK_SHL: op = IR_SHL; break;
        case TOK_SHR: op = IR_SHR; break;
        case TOK_EQ: case TOK_NE: case TOK_LT: case TOK_LE:
        case TOK_GT: case TOK_GE:
            is_cmp = 1;
            break;
        default: break;
        }
        if (is_cmp) {
            int p = g->st->next_pred++;
            IrInst *i = ir_emit(g->func, IR_SETP);
            i->dst = ir_pred(p);
            i->src0 = ir_reg(left);
            i->src1 = ir_reg(right);
            const char *cm = "eq";
            if (e->u.binary.op == TOK_NE) cm = "ne";
            else if (e->u.binary.op == TOK_LT) cm = "lt";
            else if (e->u.binary.op == TOK_LE) cm = "le";
            else if (e->u.binary.op == TOK_GT) cm = "gt";
            else if (e->u.binary.op == TOK_GE) cm = "ge";
            i->comment = xstrdup(cm);
            return p;
        }
        IrInst *i = ir_emit(g->func, op);
        i->dst = ir_reg(dst);
        i->src0 = ir_reg(left);
        i->src1 = ir_reg(right);
        return dst;
    }
    case AST_UNARY: {
        int src = gen_expr(g, e->u.unary.operand);
        int dst = g->st->next_reg++;
        IrOpcode op = (e->u.unary.op == TOK_NOT || e->u.unary.op == TOK_TILDE)
                      ? IR_NOT : IR_NEG;
        IrInst *i = ir_emit(g->func, op);
        i->dst = ir_reg(dst);
        i->src0 = ir_reg(src);
        return dst;
    }
    case AST_COND: {
        int c = gen_expr(g, e->u.cond.cond);
        int l_else = fresh_label(g);
        int l_end = fresh_label(g);
        IrInst *br = ir_emit(g->func, IR_BRA_P);
        br->src0 = ir_pred(c);
        br->src1.kind = OP_LABEL;
        br->src1.label = labname(l_else, "Lelse");
        int t = gen_expr(g, e->u.cond.then_e);
        int dst = g->st->next_reg++;
        IrInst *mv1 = ir_emit(g->func, IR_MOV);
        mv1->dst = ir_reg(dst);
        mv1->src0 = ir_reg(t);
        IrInst *j = ir_emit(g->func, IR_BRA);
        j->src0.kind = OP_LABEL;
        j->src0.label = labname(l_end, "Lend");
        IrInst *lab1 = ir_emit(g->func, IR_LABEL);
        lab1->src0.kind = OP_LABEL;
        lab1->src0.label = labname(l_else, "Lelse");
        int f = gen_expr(g, e->u.cond.else_e);
        IrInst *mv2 = ir_emit(g->func, IR_MOV);
        mv2->dst = ir_reg(dst);
        mv2->src0 = ir_reg(f);
        IrInst *lab2 = ir_emit(g->func, IR_LABEL);
        lab2->src0.kind = OP_LABEL;
        lab2->src0.label = labname(l_end, "Lend");
        return dst;
    }
    case AST_BITFIELD: {
        int src = gen_expr(g, e->u.bitfield.expr);
        int tmp = g->st->next_reg++;
        IrInst *sh = ir_emit(g->func, IR_SHR);
        sh->dst = ir_reg(tmp);
        sh->src0 = ir_reg(src);
        sh->src1 = ir_imm(e->u.bitfield.offset);
        int mask = (1 << e->u.bitfield.width) - 1;
        int dst = g->st->next_reg++;
        IrInst *an = ir_emit(g->func, IR_AND);
        an->dst = ir_reg(dst);
        an->src0 = ir_reg(tmp);
        an->src1 = ir_imm(mask);
        return dst;
    }
    case AST_CALL: {
        int nargs = 0;
        for (AstNode *a = e->u.call.args; a; a = a->next) nargs++;
        int *args = malloc(nargs * sizeof(int));
        int idx = 0;
        for (AstNode *a = e->u.call.args; a; a = a->next)
            args[idx++] = gen_expr(g, a);
        int dst = g->st->next_reg++;
        IrInst *call = ir_emit(g->func, IR_CALL);
        call->dst = ir_reg(dst);
        call->src0.kind = OP_LABEL;
        call->src0.label = xstrdup(e->u.call.fn->u.ident.name);
        free(args);
        return dst;
    }
    default:
        break;
    }
    return -1;
}

static void gen_stmt(Gen *g, AstNode *s) {
    if (!s) return;
    switch (s->kind) {
    case AST_ASSIGN: {
        int rhs = gen_expr(g, s->u.assign.rhs);
        Symbol *sym = symtab_lookup(g->st, s->u.assign.lhs->u.ident.name);
        store_symbol(g, sym, rhs);
        break;
    }
    case AST_IF: {
        int c = gen_expr(g, s->u.ifstmt.cond);
        int l_else = fresh_label(g);
        int l_end = fresh_label(g);
        IrInst *br = ir_emit(g->func, IR_BRA_P);
        br->src0 = ir_pred(c);
        br->src1.kind = OP_LABEL;
        br->src1.label = labname(l_else, "Lelse");
        /* then block */
        for (AstNode *st = s->u.ifstmt.then_b->u.block.stmts; st; st = st->next)
            gen_stmt(g, st);
        IrInst *j = ir_emit(g->func, IR_BRA);
        j->src0.kind = OP_LABEL;
        j->src0.label = labname(l_end, "Lend");
        /* else label */
        IrInst *lab1 = ir_emit(g->func, IR_LABEL);
        lab1->src0.kind = OP_LABEL;
        lab1->src0.label = labname(l_else, "Lelse");
        if (s->u.ifstmt.else_b) {
            for (AstNode *st = s->u.ifstmt.else_b->u.block.stmts; st; st = st->next)
                gen_stmt(g, st);
        }
        /* end label */
        IrInst *lab2 = ir_emit(g->func, IR_LABEL);
        lab2->src0.kind = OP_LABEL;
        lab2->src0.label = labname(l_end, "Lend");
        break;
    }
    case AST_WHILE: {
        int l_top = fresh_label(g);
        int l_end = fresh_label(g);
        IrInst *lab = ir_emit(g->func, IR_LABEL);
        lab->src0.kind = OP_LABEL;
        lab->src0.label = labname(l_top, "Ltop");
        int c = gen_expr(g, s->u.whilestmt.cond);
        IrInst *br = ir_emit(g->func, IR_BRA_P);
        br->src0 = ir_pred(c);
        br->src1.kind = OP_LABEL;
        br->src1.label = labname(l_end, "Lend");
        for (AstNode *st = s->u.whilestmt.body->u.block.stmts; st; st = st->next)
            gen_stmt(g, st);
        IrInst *j = ir_emit(g->func, IR_BRA);
        j->src0.kind = OP_LABEL;
        j->src0.label = labname(l_top, "Ltop");
        IrInst *lab2 = ir_emit(g->func, IR_LABEL);
        lab2->src0.kind = OP_LABEL;
        lab2->src0.label = labname(l_end, "Lend");
        break;
    }
    case AST_FOR: {
        gen_stmt(g, s->u.forstmt.init);
        int l_top = fresh_label(g);
        int l_end = fresh_label(g);
        IrInst *lab = ir_emit(g->func, IR_LABEL);
        lab->src0.kind = OP_LABEL;
        lab->src0.label = labname(l_top, "Ltop");
        int c = gen_expr(g, s->u.forstmt.cond);
        IrInst *br = ir_emit(g->func, IR_BRA_P);
        br->src0 = ir_pred(c);
        br->src1.kind = OP_LABEL;
        br->src1.label = labname(l_end, "Lend");
        for (AstNode *st = s->u.forstmt.body->u.block.stmts; st; st = st->next)
            gen_stmt(g, st);
        if (s->u.forstmt.step)
            gen_expr(g, s->u.forstmt.step);
        IrInst *j = ir_emit(g->func, IR_BRA);
        j->src0.kind = OP_LABEL;
        j->src0.label = labname(l_top, "Ltop");
        IrInst *lab2 = ir_emit(g->func, IR_LABEL);
        lab2->src0.kind = OP_LABEL;
        lab2->src0.label = labname(l_end, "Lend");
        break;
    }
    case AST_PARALLEL: {
        IrInst *bar = ir_emit(g->func, IR_BAR_SYNC);
        bar->src0 = ir_imm(0);
        break;
    }
    case AST_BARRIER: {
        IrInst *bar = ir_emit(g->func, IR_BAR_SYNC);
        bar->src0 = ir_imm(s->u.barrier.id);
        break;
    }
    case AST_RETURN: {
        if (s->u.ret.expr) {
            int r = gen_expr(g, s->u.ret.expr);
            IrInst *i = ir_emit(g->func, IR_MOV);
            i->dst = ir_reg(0);
            i->src0 = ir_reg(r);
        }
        ir_emit(g->func, IR_RET);
        break;
    }
    case AST_EXIT: {
        ir_emit(g->func, IR_EXIT);
        break;
    }
    case AST_EXPR_STMT: {
        if (s->u.exprstmt.expr)
            gen_expr(g, s->u.exprstmt.expr);
        break;
    }
    case AST_BLOCK: {
        for (AstNode *st = s->u.block.stmts; st; st = st->next)
            gen_stmt(g, st);
        break;
    }
    case AST_LABEL: {
        IrInst *lab = ir_emit(g->func, IR_LABEL);
        lab->src0.kind = OP_LABEL;
        lab->src0.label = xstrdup(s->u.ident.name);
        break;
    }
    case AST_GOTO: {
        IrInst *j = ir_emit(g->func, IR_BRA);
        j->src0.kind = OP_LABEL;
        j->src0.label = xstrdup(s->u.ident.name);
        break;
    }
    default:
        break;
    }
}

IrModule *codegen(AstNode *module) {
    if (!module || module->kind != AST_MODULE) return NULL;

    IrModule *ir = ir_new_module();

    for (AstNode *fn = module->u.module.routines; fn; fn = fn->next) {
        if (fn->kind != AST_ROUTINE) continue;

        SymTab st;
        symtab_init(&st);

        IrFunc *func = ir_new_func(ir, fn->u.routine.name, fn->u.routine.is_kernel);
        Gen g = { .func = func, .st = &st, .next_label = 0 };

        /* enter function scope */
        symtab_push(&st);

        /* register parameters */
        for (AstNode *p = fn->u.routine.params; p; p = p->next) {
            if (p->kind == AST_DECL) {
                Symbol *sym = symtab_insert(&st, p->u.decl.name,
                    p->u.decl.type, STOR_PARAM);
                if (sym) {
                    sym->reg = st.next_reg++;
                    IrInst *i = ir_emit(func, IR_MOV);
                    i->dst = ir_reg(sym->reg);
                    i->src0 = ir_imm(0);
                    i->comment = xstrdup(sym->name);
                }
            }
        }

        /* register local declarations */
        for (AstNode *d = fn->u.routine.body->u.block.stmts; d; d = d->next) {
            if (d->kind == AST_DECL) {
                Symbol *sym = symtab_insert(&st, d->u.decl.name,
                    d->u.decl.type, d->u.decl.storage);
                if (sym && d->u.decl.init) {
                    int r = gen_expr(&g, d->u.decl.init);
                    store_symbol(&g, sym, r);
                }
            }
        }

        /* generate body statements */
        for (AstNode *s = fn->u.routine.body->u.block.stmts; s; s = s->next) {
            if (s->kind != AST_DECL)
                gen_stmt(&g, s);
        }

        /* ensure function ends with ret/exit */
        if (!func->last || (func->last->op != IR_RET && func->last->op != IR_EXIT))
            ir_emit(func, IR_EXIT);

        func->num_regs = st.next_reg;
        func->num_preds = st.next_pred;

        symtab_pop(&st);
    }

    return ir;
}

#include "ir.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

IrModule *ir_new_module(void) {
    return calloc(1, sizeof(IrModule));
}

IrFunc *ir_new_func(IrModule *m, const char *name, int is_kernel) {
    IrFunc *f = calloc(1, sizeof(IrFunc));
    f->name = strdup(name);
    f->is_kernel = is_kernel;
    f->num_regs = 8;
    f->num_preds = 4;
    if (!m->funcs) m->funcs = f;
    else {
        IrFunc *p = m->funcs;
        while (p->next) p = p->next;
        p->next = f;
    }
    return f;
}

IrInst *ir_emit(IrFunc *f, IrOpcode op) {
    IrInst *i = calloc(1, sizeof(IrInst));
    i->op = op;
    if (!f->first) f->first = f->last = i;
    else {
        f->last->next = i;
        f->last = i;
    }
    return i;
}

IrOperand ir_reg(int r) {
    IrOperand o = {0};
    o.kind = OP_REG;
    o.reg = r;
    return o;
}

IrOperand ir_imm(long v) {
    IrOperand o = {0};
    o.kind = OP_IMM;
    o.imm = v;
    return o;
}

IrOperand ir_pred(int p) {
    IrOperand o = {0};
    o.kind = OP_PRED;
    o.pred = p;
    return o;
}

IrOperand ir_mem(AddrSpace as, int base, int off) {
    IrOperand o = {0};
    o.kind = OP_MEM;
    o.as = as;
    o.mem_base = base;
    o.mem_off = off;
    return o;
}

static const char *op_name(IrOpcode op) {
    static const char *n[] = {
        "nop","mov","add","sub","mul","div","mad",
        "and","or","xor","not","shl","shr","rol","ror",
        "min","max","abs","neg","setp","selp",
        "ld","st","atom","bra","bra.p","call","ret","exit",
        "bar.sync","shfl","vote","redux","cvt","label","comment"
    };
    return n[op];
}

static void print_operand(FILE *out, IrOperand *o) {
    switch (o->kind) {
    case OP_NONE: fprintf(out, "_"); break;
    case OP_REG: fprintf(out, "r%d", o->reg); break;
    case OP_IMM: fprintf(out, "%ld", o->imm); break;
    case OP_PRED: fprintf(out, "p%d", o->pred); break;
    case OP_LABEL: fprintf(out, "%s", o->label ? o->label : "?"); break;
    case OP_MEM:
        fprintf(out, "%s[r%d%+d]",
                o->as == AS_SHARED ? "shared" :
                o->as == AS_GLOBAL ? "global" :
                o->as == AS_PARAM ? "param" :
                o->as == AS_CONST ? "const" : "local",
                o->mem_base, o->mem_off);
        break;
    }
}

void ir_print(IrModule *m, FILE *out) {
    for (IrFunc *f = m->funcs; f; f = f->next) {
        fprintf(out, ".%s %s\n", f->is_kernel ? "entry" : "func", f->name);
        fprintf(out, " .regs %d\n .preds %d\n", f->num_regs, f->num_preds);
        for (IrInst *i = f->first; i; i = i->next) {
            if (i->op == IR_LABEL) {
                fprintf(out, "%s:\n", i->src0.label ? i->src0.label : "L");
                continue;
            }
            if (i->op == IR_COMMENT) {
                fprintf(out, " ; %s\n", i->comment ? i->comment : "");
                continue;
            }
            fprintf(out, " ");
            if (i->pred >= 0)
                fprintf(out, "@p%d ", i->pred);
            fprintf(out, "%-8s ", op_name(i->op));
            print_operand(out, &i->dst);
            if (i->src0.kind != OP_NONE) {
                fprintf(out, ", ");
                print_operand(out, &i->src0);
            }
            if (i->src1.kind != OP_NONE) {
                fprintf(out, ", ");
                print_operand(out, &i->src1);
            }
            if (i->src2.kind != OP_NONE) {
                fprintf(out, ", ");
                print_operand(out, &i->src2);
            }
            fprintf(out, "\n");
        }
        fprintf(out, "\n");
    }
}

void ir_free(IrModule *m) {
    for (IrFunc *f = m->funcs; f;) {
        IrFunc *nf = f->next;
        for (IrInst *i = f->first; i;) {
            IrInst *ni = i->next;
            free(i->comment);
            free(i);
            i = ni;
        }
        free(f->name);
        free(f);
        f = nf;
    }
    free(m);
}

#include "lexer.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int is_ident_start(int c) {
    return isalpha(c) || c == '_' || c == '%';
}

static int is_ident_cont(int c) {
    return isalnum(c) || c == '_' || c == '%';
}

static void skip_ws_and_comments(Lexer *L) {
    for (;;) {
        while (*L->cur == ' ' || *L->cur == '\t' || *L->cur == '\r') {
            L->cur++;
            L->col++;
        }
        if (*L->cur == '\n') {
            L->cur++;
            L->line++;
            L->col = 1;
            continue;
        }
        /* BLISS-style ! comment to end of line, also // and /* */
        if (*L->cur == '!' || (*L->cur == '/' && L->cur[1] == '/')) {
            while (*L->cur && *L->cur != '\n') L->cur++;
            continue;
        }
        if (*L->cur == '/' && L->cur[1] == '*') {
            L->cur += 2;
            while (*L->cur && !(*L->cur == '*' && L->cur[1] == '/')) {
                if (*L->cur == '\n') { L->line++; L->col = 1; }
                else L->col++;
                L->cur++;
            }
            if (*L->cur) L->cur += 2;
            continue;
        }
        break;
    }
}

static Token make_token(Lexer *L, TokenKind k) {
    Token t;
    t.kind = k;
    t.start = L->start;
    t.length = (int)(L->cur - L->start);
    t.line = L->line;
    t.col = L->col - t.length;
    t.value.integer = 0;
    return t;
}

static Token make_int(Lexer *L, long v) {
    Token t = make_token(L, TOK_NUMBER);
    t.value.integer = v;
    return t;
}

static TokenKind keyword(const char *s, int len) {
    struct { const char *spelling; TokenKind kind; } table[] = {
        {"MODULE", TOK_MODULE}, {"ROUTINE", TOK_ROUTINE},
        {"BEGIN", TOK_BEGIN}, {"END", TOK_END},
        {"IF", TOK_IF}, {"THEN", TOK_THEN}, {"ELSE", TOK_ELSE},
        {"FI", TOK_FI}, {"ELIF", TOK_ELIF},
        {"WHILE", TOK_WHILE}, {"DO", TOK_DO}, {"FOR", TOK_FOR},
        {"TO", TOK_TO}, {"BY", TOK_BY}, {"OD", TOK_OD},
        {"RETURN", TOK_RETURN}, {"EXIT", TOK_EXIT},
        {"GOTO", TOK_GOTO}, {"LABEL", TOK_LABEL},
        {"OWN", TOK_OWN}, {"GLOBAL", TOK_GLOBAL}, {"LOCAL", TOK_LOCAL},
        {"BIND", TOK_BIND}, {"EXTERNAL", TOK_EXTERNAL},
        {"BASED", TOK_BASED}, {"AT", TOK_AT}, {"ABSOLUTE", TOK_ABSOLUTE},
        {"WORD", TOK_WORD}, {"BIT", TOK_BIT}, {"BYTE", TOK_BYTE},
        {"LONG", TOK_LONG}, {"FLOAT", TOK_FLOAT}, {"PRED", TOK_PRED},
        {"REGISTER", TOK_REGISTER}, {"SHARED", TOK_SHARED},
        {"GLOBALMEM", TOK_GLOBALMEM}, {"CONST", TOK_CONST},
        {"PARAM", TOK_PARAM},
        {"PARALLEL", TOK_PARALLEL}, {"WARP", TOK_WARP}, {"CTA", TOK_CTA},
        {"SYNC", TOK_SYNC}, {"BARRIER", TOK_BARRIER},
        {"DEADLINE", TOK_DEADLINE}, {"PRIORITY", TOK_PRIORITY},
        {"BOUNDED", TOK_BOUNDED},
        {"MACRO", TOK_MACRO}, {"ENDMACRO", TOK_ENDMACRO},
        {"TABLE", TOK_TABLE}, {"COMMON", TOK_COMMON},
        {"AND", TOK_AND}, {"OR", TOK_OR}, {"NOT", TOK_NOT}, {"XOR", TOK_XOR},
        {"SHL", TOK_SHL}, {"SHR", TOK_SHR}, {"ROL", TOK_ROL}, {"ROR", TOK_ROR},
        {"TRUE", TOK_TRUE}, {"FALSE", TOK_FALSE},
        {"NULL", TOK_NULL},
        {0, 0}
    };
    for (int i = 0; table[i].spelling; i++) {
        if ((int)strlen(table[i].spelling) == len &&
            strncmp(table[i].spelling, s, len) == 0)
            return table[i].kind;
    }
    return TOK_IDENT;
}

void lexer_init(Lexer *L, const char *source) {
    L->src = source;
    L->cur = source;
    L->start = source;
    L->line = 1;
    L->col = 1;
    L->has_lookahead = 0;
}

Token lexer_next(Lexer *L) {
    if (L->has_lookahead) {
        L->has_lookahead = 0;
        return L->lookahead;
    }

    skip_ws_and_comments(L);
    L->start = L->cur;

    if (*L->cur == 0)
        return make_token(L, TOK_EOF);

    char c = *L->cur++;
    L->col++;

    /* identifiers and keywords */
    if (is_ident_start(c)) {
        while (is_ident_cont(*L->cur)) { L->cur++; L->col++; }
        TokenKind k = keyword(L->start, (int)(L->cur - L->start));
        return make_token(L, k);
    }

    /* numbers */
    if (isdigit(c)) {
        long v = c - '0';
        while (isdigit(*L->cur)) {
            v = v * 10 + (*L->cur - '0');
            L->cur++;
            L->col++;
        }
        return make_int(L, v);
    }

    /* string literals */
    if (c == '"') {
        while (*L->cur && *L->cur != '"') {
            if (*L->cur == '\n') { L->line++; L->col = 1; }
            else L->col++;
            L->cur++;
        }
        if (*L->cur) L->cur++;
        return make_token(L, TOK_STRING);
    }

    /* two-character operators */
    if (*L->cur) {
        char c2 = *L->cur;
        if (c == '=' && c2 == '=') { L->cur++; L->col++; return make_token(L, TOK_EQ); }
        if (c == '!' && c2 == '=') { L->cur++; L->col++; return make_token(L, TOK_NE); }
        if (c == '<' && c2 == '=') { L->cur++; L->col++; return make_token(L, TOK_LE); }
        if (c == '>' && c2 == '=') { L->cur++; L->col++; return make_token(L, TOK_GE); }
        if (c == '<' && c2 == '<') { L->cur++; L->col++; return make_token(L, TOK_SHL); }
        if (c == '>' && c2 == '>') { L->cur++; L->col++; return make_token(L, TOK_SHR); }
        if (c == '-' && c2 == '>') { L->cur++; L->col++; return make_token(L, TOK_ARROW); }
    }

    /* single-character operators */
    switch (c) {
    case '+': return make_token(L, TOK_PLUS);
    case '-': return make_token(L, TOK_MINUS);
    case '*': return make_token(L, TOK_STAR);
    case '/': return make_token(L, TOK_SLASH);
    case '%': return make_token(L, TOK_PERCENT);
    case '=': return make_token(L, TOK_ASSIGN);
    case '<': return make_token(L, TOK_LT);
    case '>': return make_token(L, TOK_GT);
    case ':': return make_token(L, TOK_COLON);
    case ';': return make_token(L, TOK_SEMI);
    case ',': return make_token(L, TOK_COMMA);
    case '.': return make_token(L, TOK_DOT);
    case '(': return make_token(L, TOK_LPAREN);
    case ')': return make_token(L, TOK_RPAREN);
    case '[': return make_token(L, TOK_LBRACK);
    case ']': return make_token(L, TOK_RBRACK);
    case '{': return make_token(L, TOK_LBRACE);
    case '}': return make_token(L, TOK_RBRACE);
    case '&': return make_token(L, TOK_AMPER);
    case '|': return make_token(L, TOK_PIPE);
    case '^': return make_token(L, TOK_CARET);
    case '~': return make_token(L, TOK_TILDE);
    case '?': return make_token(L, TOK_QUESTION);
    }

    return make_token(L, TOK_ERROR);
}

Token lexer_peek(Lexer *L) {
    if (!L->has_lookahead) {
        L->lookahead = lexer_next(L);
        L->has_lookahead = 1;
    }
    return L->lookahead;
}

void lexer_error(Lexer *L, const char *msg) {
    fprintf(stderr, "lexer error line %d: %s\n", L->line, msg);
}

const char *token_kind_name(TokenKind k) {
    static const char *names[] = {
        "EOF", "IDENT", "NUMBER", "STRING",
        "MODULE", "ROUTINE", "BEGIN", "END",
        "IF", "THEN", "ELSE", "FI", "ELIF",
        "WHILE", "DO", "FOR", "TO", "BY", "OD",
        "RETURN", "EXIT", "GOTO", "LABEL",
        "OWN", "GLOBAL", "LOCAL", "BIND", "EXTERNAL",
        "BASED", "AT", "ABSOLUTE",
        "WORD", "BIT", "BYTE", "LONG", "FLOAT", "PRED",
        "REGISTER", "SHARED", "GLOBALMEM", "CONST", "PARAM",
        "PARALLEL", "WARP", "CTA", "SYNC", "BARRIER",
        "DEADLINE", "PRIORITY", "BOUNDED",
        "MACRO", "ENDMACRO",
        "TABLE", "COMMON",
        "AND", "OR", "NOT", "XOR",
        "SHL", "SHR", "ROL", "ROR",
        "TRUE", "FALSE",
        "NULL",
        "PLUS", "MINUS", "STAR", "SLASH", "PERCENT",
        "EQ", "NE", "LT", "LE", "GT", "GE",
        "ASSIGN", "COLON", "SEMI", "COMMA", "DOT",
        "LPAREN", "RPAREN", "LBRACK", "RBRACK",
        "LBRACE", "RBRACE", "ARROW", "AMPER", "PIPE",
        "CARET", "TILDE", "QUESTION",
        "ERROR"
    };
    if (k >= 0 && k <= TOK_ERROR) return names[k];
    return "?";
}

#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "ir.h"
#include "regalloc.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        perror(path);
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(n + 1);
    if (!buf) { fclose(f); return NULL; }
    if (fread(buf, 1, n, f) != (size_t)n) {
        fclose(f);
        free(buf);
        return NULL;
    }
    buf[n] = 0;
    fclose(f);
    return buf;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <source.kl> [-emit-ir] [-dump-ast] [-regalloc]\n", argv[0]);
        return 1;
    }
    int emit_ir = 0, dump_ast = 0, do_regalloc = 0;
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], "-emit-ir") == 0) emit_ir = 1;
        if (strcmp(argv[i], "-dump-ast") == 0) dump_ast = 1;
        if (strcmp(argv[i], "-regalloc") == 0) do_regalloc = 1;
    }

    char *src = read_file(argv[1]);
    if (!src) return 1;

    Lexer lex;
    lexer_init(&lex, src);

    Parser parser;
    parser_init(&parser, &lex);

    AstNode *mod = parse_module(&parser);
    if (parser.had_error) {
        fprintf(stderr, "compilation failed\n");
        free(src);
        return 1;
    }

    if (dump_ast) {
        printf("=== AST ===\n");
        ast_print(mod, 0);
    }

    IrModule *ir = codegen(mod);

    if (do_regalloc) {
        for (IrFunc *f = ir->funcs; f; f = f->next)
            graph_color_allocate(f);
    }

    if (emit_ir || !dump_ast) {
        printf("=== KERNEL IR (SM_86 oriented) ===\n");
        ir_print(ir, stdout);
    }

    ir_free(ir);
    free(src);
    return 0;
}

#include "parser.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void error_at(Parser *P, Token *t, const char *msg) {
    if (P->panic) return;
    P->panic = 1;
    P->had_error = 1;
    fprintf(stderr, "parse error line %d: %s (near '%.*s')\n",
            t->line, msg, t->length, t->start);
}

static void error(Parser *P, const char *msg) {
    error_at(P, &P->current, msg);
}

static void advance(Parser *P) {
    P->previous = P->current;
    for (;;) {
        P->current = lexer_next(P->lex);
        if (P->current.kind != TOK_ERROR) break;
        error_at(P, &P->current, "unexpected character");
    }
}

static int check(Parser *P, TokenKind k) {
    return P->current.kind == k;
}

static int match(Parser *P, TokenKind k) {
    if (!check(P, k)) return 0;
    advance(P);
    return 1;
}

static void consume(Parser *P, TokenKind k, const char *msg) {
    if (P->current.kind == k) {
        advance(P);
        return;
    }
    error(P, msg);
}

static char *copy_lexeme(Token *t) {
    char *s = malloc(t->length + 1);
    memcpy(s, t->start, t->length);
    s[t->length] = 0;
    return s;
}

AstNode *ast_new(AstKind kind, int line) {
    AstNode *n = calloc(1, sizeof(AstNode));
    n->kind = kind;
    n->line = line;
    return n;
}

/* Forward declarations */
static AstNode *expression(Parser *P);
static AstNode *statement(Parser *P);
static AstNode *declaration(Parser *P);
static AstNode *block(Parser *P);

/* ---------- Expressions (BLISS-oriented) ---------- */

static AstNode *primary(Parser *P) {
    if (match(P, TOK_NUMBER)) {
        AstNode *n = ast_new(AST_NUMBER, P->previous.line);
        n->u.number.ival = P->previous.value.integer;
        return n;
    }
    if (match(P, TOK_TRUE) || match(P, TOK_FALSE)) {
        AstNode *n = ast_new(AST_NUMBER, P->previous.line);
        n->u.number.ival = (P->previous.kind == TOK_TRUE);
        return n;
    }
    if (match(P, TOK_IDENT)) {
        AstNode *n = ast_new(AST_IDENT, P->previous.line);
        n->u.ident.name = copy_lexeme(&P->previous);
        /* function call or indexing */
        if (match(P, TOK_LPAREN)) {
            AstNode *call = ast_new(AST_CALL, n->line);
            call->u.call.fn = n;
            AstNode *args = NULL, *tail = NULL;
            if (!check(P, TOK_RPAREN)) {
                do {
                    AstNode *a = expression(P);
                    if (!args) args = tail = a;
                    else { tail->next = a; tail = a; }
                } while (match(P, TOK_COMMA));
            }
            consume(P, TOK_RPAREN, "expect ')' after arguments");
            call->u.call.args = args;
            return call;
        }
        if (match(P, TOK_LBRACK)) {
            AstNode *idx = ast_new(AST_INDEX, n->line);
            idx->u.index.base = n;
            idx->u.index.index = expression(P);
            consume(P, TOK_RBRACK, "expect ']'");
            return idx;
        }
        return n;
    }
    if (match(P, TOK_LPAREN)) {
        AstNode *e = expression(P);
        consume(P, TOK_RPAREN, "expect ')' after expression");
        return e;
    }
    error(P, "expect expression");
    return NULL;
}

static AstNode *unary(Parser *P) {
    if (match(P, TOK_MINUS) || match(P, TOK_NOT) || match(P, TOK_TILDE) ||
        match(P, TOK_AMPER) || match(P, TOK_STAR)) {
        TokenKind op = P->previous.kind;
        AstNode *n = ast_new(AST_UNARY, P->previous.line);
        n->u.unary.op = op;
        n->u.unary.operand = unary(P);
        return n;
    }
    /* PL/M style bit field: BIT(expr, offset, width) */
    if (match(P, TOK_BIT)) {
        consume(P, TOK_LPAREN, "expect '(' after BIT");
        AstNode *e = expression(P);
        consume(P, TOK_COMMA, "expect ','");
        AstNode *off = expression(P);
        consume(P, TOK_COMMA, "expect ','");
        AstNode *wid = expression(P);
        consume(P, TOK_RPAREN, "expect ')'");
        AstNode *n = ast_new(AST_BITFIELD, e->line);
        n->u.bitfield.expr = e;
        n->u.bitfield.offset = (int)off->u.number.ival;
        n->u.bitfield.width = (int)wid->u.number.ival;
        return n;
    }
    return primary(P);
}

/* Operator precedence climbing */
static AstNode *binary(Parser *P, int min_prec) {
    AstNode *left = unary(P);

    for (;;) {
        TokenKind op = P->current.kind;
        int prec = -1;
        int is_right_assoc = 0;

        switch (op) {
        case TOK_PLUS: case TOK_MINUS: prec = 1; break;
        case TOK_STAR: case TOK_SLASH: case TOK_PERCENT: prec = 2; break;
        case TOK_SHL: case TOK_SHR: prec = 3; break;
        case TOK_AND: prec = 4; break;
        case TOK_XOR: prec = 5; break;
        case TOK_OR: prec = 6; break;
        case TOK_EQ: case TOK_NE: case TOK_LT: case TOK_LE:
        case TOK_GT: case TOK_GE: prec = 7; break;
        case TOK_AND: prec = 8; break;
        case TOK_OR: prec = 9; break;
        default: break;
        }

        if (prec < min_prec) break;
        advance(P);

        AstNode *right = binary(P, prec + 1);
        AstNode *bin = ast_new(AST_BINARY, left->line);
        bin->u.binary.op = op;
        bin->u.binary.left = left;
        bin->u.binary.right = right;
        left = bin;
    }

    return left;
}

static AstNode *expression(Parser *P) {
    return binary(P, 0);
}

/* ---------- Statements ---------- */

static AstNode *declaration(Parser *P) {
    StorageClass sc = STOR_LOCAL;
    Type *ty = calloc(1, sizeof(Type));
    ty->kind = TYPE_WORD;

    if (match(P, TOK_LOCAL)) sc = STOR_LOCAL;
    else if (match(P, TOK_OWN)) sc = STOR_OWN;
    else if (match(P, TOK_GLOBAL)) sc = STOR_GLOBAL;
    else if (match(P, TOK_REGISTER)) sc = STOR_REGISTER;
    else if (match(P, TOK_SHARED)) sc = STOR_SHARED;
    else if (match(P, TOK_PARAM)) sc = STOR_PARAM;
    else if (match(P, TOK_CONST)) sc = STOR_CONST;
    else if (match(P, TOK_ABSOLUTE)) sc = STOR_ABSOLUTE;
    else if (match(P, TOK_BASED)) sc = STOR_BASED;

    if (match(P, TOK_WORD)) ty->kind = TYPE_WORD;
    else if (match(P, TOK_LONG)) ty->kind = TYPE_LONG;
    else if (match(P, TOK_BIT)) {
        ty->kind = TYPE_BIT;
        if (match(P, TOK_LPAREN)) {
            ty->bits = (int)expression(P)->u.number.ival;
            consume(P, TOK_RPAREN, "expect ')'");
        }
    }
    else if (match(P, TOK_BYTE)) ty->kind = TYPE_BYTE;
    else if (match(P, TOK_FLOAT)) ty->kind = TYPE_FLOAT;
    else if (match(P, TOK_PRED)) { ty->kind = TYPE_BIT; ty->bits = 1; }

    if (!match(P, TOK_IDENT)) {
        error(P, "expect variable name");
        return NULL;
    }
    char *name = copy_lexeme(&P->previous);

    AstNode *n = ast_new(AST_DECL, P->previous.line);
    n->u.decl.name = name;
    n->u.decl.type = ty;
    n->u.decl.storage = sc;

    if (match(P, TOK_ASSIGN)) {
        n->u.decl.init = expression(P);
    }

    match(P, TOK_SEMI);
    return n;
}

static AstNode *statement(Parser *P) {
    /* IF */
    if (match(P, TOK_IF)) {
        AstNode *n = ast_new(AST_IF, P->previous.line);
        n->u.ifstmt.cond = expression(P);
        consume(P, TOK_THEN, "expect THEN");
        n->u.ifstmt.then_b = block(P);
        if (match(P, TOK_ELSE)) {
            n->u.ifstmt.else_b = block(P);
        }
        consume(P, TOK_FI, "expect FI");
        return n;
    }

    /* WHILE */
    if (match(P, TOK_WHILE)) {
        AstNode *n = ast_new(AST_WHILE, P->previous.line);
        n->u.whilestmt.cond = expression(P);
        consume(P, TOK_DO, "expect DO");
        n->u.whilestmt.body = block(P);
        consume(P, TOK_OD, "expect OD");
        return n;
    }

    /* FOR */
    if (match(P, TOK_FOR)) {
        AstNode *n = ast_new(AST_FOR, P->previous.line);
        n->u.forstmt.init = declaration(P);
        consume(P, TOK_TO, "expect TO");
        n->u.forstmt.cond = expression(P);
        if (match(P, TOK_BY)) {
            n->u.forstmt.step = expression(P);
        }
        consume(P, TOK_DO, "expect DO");
        n->u.forstmt.body = block(P);
        consume(P, TOK_OD, "expect OD");
        return n;
    }

    /* PARALLEL */
    if (match(P, TOK_PARALLEL)) {
        AstNode *n = ast_new(AST_PARALLEL, P->previous.line);
        n->u.parallel.width = (int)expression(P)->u.number.ival;
        consume(P, TOK_DO, "expect DO");
        n->u.parallel.body = block(P);
        consume(P, TOK_OD, "expect OD");
        return n;
    }

    /* BARRIER */
    if (match(P, TOK_BARRIER)) {
        AstNode *n = ast_new(AST_BARRIER, P->previous.line);
        consume(P, TOK_LPAREN, "expect '('");
        n->u.barrier.id = (int)expression(P)->u.number.ival;
        consume(P, TOK_RPAREN, "expect ')'");
        match(P, TOK_SEMI);
        return n;
    }

    /* RETURN */
    if (match(P, TOK_RETURN)) {
        AstNode *n = ast_new(AST_RETURN, P->previous.line);
        if (!check(P, TOK_END) && !check(P, TOK_SEMI) && !check(P, TOK_FI) &&
            !check(P, TOK_ELSE) && !check(P, TOK_OD)) {
            n->u.ret.expr = expression(P);
        }
        match(P, TOK_SEMI);
        return n;
    }

    /* EXIT */
    if (match(P, TOK_EXIT)) {
        AstNode *n = ast_new(AST_EXIT, P->previous.line);
        match(P, TOK_SEMI);
        return n;
    }

    /* LABEL */
    if (match(P, TOK_LABEL)) {
        AstNode *n = ast_new(AST_LABEL, P->previous.line);
        consume(P, TOK_IDENT, "expect label name");
        n->u.ident.name = copy_lexeme(&P->previous);
        consume(P, TOK_COLON, "expect ':' after label");
        return n;
    }

    /* GOTO */
    if (match(P, TOK_GOTO)) {
        AstNode *n = ast_new(AST_GOTO, P->previous.line);
        consume(P, TOK_IDENT, "expect label name");
        n->u.ident.name = copy_lexeme(&P->previous);
        match(P, TOK_SEMI);
        return n;
    }

    /* BEGIN block */
    if (match(P, TOK_BEGIN)) {
        AstNode *n = block(P);
        consume(P, TOK_END, "expect END");
        return n;
    }

    /* declaration: LOCAL/OWN/GLOBAL/... TYPE name */
    if (check(P, TOK_LOCAL) || check(P, TOK_OWN) || check(P, TOK_GLOBAL) ||
        check(P, TOK_REGISTER) || check(P, TOK_SHARED) || check(P, TOK_PARAM) ||
        check(P, TOK_CONST) || check(P, TOK_ABSOLUTE) || check(P, TOK_BASED) ||
        check(P, TOK_WORD) || check(P, TOK_LONG) || check(P, TOK_BIT) ||
        check(P, TOK_BYTE) || check(P, TOK_FLOAT) || check(P, TOK_PRED)) {
        return declaration(P);
    }

    /* expression statement (assignment or call) */
    AstNode *e = expression(P);
    if (e && e->kind == AST_IDENT && match(P, TOK_ASSIGN)) {
        AstNode *n = ast_new(AST_ASSIGN, e->line);
        n->u.assign.lhs = e;
        n->u.assign.rhs = expression(P);
        match(P, TOK_SEMI);
        return n;
    }
    /* plain expression statement */
    AstNode *n = ast_new(AST_EXPR_STMT, e ? e->line : P->current.line);
    n->u.exprstmt.expr = e;
    match(P, TOK_SEMI);
    return n;
}

static AstNode *block(Parser *P) {
    AstNode *n = ast_new(AST_BLOCK, P->current.line);
    AstNode *stmts = NULL, *tail = NULL;
    while (!check(P, TOK_END) && !check(P, TOK_FI) &&
           !check(P, TOK_ELSE) && !check(P, TOK_OD) &&
           !check(P, TOK_EOF)) {
        AstNode *s = statement(P);
        if (s) {
            if (!stmts) stmts = tail = s;
            else { tail->next = s; tail = s; }
        }
    }
    n->u.block.stmts = stmts;
    return n;
}

/* ---------- Top-level ---------- */

void parser_init(Parser *P, Lexer *L) {
    P->lex = L;
    P->had_error = 0;
    P->panic = 0;
    advance(P);
}

AstNode *parse_module(Parser *P) {
    if (!match(P, TOK_MODULE)) {
        error(P, "expect MODULE");
        return NULL;
    }
    consume(P, TOK_IDENT, "expect module name");
    AstNode *n = ast_new(AST_MODULE, P->previous.line);
    n->u.module.name = copy_lexeme(&P->previous);

    /* optional module-level annotations */
    while (check(P, TOK_PRIORITY) || check(P, TOK_DEADLINE)) {
        advance(P);
        expression(P);
    }

    AstNode *decls = NULL, *dtail = NULL;
    AstNode *funcs = NULL, *ftail = NULL;

    while (!check(P, TOK_END) && !check(P, TOK_EOF)) {
        /* priority/deadline annotations */
        int prio = 0, dl = 0;
        while (check(P, TOK_PRIORITY) || check(P, TOK_DEADLINE)) {
            if (check(P, TOK_PRIORITY)) { advance(P); prio = (int)expression(P)->u.number.ival; }
            if (check(P, TOK_DEADLINE)) { advance(P); dl = (int)expression(P)->u.number.ival; }
        }

        if (match(P, TOK_ROUTINE)) {
            consume(P, TOK_IDENT, "expect routine name");
            AstNode *fn = ast_new(AST_ROUTINE, P->previous.line);
            fn->u.routine.name = copy_lexeme(&P->previous);
            fn->u.routine.priority = prio;
            fn->u.routine.deadline = dl;

            if (match(P, TOK_KERNEL))
                fn->u.routine.is_kernel = 1;

            consume(P, TOK_BEGIN, "expect BEGIN");
            fn->u.routine.body = block(P);
            consume(P, TOK_END, "expect END");

            if (!funcs) funcs = ftail = fn;
            else { ftail->next = fn; ftail = fn; }
        } else {
            AstNode *d = declaration(P);
            if (d) {
                if (!decls) decls = dtail = d;
                else { dtail->next = d; dtail = d; }
            }
        }
    }

    consume(P, TOK_END, "expect END (module)");
    match(P, TOK_SEMI);

    n->u.module.decls = decls;
    n->u.module.routines = funcs;
    return n;
}

void ast_free(AstNode *n) {
    /* production code would recurse and free all children */
    (void)n;
}

void ast_print(AstNode *n, int indent) {
    if (!n) return;
    for (int i = 0; i < indent; i++) printf("  ");
    switch (n->kind) {
    case AST_MODULE: printf("MODULE %s\n", n->u.module.name); break;
    case AST_ROUTINE: printf("ROUTINE %s%s\n", n->u.routine.name,
        n->u.routine.is_kernel ? " [KERNEL]" : ""); break;
    case AST_BLOCK: printf("BLOCK\n"); break;
    case AST_DECL: printf("DECL %s\n", n->u.decl.name); break;
    case AST_ASSIGN: printf("ASSIGN\n"); break;
    case AST_IF: printf("IF\n"); break;
    case AST_WHILE: printf("WHILE\n"); break;
    case AST_FOR: printf("FOR\n"); break;
    case AST_RETURN: printf("RETURN\n"); break;
    case AST_EXIT: printf("EXIT\n"); break;
    case AST_PARALLEL: printf("PARALLEL %d\n", n->u.parallel.width); break;
    case AST_BARRIER: printf("BARRIER(%d)\n", n->u.barrier.id); break;
    case AST_IDENT: printf("IDENT %s\n", n->u.ident.name); break;
    case AST_NUMBER: printf("NUMBER %ld\n", n->u.number.ival); break;
    case AST_BINARY: printf("BINARY op=%d\n", n->u.binary.op); break;
    case AST_UNARY: printf("UNARY op=%d\n", n->u.unary.op); break;
    case AST_CALL: printf("CALL\n"); break;
    case AST_BITFIELD: printf("BITFIELD off=%d wid=%d\n",
        n->u.bitfield.offset, n->u.bitfield.width); break;
    default: printf("NODE kind=%d\n", n->kind); break;
    }
    /* recurse into children (simplified) */
    if (n->kind == AST_MODULE) {
        ast_print(n->u.module.decls, indent + 1);
        ast_print(n->u.module.routines, indent + 1);
    }
    if (n->kind == AST_ROUTINE)
        ast_print(n->u.routine.body, indent + 1);
    if (n->kind == AST_BLOCK)
        ast_print(n->u.block.stmts, indent + 1);
    ast_print(n->next, indent);
}

#include "regalloc.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Dense interference-graph builder + greedy colouring.
   Live ranges are computed by a simple backward scan.
   No SSA, no LLVM, no external libraries. */

static void live_at(IrFunc *f, int *live, int n, IrInst *from) {
    memset(live, 0, n * sizeof(int));
    int seen_from = 0;
    for (IrInst *i = f->first; i; i = i->next) {
        if (i == from) seen_from = 1;
        if (!seen_from) continue;
        if (i->src0.kind == OP_REG && i->src0.reg < n) live[i->src0.reg] = 1;
        if (i->src1.kind == OP_REG && i->src1.reg < n) live[i->src1.reg] = 1;
        if (i->src2.kind == OP_REG && i->src2.reg < n) live[i->src2.reg] = 1;
        if (i->dst.kind == OP_REG && i->dst.reg < n) live[i->dst.reg] = 1;
    }
}

void build_interference(IrFunc *f, InterferenceGraph *g) {
    memset(g, 0, sizeof(*g));
    g->n_vregs = f->num_regs + 2;
    if (g->n_vregs > MAX_VREGS) g->n_vregs = MAX_VREGS;

    int live[MAX_VREGS];
    for (IrInst *i = f->first; i; i = i->next) {
        live_at(f, live, g->n_vregs, i);
        for (int a = 0; a < g->n_vregs; a++) {
            if (!live[a]) continue;
            for (int b = a + 1; b < g->n_vregs; b++) {
                if (!live[b]) continue;
                g->adj[a][b] = g->adj[b][a] = 1;
            }
        }
        if (i->dst.kind == OP_REG && i->dst.reg < g->n_vregs) {
            int d = i->dst.reg;
            for (int a = 0; a < g->n_vregs; a++)
                if (live[a] && a != d)
                    g->adj[d][a] = g->adj[a][d] = 1;
        }
    }

    for (int v = 0; v < g->n_vregs; v++) {
        int deg = 0;
        for (int u = 0; u < g->n_vregs; u++)
            if (g->adj[v][u]) deg++;
        g->degree[v] = deg;
        g->color[v] = -1;
        g->spill_cost[v] = 1 + deg;
        g->coalesced[v] = v;
    }
}

void color_graph(InterferenceGraph *g, int n_pregs) {
    int order[MAX_VREGS];
    for (int i = 0; i < g->n_vregs; i++) order[i] = i;

    /* insertion sort by degree descending */
    for (int i = 1; i < g->n_vregs; i++) {
        int key = order[i];
        int j = i - 1;
        while (j >= 0 && g->degree[order[j]] < g->degree[key]) {
            order[j+1] = order[j];
            j--;
        }
        order[j+1] = key;
    }

    for (int oi = 0; oi < g->n_vregs; oi++) {
        int v = order[oi];
        if (g->coalesced[v] != v) continue;

        char used[MAX_PREGS];
        memset(used, 0, sizeof(used));
        for (int u = 0; u < g->n_vregs; u++) {
            if (!g->adj[v][u]) continue;
            int c = g->color[g->coalesced[u]];
            if (c >= 0 && c < n_pregs) used[c] = 1;
        }
        int chosen = -1;
        for (int c = 0; c < n_pregs; c++)
            if (!used[c]) { chosen = c; break; }
        g->color[v] = chosen;
    }
}

void apply_colors(IrFunc *f, InterferenceGraph *g) {
    for (IrInst *i = f->first; i; i = i->next) {
        IrOperand *ops[4] = { &i->dst, &i->src0, &i->src1, &i->src2 };
        for (int k = 0; k < 4; k++) {
            if (ops[k]->kind != OP_REG) continue;
            int v = ops[k]->reg;
            if (v < 0 || v >= g->n_vregs) continue;
            int col = g->color[g->coalesced[v]];
            if (col >= 0)
                ops[k]->reg = col;
            else if (!i->comment) {
                char buf[48];
                snprintf(buf, sizeof(buf), "SPILL v%d", v);
                i->comment = strdup(buf);
            }
        }
    }
    f->num_regs = MAX_PREGS;
}

void graph_color_allocate(IrFunc *f) {
    if (!f || !f->first) return;
    InterferenceGraph g;
    build_interference(f, &g);
    color_graph(&g, MAX_PREGS);
    apply_colors(f, &g);
}

#include "symtab.h"
#include "ir.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static unsigned hash_name(const char *s) {
    unsigned h = 5381;
    while (*s) h = ((h << 5) + h) + (unsigned char)*s++;
    return h;
}

void symtab_init(SymTab *st) {
    memset(st, 0, sizeof(*st));
    st->next_reg = 1;
    st->next_pred = 0;
    st->next_slot = 0;
    symtab_push(st);
}

void symtab_push(SymTab *st) {
    if (st->scope_top >= MAX_SCOPES) {
        fprintf(stderr, "symtab: scope overflow\n");
        return;
    }
    Scope *sc = calloc(1, sizeof(Scope));
    sc->parent = st->current;
    sc->depth = st->current ? st->current->depth + 1 : 0;
    st->scopes[st->scope_top++] = sc;
    st->current = sc;
}

void symtab_pop(SymTab *st) {
    if (st->scope_top <= 1) return;
    Scope *sc = st->current;
    st->current = sc->parent;
    st->scope_top--;
    for (int i = 0; i < 64; i++) {
        Symbol *s = sc->symbols[i];
        while (s) {
            Symbol *n = s->next;
            free(s->name);
            free(s);
            s = n;
        }
    }
    free(sc);
}

Symbol *symtab_lookup(SymTab *st, const char *name) {
    for (Scope *sc = st->current; sc; sc = sc->parent) {
        unsigned h = hash_name(name) & 63;
        for (Symbol *s = sc->symbols[h]; s; s = s->next)
            if (strcmp(s->name, name) == 0)
                return s;
    }
    return NULL;
}

Symbol *symtab_lookup_current(SymTab *st, const char *name) {
    if (!st->current) return NULL;
    unsigned h = hash_name(name) & 63;
    for (Symbol *s = st->current->symbols[h]; s; s = s->next)
        if (strcmp(s->name, name) == 0)
            return s;
    return NULL;
}

Symbol *symtab_insert(SymTab *st, const char *name, Type *type, StorageClass sc) {
    if (symtab_lookup_current(st, name)) {
        fprintf(stderr, "symtab: redeclaration of '%s'\n", name);
        return NULL;
    }
    Symbol *sym = calloc(1, sizeof(Symbol));
    sym->name = strdup(name);
    sym->type = type;
    sym->storage = sc;
    sym->reg = -1;
    sym->pred = -1;
    sym->slot = -1;

    if (sc == STOR_REGISTER || sc == STOR_LOCAL || sc == STOR_OWN ||
        sc == STOR_PARAM) {
        if (type && type->kind == TYPE_BIT && type->bits <= 1) {
            sym->pred = st->next_pred++;
        } else {
            sym->reg = st->next_reg++;
        }
    } else if (sc == STOR_ABSOLUTE) {
        /* no register; address is absolute */
    } else if (sc == STOR_SHARED || sc == STOR_GLOBAL || sc == STOR_CONST) {
        sym->slot = st->next_slot++;
    }

    unsigned h = hash_name(name) & 63;
    sym->next = st->current->symbols[h];
    st->current->symbols[h] = sym;
    return sym;
}

void symtab_dump(SymTab *st, FILE *out) {
    fprintf(out, "=== Symbol Table ===\n");
    for (int i = 0; i < st->scope_top; i++) {
        Scope *sc = st->scopes[i];
        fprintf(out, "Scope depth %d:\n", sc->depth);
        for (int b = 0; b < 64; b++) {
            for (Symbol *s = sc->symbols[b]; s; s = s->next) {
                fprintf(out, "  %s stor=%d reg=%d pred=%d abs=%ld slot=%d\n",
                        s->name, s->storage, s->reg, s->pred,
                        s->absolute, s->slot);
            }
        }
    }
}

/* ---------- Linear-scan register allocator ---------- */

#define PHYS_REGS 32

typedef struct {
    int vreg;
    int start;
    int end;
    int preg;
    int slot;
} LiveInterval;

void allocate_registers(IrFunc *f, SymTab *st) {
    (void)st;
    if (!f || !f->first) return;

    int max_v = f->num_regs + 4;
    LiveInterval *iv = calloc(max_v, sizeof(LiveInterval));
    int n_iv = 0;

    int idx = 0;
    for (IrInst *i = f->first; i; i = i->next, idx++) {
        int regs[4] = {-1,-1,-1,-1};
        int nr = 0;
        if (i->dst.kind == OP_REG) regs[nr++] = i->dst.reg;
        if (i->src0.kind == OP_REG) regs[nr++] = i->src0.reg;
        if (i->src1.kind == OP_REG) regs[nr++] = i->src1.reg;
        if (i->src2.kind == OP_REG) regs[nr++] = i->src2.reg;

        for (int k = 0; k < nr; k++) {
            int r = regs[k];
            if (r < 0 || r >= max_v) continue;
            int found = -1;
            for (int j = 0; j < n_iv; j++)
                if (iv[j].vreg == r) { found = j; break; }
            if (found < 0) {
                iv[n_iv].vreg = r;
                iv[n_iv].start = idx;
                iv[n_iv].end = idx;
                iv[n_iv].preg = -1;
                iv[n_iv].slot = -1;
                n_iv++;
            } else {
                if (idx < iv[found].start) iv[found].start = idx;
                if (idx > iv[found].end) iv[found].end = idx;
            }
        }
    }

    /* Sort by start */
    for (int i = 1; i < n_iv; i++) {
        LiveInterval key = iv[i];
        int j = i - 1;
        while (j >= 0 && iv[j].start > key.start) {
            iv[j+1] = iv[j];
            j--;
        }
        iv[j+1] = key;
    }

    /* Linear scan */
    int active[PHYS_REGS];
    int n_active = 0;
    int free_pool[PHYS_REGS];
    int n_free = PHYS_REGS;
    for (int i = 0; i < PHYS_REGS; i++) free_pool[i] = i;
    int next_spill_slot = 0;

    for (int i = 0; i < n_iv; i++) {
        LiveInterval *cur = &iv[i];

        for (int a = 0; a < n_active; ) {
            int v = active[a];
            LiveInterval *liv = NULL;
            for (int k = 0; k < n_iv; k++)
                if (iv[k].vreg == v) { liv = &iv[k]; break; }
            if (liv && liv->end < cur->start) {
                if (liv->preg >= 0)
                    free_pool[n_free++] = liv->preg;
                active[a] = active[--n_active];
            } else {
                a++;
            }
        }

        if (n_free > 0) {
            cur->preg = free_pool[--n_free];
            active[n_active++] = cur->vreg;
        } else {
            int spill_idx = 0;
            int furthest = -1;
            for (int a = 0; a < n_active; a++) {
                for (int k = 0; k < n_iv; k++) {
                    if (iv[k].vreg == active[a] && iv[k].end > furthest) {
                        furthest = iv[k].end;
                        spill_idx = a;
                    }
                }
            }
            for (int k = 0; k < n_iv; k++) {
                if (iv[k].vreg == active[spill_idx]) {
                    iv[k].slot = next_spill_slot++;
                    iv[k].preg = -1;
                    break;
                }
            }
            cur->slot = next_spill_slot++;
            cur->preg = -1;
        }
    }

    /* Rewrite IR */
    for (IrInst *i = f->first; i; i = i->next) {
        IrOperand *ops[4] = {&i->dst, &i->src0, &i->src1, &i->src2};
        for (int k = 0; k < 4; k++) {
            if (ops[k]->kind != OP_REG) continue;
            int v = ops[k]->reg;
            for (int j = 0; j < n_iv; j++) {
                if (iv[j].vreg == v) {
                    if (iv[j].preg >= 0)
                        ops[k]->reg = iv[j].preg;
                    else {
                        if (!i->comment) {
                            char buf[64];
                            snprintf(buf, sizeof(buf), "spill slot %d", iv[j].slot);
                            i->comment = strdup(buf);
                        }
                    }
                    break;
                }
            }
        }
    }

    free(iv);
    f->num_regs = PHYS_REGS;
}

#include "compiler.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* Block 19: BSCL FRONTEND — the structured control/system layer.
 * BSCL shares the B grammar and pipeline; it adds deterministic
 * control constructs which the parser already accepts natively:
 *
 *   loop stmt until (cond);   : post-condition loop (desugared in parser)
 *   when (cond) stmt          : guarded statement (== if)
 *   atomic stmt               : cooperative section; between YIELDs a
 *                               process never interleaves, so a block
 *                               is already atomic — passed through.
 *
 * The layer below additionally strips `#` directive lines and rejects
 * anything else non-BSCL, then compiles through the common pipeline.
 * There is no separate BSCL runtime. */

bool bscl_to_b(const char *src, char **out_b, DiagList *diags,
               const char *file) {
    (void)diags; (void)file;
    size_t cap = strlen(src) + 64, len = 0;
    char *buf = malloc(cap);
    if (!buf) return false;
    int lineno = 0;
    char *copy = strdup(src);
    char *save = NULL;
    for (char *line = strtok_r(copy, "\n", &save); line;
         line = strtok_r(NULL, "\n", &save)) {
        lineno++;
        char *s = line;
        while (*s == ' ' || *s == '\t') s++;
        if (*s == '#') continue;              /* BSCL directive: host-only */
        size_t n = strlen(line);
        if (len + n + 2 > cap) {
            cap *= 2;
            buf = realloc(buf, cap);
            if (!buf) { free(copy); return false; }
        }
        memcpy(buf + len, line, n); len += n;
        buf[len++] = '\n';
    }
    buf[len] = 0;
    free(copy);
    *out_b = buf;
    return true;
}

