/* Block 24: CLI.
 * occamb build <src> [-o out.wc] compile to a wordcode image
 * occamb run <img.wc> [--trace] execute an image
 * occamb dump <img.wc> hex dump
 * occamb disassemble <img.wc> human-readable assembly
 * occamb check <src> compile only (diagnostics)
 * occamb selftest built-in VM verification suite
 * --help --version
 * Exit codes: 0 ok, 1 usage/compile, 3 deadlock, 4 runtime fault. */

static const char *VERSION = "occamb 1.0.0 (wordcode v1)";

static char *read_text_file(const char *path, size_t *n) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { /* short read ok */ }
    buf[sz] = 0;
    fclose(f);
    if (n) *n = (size_t)sz;
    return buf;
}

static void usage(FILE *out) {
    fprintf(out,
        "%s\n"
        "usage: occamb <command> [options]\n"
        " build <src> [-o out.wc] compile .b/.occ/.bscl to wordcode\n"
        " run <img.wc> [--trace] execute a wordcode image\n"
        " dump <img.wc> hex dump of the image\n"
        " disassemble <img.wc> wordcode disassembly\n"
        " check <src> compile only; print diagnostics\n"
        " selftest run built-in VM self-test\n"
        " --help this text\n"
        " --version version string\n", VERSION);
}

/* ---- Block 30: VM SELF-TEST ----------------------------------------
 * Hand-assembled program exercising: registers, arithmetic, branches,
 * stack, calls, memory alloc/free, channel communication, spawn,
 * WAIT join and HALT. R0 at HALT = 0 iff every check passed. */
static const struct { uint8_t op; uint32_t a, b, c; } SELFTEST[] = {
    /* arithmetic: 6*7 == 42 */
    { OP_CONST, R0, 0, 6 }, { OP_CONST, R1, 0, 7 }, { OP_MUL, R0, R1, 0 },
    { OP_CONST, R2, 0, 42 }, { OP_EQ, R0, R2, 0 }, { OP_JZ, 8, 0, 0 },
    { OP_CONST, R0, 0, 1 }, { OP_HALT, 0, 0, 0 },
    /* stack: push 5, pop into R3 */
    { OP_CONST, R0, 0, 5 }, { OP_PUSH, R0, 0, 0 }, { OP_POP, R3, 0, 0 },
    { OP_CONST, R4, 0, 5 }, { OP_EQ, R3, R4, 0 }, { OP_JZ, 16, 0, 0 },
    { OP_CONST, R0, 0, 2 }, { OP_HALT, 0, 0, 0 },
    /* call double(9) at 48 */
    { OP_CONST, R0, 0, 9 }, { OP_PUSH, R0, 0, 0 }, { OP_CALL, 48, 1, 1 },
    { OP_CONST, R2, 0, 18 }, { OP_EQ, R0, R2, 0 }, { OP_JZ, 24, 0, 0 },
    { OP_CONST, R0, 0, 3 }, { OP_HALT, 0, 0, 0 },
    /* memory: alloc 4 words, expect nonzero, free it */
    { OP_CONST, R0, 0, 4 }, { OP_ALLOC, R5, R0, 0 }, { OP_CONST, R1, 0, 0 },
    { OP_NE, R5, R1, 0 }, { OP_JZ, 31, 0, 0 },
    { OP_CONST, R0, 0, 4 }, { OP_HALT, 0, 0, 0 }, { OP_FREE, R5, 0, 0 },
    /* channels + spawn(worker at 52) + wait */
    { OP_CHAN, R6, 0, 0 }, { OP_PUSH, R6, 0, 0 }, { OP_SPAWN, 52, 1, 1 },
    { OP_PUSH, R0, 0, 0 }, { OP_CONST, R0, 0, 41 }, { OP_SEND, R6, R0, 0 },
    { OP_RECV, R6, 0, 0 }, { OP_POP, R1, 0, 0 }, { OP_WAIT, R1, 0, 0 },
    { OP_CONST, R2, 0, 42 }, { OP_EQ, R0, R2, 0 }, { OP_JZ, 46, 0, 0 },
    { OP_CONST, R0, 0, 5 }, { OP_HALT, 0, 0, 0 },
    { OP_CONST, R0, 0, 0 }, { OP_HALT, 0, 0, 0 },
    /* double(n): n*2 */
    { OP_LOAD, R0, 0, 0 }, { OP_CONST, R1, 0, 2 }, { OP_MUL, R0, R1, 0 },
    { OP_RET, 0, 0, 0 },
    /* worker(c): recv, +1, send back, exit 0 */
    { OP_LOAD, R5, 0, 0 }, { OP_RECV, R5, 0, 0 }, { OP_CONST, R1, 0, 1 },
    { OP_ADD, R0, R1, 0 }, { OP_SEND, R5, R0, 0 }, { OP_CONST, R0, 0, 0 },
    { OP_RET, 0, 0, 0 },
};

static int cmd_selftest(void) {
    WcImage img;
    wc_image_init(&img);
    size_t n = sizeof(SELFTEST) / sizeof(SELFTEST[0]);
    Word *code = malloc(n * sizeof(Word));
    for (size_t i = 0; i < n; i++)
        code[i] = wc_encode(SELFTEST[i].op, SELFTEST[i].a,
                            SELFTEST[i].b, SELFTEST[i].c);
    img.code = code; img.code_size = n;
    img.entry = 0; img.entry_frame_size = 1;
    VM *vm = vm_create(65536);
    if (!vm) { wc_image_free(&img); return 1; }
    bool loaded = vm_load_image(vm, &img);
    int rc = loaded ? vm_run(vm) : -1;
    bool pass = (rc == 0);
    printf("selftest: %s (exit=%d, steps=%llu)\n",
           pass ? "PASS" : "FAIL", rc,
           (unsigned long long)vm_steps(vm));
    if (!pass) printf(" error: %s\n", vm_error(vm));
    vm_destroy(vm);
    wc_image_free(&img);
    return pass ? 0 : 1;
}

static int cmd_build(const char *src, const char *out) {
    Compiler c;
    compiler_init(&c);
    WcImage img;
    int rc = compile_file(&c, src, &img);
    if (rc != 0) {
        diag_print(stderr, &c.diags);
        compiler_free(&c);
        return 1;
    }
    char err[128] = {0};
    FILE *f = fopen(out, "wb");
    if (!f) { fprintf(stderr, "cannot open '%s'\n", out);
              compiler_free(&c); return 1; }
    bool ok = wc_serialize(&img, f, err, sizeof(err));
    fclose(f);
    if (!ok) fprintf(stderr, "serialize: %s\n", err);
    printf("built %s -> %s (%zu code words, %zu data words)\n",
           src, out, img.code_size, img.data_size);
    wc_image_free(&img);
    compiler_free(&c);
    return ok ? 0 : 1;
}

static int load_image(const char *path, WcImage *img) {
    char err[160] = {0};
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open '%s'\n", path); return 1; }
    bool ok = wc_deserialize(img, f, err, sizeof(err));
    fclose(f);
    if (!ok) { fprintf(stderr, "%s: %s\n", path, err); return 1; }
    return 0;
}

static int cmd_run(const char *path, bool trace) {
    WcImage img;
    wc_image_init(&img);
    if (load_image(path, &img) != 0) return 1;
    VM *vm = vm_create(65536);
    if (!vm) { wc_image_free(&img); return 1; }
    vm_set_output(vm, stdout);
    if (!vm_load_image(vm, &img)) {
        fprintf(stderr, "%s\n", vm_error(vm));
        vm_destroy(vm); wc_image_free(&img); return 1;
    }
    if (trace) vm_set_trace(vm, stderr);
    int rc = vm_run(vm);
    if (rc != 0 && vm_error(vm)[0])
        fprintf(stderr, "vm: %s\n", vm_error(vm));
    vm_destroy(vm);
    wc_image_free(&img);
    return rc < 0 ? 1 : rc;
}

static int cmd_disassemble(const char *path) {
    WcImage img;
    wc_image_init(&img);
    if (load_image(path, &img) != 0) return 1;
    wc_disassemble(stdout, &img);
    wc_image_free(&img);
    return 0;
}

static int cmd_dump(const char *path) {
    size_t n;
    unsigned char *b = (unsigned char *)read_text_file(path, &n);
    if (!b) { fprintf(stderr, "cannot open '%s'\n", path); return 1; }
    for (size_t i = 0; i < n; i++) {
        if (i % 16 == 0) printf("%08zx ", i);
        printf("%02x ", b[i]);
        if (i % 16 == 15 || i == n - 1) putchar('\n');
    }
    free(b);
    return 0;
}

static int cmd_check(const char *src) {
    Compiler c;
    compiler_init(&c);
    WcImage img;
    int rc = compile_file(&c, src, &img);
    if (c.diags.count) diag_print(stderr, &c.diags);
    printf("%s: %s\n", src, rc == 0 ? "OK" : "FAILED");
    wc_image_free(&img);
    compiler_free(&c);
    return rc;
}

int main(int argc, char **argv) {
    if (argc < 2) { usage(stderr); return 1; }
    const char *cmd = argv[1];
    if (strcmp(cmd, "--help") == 0 || strcmp(cmd, "-h") == 0) {
        usage(stdout); return 0;
    }
    if (strcmp(cmd, "--version") == 0) { puts(VERSION); return 0; }
    if (strcmp(cmd, "selftest") == 0) return cmd_selftest();
    if (strcmp(cmd, "build") == 0 && argc >= 3) {
        const char *out = "out.wc";
        for (int i = 3; i + 1 < argc + 1 && i < argc; i++)
            if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) out = argv[i + 1];
        /* build with explicit -o handling */
        out = "out.wc";
        for (int i = 3; i + 1 < argc; i++)
            if (strcmp(argv[i], "-o") == 0) out = argv[i + 1];
        return cmd_build(argv[2], out);
    }
    if (strcmp(cmd, "run") == 0 && argc >= 3) {
        bool trace = argc > 3 && strcmp(argv[3], "--trace") == 0;
        return cmd_run(argv[2], trace);
    }
    if (strcmp(cmd, "disassemble") == 0 && argc >= 3) return cmd_disassemble(argv[2]);
    if (strcmp(cmd, "dump") == 0 && argc >= 3) return cmd_dump(argv[2]);
    if (strcmp(cmd, "check") == 0 && argc >= 3) return cmd_check(argv[2]);
    fprintf(stderr, "unknown command '%s'\n", cmd);
    usage(stderr);
    return 1;
}

#include "compiler.h"
#include "parser.h"
#include "types.h"
#include "wordcode.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

extern bool emit_wordcode(IRModule *m, FuncTab *ft, Compiler *comp,
                          WcImage *img, DiagList *dg);

/* Block 20: COMPILER — source -> lexer -> parser -> AST -> typecheck
 * -> IR -> Wordcode. Diagnostics carry file/line/column; any error
 * fails the compilation (fail-closed). */

void compiler_init(Compiler *c) {
    c->data = NULL; c->len = 0; c->cap = 0;
    diag_list_init(&c->diags);
}

void compiler_free(Compiler *c) {
    free(c->data);
    c->data = NULL; c->len = 0; c->cap = 0;
    diag_list_free(&c->diags);
}

static size_t data_append_bytes(Compiler *c, const char *s) {
    size_t off = c->len * 8;
    size_t n = strlen(s);
    for (size_t i = 0; i < n; i++) {
        size_t byte = off + i;
        size_t widx = byte / 8;
        while (widx >= c->cap) {
            size_t ncap = c->cap ? c->cap * 2 : 8;
            Word *nd = realloc(c->data, ncap * sizeof(Word));
            if (!nd) return off;
            memset(nd + c->cap, 0, (ncap - c->cap) * sizeof(Word));
            c->data = nd; c->cap = ncap;
        }
        if (widx >= c->len) { c->data[widx] = 0; c->len = widx + 1; }
        c->data[widx] |= ((Word)(unsigned char)s[i]) << ((byte % 8) * 8);
    }
    return off;
}

/* ---------------- AST -> IR ---------------- */

typedef struct {
    IRModule *m;
    FuncTab *ft;
    Compiler *comp;
    DiagList *dg;
    const char *file;
    SymTab locals;
    long labels;
    long break_stack[32];
    size_t nbreak;
    bool failed;
} Gen;

static long newlabel(Gen *g) { return g->labels++; }

static void gen_err(Gen *g, const Node *n, const char *msg) {
    diag_add(g->dg, D_ERROR, g->file, n->line, n->col, "%s", msg);
    g->failed = true;
}

static void emit(Gen *g, IROp op, long a, long b, long c, const char *note) {
    ir_emit(g->m, op, a, b, c, note);
}

static void gen_expr(Gen *g, Node *n);

/* comparisons set ZF=1 when TRUE; JZ jumps when ZF set */
static void materialize_bool(Gen *g) {
    long t = newlabel(g), e = newlabel(g);
    emit(g, IR_JZ, t, 0, 0, NULL);
    emit(g, IR_CONST, R0, 0, 0, NULL);
    emit(g, IR_JMP, e, 0, 0, NULL);
    ir_emit_label(g->m, t);
    emit(g, IR_CONST, R0, 1, 0, NULL);
    ir_emit_label(g->m, e);
}

/* emit condition: leaves ZF set iff the condition is true */
static void gen_cond(Gen *g, Node *n) {
    int op = (n && n->kind == N_BIN) ? (int)n->ival : 0;
    switch (op) {
    case TK_EQ: case TK_NE: case TK_LT: case TK_LE: case TK_GT: case TK_GE:
        gen_expr(g, n->a);
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        gen_expr(g, n->b);
        emit(g, IR_POP, R1, 0, 0, NULL);
        switch (op) {
        case TK_EQ: emit(g, IR_EQ, R1, R0, 0, NULL); break;
        case TK_NE: emit(g, IR_NE, R1, R0, 0, NULL); break;
        case TK_LT: emit(g, IR_LT, R1, R0, 0, NULL); break;
        case TK_LE: emit(g, IR_LE, R1, R0, 0, NULL); break;
        case TK_GT: emit(g, IR_GT, R1, R0, 0, NULL); break;
        default: emit(g, IR_GE, R1, R0, 0, NULL); break;
        }
        return;
    default:
        gen_expr(g, n);
        emit(g, IR_CONST, R1, 0, 0, NULL);
        emit(g, IR_NE, R0, R1, 0, NULL); /* ZF=1 iff R0 != 0 */
        return;
    }
}

static void gen_args_push(Gen *g, Node *args, size_t *argc) {
    *argc = 0;
    for (Node *a = args; a; a = a->next) {
        gen_expr(g, a);
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        (*argc)++;
    }
}

static void gen_call(Gen *g, Node *n) {
    if (strcmp(n->name, "chan") == 0) { emit(g, IR_CHAN, R0, 0, 0, NULL); return; }
    if (strcmp(n->name, "in") == 0) { emit(g, IR_IN, R0, 0, 0, NULL); return; }
    if (strcmp(n->name, "recv") == 0) { gen_expr(g, n->a); emit(g, IR_RECV, R0, 0, 0, NULL); return; }
    if (strcmp(n->name, "out") == 0) { gen_expr(g, n->a); emit(g, IR_OUT, R0, 0, 0, NULL); return; }
    if (strcmp(n->name, "wait") == 0) { gen_expr(g, n->a); emit(g, IR_WAIT, R0, 0, 0, NULL); return; }
    if (strcmp(n->name, "print") == 0) {
        size_t off = data_append_bytes(g->comp, n->a->str);
        emit(g, IR_OUTS, (long)off, (long)strlen(n->a->str), 0, NULL);
        return;
    }
    if (strcmp(n->name, "send") == 0) {
        gen_expr(g, n->a); /* channel */
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        gen_expr(g, n->a->next); /* value */
        emit(g, IR_POP, R1, 0, 0, NULL);
        emit(g, IR_SEND, R1, R0, 0, NULL);
        return;
    }
    if (strcmp(n->name, "alt2") == 0) {
        gen_expr(g, n->a); /* c1 -> R0 */
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        gen_expr(g, n->a->next); /* c2 -> R0 */
        emit(g, IR_POP, R1, 0, 0, NULL); /* R1=c1, R0=c2 */
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        emit(g, IR_POP, R2, 0, 0, NULL);
        long lto = newlabel(g), ldone = newlabel(g);
        emit(g, IR_ALT, R1, R2, lto, NULL);
        emit(g, IR_JMP, ldone, 0, 0, NULL);
        ir_emit_label(g->m, lto);
        emit(g, IR_CONST, R0, 0, 0, NULL); /* timeout: value 0 */
        emit(g, IR_CONST, R1, 2, 0, NULL); /* index 2 */
        ir_emit_label(g->m, ldone);
        emit(g, IR_CONST, R2, 32, 0, NULL);
        emit(g, IR_SHL, R1, R2, 0, NULL); /* R1 = index << 32 */
        emit(g, IR_OR, R0, R1, 0, NULL); /* R0 = idx|value */
        return;
    }
    /* user function */
    size_t argc;
    gen_args_push(g, n->a, &argc);
    int fi = functab_lookup(g->ft, n->name);
    if (fi < 0) { gen_err(g, n, "call to unknown function"); return; }
    emit(g, IR_CALL, g->ft->fns[fi].label, (long)argc, 0, n->name);
}

static void gen_expr(Gen *g, Node *n) {
    if (!n || g->failed) return;
    switch (n->kind) {
    case N_INT:
        if (n->ival > 0xFFFFFFFFFFULL) { gen_err(g, n, "integer literal exceeds 40-bit immediate"); return; }
        emit(g, IR_CONST, R0, (long)n->ival, 0, NULL);
        return;
    case N_VAR:
        emit(g, IR_LOAD, R0, (long)n->ival, 0, n->name);
        return;
    case N_UNARY:
        if (n->ival == '-') {
            gen_expr(g, n->a);
            emit(g, IR_PUSH, R0, 0, 0, NULL);
            emit(g, IR_CONST, R0, 0, 0, NULL);
            emit(g, IR_POP, R1, 0, 0, NULL);
            emit(g, IR_SUB, R0, R1, 0, NULL);
        } else if (n->ival == '~') {
            gen_expr(g, n->a);
            emit(g, IR_NOT, R0, 0, 0, NULL);
        } else { /* '!' : R0 = (x == 0) */
            gen_expr(g, n->a);
            emit(g, IR_CONST, R1, 0, 0, NULL);
            emit(g, IR_EQ, R0, R1, 0, NULL);
            materialize_bool(g);
        }
        return;
    case N_BIN: {
        int op = (int)n->ival;
        if (op == TK_ANDAND || op == TK_OROR) {
            gen_expr(g, n->a);
            emit(g, IR_BOOL, R0, 0, 0, NULL);
            emit(g, IR_PUSH, R0, 0, 0, NULL);
            gen_expr(g, n->b);
            emit(g, IR_BOOL, R0, 0, 0, NULL);
            emit(g, IR_POP, R1, 0, 0, NULL);
            emit(g, op == TK_ANDAND ? IR_AND : IR_OR, R1, R0, 0, NULL);
            emit(g, IR_CONST, R0, 0, 0, NULL);
            emit(g, IR_ADD, R0, R1, 0, NULL);
            return;
        }
        gen_expr(g, n->a);
        emit(g, IR_PUSH, R0, 0, 0, NULL);
        gen_expr(g, n->b);
        emit(g, IR_POP, R1, 0, 0, NULL); /* R1 = left, R0 = right */
        switch (op) {
        case TK_EQ: case TK_NE: case TK_LT: case TK_LE: case TK_GT: case TK_GE:
            switch (op) {
            case TK_EQ: emit(g, IR_EQ, R1, R0, 0, NULL); break;
            case TK_NE: emit(g, IR_NE, R1, R0, 0, NULL); break;
            case TK_LT: emit(g, IR_LT, R1, R0, 0, NULL); break;
            case TK_LE: emit(g, IR_LE, R1, R0, 0, NULL); break;
            case TK_GT: emit(g, IR_GT, R1, R0, 0, NULL); break;
            default: emit(g, IR_GE, R1, R0, 0, NULL); break;
            }
            materialize_bool(g);
            return;
        case TK_PLUS: emit(g, IR_ADD, R1, R0, 0, NULL); break;
        case TK_MINUS: emit(g, IR_SUB, R1, R0, 0, NULL); break;
        case TK_STAR: emit(g, IR_MUL, R1, R0, 0, NULL); break;
        case TK_SLASH: emit(g, IR_DIV, R1, R0, 0, NULL); break;
        case TK_PERCENT: emit(g, IR_MOD, R1, R0, 0, NULL); break;
        case TK_AMP: emit(g, IR_AND, R1, R0, 0, NULL); break;
        case TK_PIPE: emit(g, IR_OR, R1, R0, 0, NULL); break;
        case TK_CARET: emit(g, IR_XOR, R1, R0, 0, NULL); break;
        case TK_SHL: emit(g, IR_SHL, R1, R0, 0, NULL); break;
        default: emit(g, IR_SHR, R1, R0, 0, NULL); break;
        }
        emit(g, IR_CONST, R0, 0, 0, NULL);
        emit(g, IR_ADD, R0, R1, 0, NULL); /* R0 = R1 */
        return;
    }
    case N_CALL:
        gen_call(g, n);
        return;
    case N_SPAWN: {
        size_t argc;
        gen_args_push(g, n->a, &argc);
        int fi = functab_lookup(g->ft, n->name);
        if (fi < 0) { gen_err(g, n, "spawn of unknown process"); return; }
        emit(g, IR_SPAWN, g->ft->fns[fi].label, (long)argc, 0, n->name);
        return;
    }
    default:
        gen_err(g, n, "node not valid in expression");
        return;
    }
}

static void gen_stmt(Gen *g, Node *n) {
    if (!n || g->failed) return;
    switch (n->kind) {
    case N_BLOCK:
        for (Node *s = n->a; s; s = s->next) gen_stmt(g, s);
        return;
    case N_ASSIGN: {
        gen_expr(g, n->a);
        int i = symtab_lookup(&g->locals, n->name);
        if (i < 0) {
            symtab_add(&g->locals, n->name, T_WORD, (Word)g->locals.count);
            i = (int)g->locals.count - 1;
        }
        emit(g, IR_STORE, (long)g->locals.syms[i].slot, R0, 0, n->name);
        return;
    }
    case N_IF: {
        long lt = newlabel(g), le = newlabel(g), ld = newlabel(g);
        gen_cond(g, n->a);
        emit(g, IR_JZ, lt, 0, 0, NULL);
        emit(g, IR_JMP, le, 0, 0, NULL);
        ir_emit_label(g->m, lt);
        gen_stmt(g, n->b);
        emit(g, IR_JMP, ld, 0, 0, NULL);
        ir_emit_label(g->m, le);
        gen_stmt(g, n->c);
        ir_emit_label(g->m, ld);
        return;
    }
    case N_WHILE: {
        long ls = newlabel(g), lb = newlabel(g), le = newlabel(g);
        if (g->nbreak < 32) g->break_stack[g->nbreak++] = le; else gen_err(g, n, "break stack overflow");
        ir_emit_label(g->m, ls);
        gen_cond(g, n->a);
        emit(g, IR_JZ, lb, 0, 0, NULL);
        emit(g, IR_JMP, le, 0, 0, NULL);
        ir_emit_label(g->m, lb);
        gen_stmt(g, n->b);
        emit(g, IR_JMP, ls, 0, 0, NULL);
        ir_emit_label(g->m, le);
        if (g->nbreak) g->nbreak--;
        return;
    }
    case N_BREAK:
        if (g->nbreak == 0) { gen_err(g, n, "break outside loop"); return; }
        emit(g, IR_JMP, g->break_stack[g->nbreak - 1], 0, 0, NULL);
        return;
    case N_RETURN:
        if (n->a) gen_expr(g, n->a); else emit(g, IR_CONST, R0, 0, 0, NULL);
        emit(g, IR_RET, 0, 0, 0, NULL);
        return;
    case N_CALL:
    case N_SPAWN:
        gen_expr(g, n); /* result ignored; stack balanced */
        return;
    default:
        gen_err(g, n, "node not valid as statement");
        return;
    }
}

static void gen_func(Gen *g, Node *f) {
    int fi = functab_lookup(g->ft, f->name);
    symtab_init(&g->locals);
    Word slot = 0;
    for (Node *p = f->a; p; p = p->next, slot++)
        symtab_add(&g->locals, p->name, T_WORD, slot);
    g->nbreak = 0;
    ir_emit_label(g->m, g->ft->fns[fi].label);
    gen_stmt(g, f->b);
    emit(g, IR_CONST, R0, 0, 0, NULL); /* implicit return 0 */
    emit(g, IR_RET, 0, 0, 0, NULL);
}

/* ---------------- pipeline ---------------- */

bool compile_source(Compiler *c, const char *src, const char *file,
                    WcImage *img) {
    wc_image_init(img);
    TokenStream ts;
    if (!lexer_tokenize(src, file, &ts, &c->diags)) {
        token_stream_free(&ts);
        return false;
    }
    Node *prog = NULL;
    if (!parse_program(&ts, &c->diags, &prog)) {
        token_stream_free(&ts);
        return false;
    }
    token_stream_free(&ts);

    FuncTab ft;
    if (!typecheck_program(prog, &ft, &c->diags, file)) {
        ast_free(prog);
        return false;
    }

    IRModule m;
    ir_module_init(&m);
    Gen g;
    g.m = &m; g.ft = &ft; g.comp = c; g.dg = &c->diags; g.file = file;
    g.labels = 0; g.nbreak = 0; g.failed = false;
    symtab_init(&g.locals);

    for (Node *f = prog->a; f && !g.failed; f = f->next)
        gen_func(&g, f);

    bool ok = !g.failed && c->diags.error_count == 0;
    if (ok) ok = emit_wordcode(&m, &ft, c, img, &c->diags);

    ir_module_free(&m);
    ast_free(prog);
    return ok;
}

int compile_file(Compiler *c, const char *path, WcImage *img) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        diag_add(&c->diags, D_ERROR, path, 0, 0, "cannot open source file");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *src = malloc((size_t)n + 1);
    if (!src) { fclose(f); return 1; }
    if (fread(src, 1, (size_t)n, f) != (size_t)n) { /* tolerate short read */ }
    src[n] = 0;
    fclose(f);

    /* dialect selection by extension (Blocks 18/19) */
    const char *dot = strrchr(path, '.');
    char *bsrc = NULL;
    bool ok;
    if (dot && strcmp(dot, ".occ") == 0) {
        ok = occam_to_b(src, &bsrc, &c->diags, path);
        if (ok) ok = compile_source(c, bsrc, path, img);
        free(bsrc);
    } else if (dot && strcmp(dot, ".bscl") == 0) {
        ok = bscl_to_b(src, &bsrc, &c->diags, path);
        if (ok) ok = compile_source(c, bsrc, path, img);
        free(bsrc);
    } else {
        ok = compile_source(c, src, path, img);
    }
    free(src);
    return ok ? 0 : 1;
}

#include "ir.h"
#include "compiler.h"
#include "types.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* Block 20 (backend half): IR -> Wordcode.
 * Two passes: (1) assign code addresses to labels, (2) emit packed
 * instructions, resolving labels, CALL/SPAWN frame sizes and ALT
 * timeout offsets. Fails closed on unresolved labels or bad targets. */

static int ir_to_wc(IROp op) {
    switch (op) {
    case IR_NOP: return OP_NOP; case IR_CONST: return OP_CONST;
    case IR_LOAD: return OP_LOAD; case IR_STORE: return OP_STORE;
    case IR_PUSH: return OP_PUSH; case IR_POP: return OP_POP;
    case IR_DROP: return OP_DROP; case IR_DUP: return OP_DUP;
    case IR_ADD: return OP_ADD; case IR_SUB: return OP_SUB;
    case IR_MUL: return OP_MUL; case IR_DIV: return OP_DIV;
    case IR_MOD: return OP_MOD; case IR_AND: return OP_AND;
    case IR_OR: return OP_OR; case IR_XOR: return OP_XOR;
    case IR_NOT: return OP_NOT; case IR_SHL: return OP_SHL;
    case IR_SHR: return OP_SHR; case IR_BOOL: return OP_BOOL;
    case IR_EQ: return OP_EQ; case IR_NE: return OP_NE;
    case IR_LT: return OP_LT; case IR_LE: return OP_LE;
    case IR_GT: return OP_GT; case IR_GE: return OP_GE;
    case IR_JMP: return OP_JMP; case IR_JZ: return OP_JZ;
    case IR_JNZ: return OP_JNZ; case IR_CALL: return OP_CALL;
    case IR_RET: return OP_RET; case IR_SPAWN: return OP_SPAWN;
    case IR_SEND: return OP_SEND; case IR_RECV: return OP_RECV;
    case IR_ALT: return OP_ALT; case IR_WAIT: return OP_WAIT;
    case IR_YIELD: return OP_YIELD; case IR_ALLOC: return OP_ALLOC;
    case IR_FREE: return OP_FREE; case IR_IN: return OP_IN;
    case IR_OUT: return OP_OUT; case IR_OUTS: return OP_OUTS;
    case IR_CHAN: return OP_CHAN; case IR_HALT: return OP_HALT;
    default: return -1;
    }
}

static const FuncEnt *func_by_label(const FuncTab *ft, long label) {
    for (size_t i = 0; i < ft->count; i++)
        if (ft->fns[i].label == label) return &ft->fns[i];
    return NULL;
}

bool emit_wordcode(IRModule *m, FuncTab *ft, Compiler *comp,
                   WcImage *img, DiagList *dg) {
    /* pass 1: label addresses */
    size_t addr = 0, nlabels = 0;
    for (size_t i = 0; i < m->count; i++) {
        if (m->items[i].op == IR_LABEL) {
            if (m->items[i].a + 1 > (long)nlabels) nlabels = (size_t)(m->items[i].a + 1);
        } else addr++;
    }
    long *laddr = calloc(nlabels ? nlabels : 1, sizeof(long));
    if (!laddr) { diag_add(dg, D_ERROR, "<emit>", 0, 0, "out of memory"); return false; }
    addr = 0;
    for (size_t i = 0; i < m->count; i++) {
        if (m->items[i].op == IR_LABEL) laddr[m->items[i].a] = (long)addr;
        else addr++;
    }
    size_t code_words = addr;
    Word *code = calloc(code_words ? code_words : 1, sizeof(Word));
    if (!code) { free(laddr); diag_add(dg, D_ERROR, "<emit>", 0, 0, "out of memory"); return false; }

    /* pass 2: emit */
    addr = 0;
    bool ok = true;
    for (size_t i = 0; i < m->count && ok; i++) {
        IRInstr *in = &m->items[i];
        if (in->op == IR_LABEL) continue;
        int wop = ir_to_wc(in->op);
        if (wop < 0) {
            diag_add(dg, D_ERROR, "<emit>", 0, 0, "no wordcode for IR op %d", in->op);
            ok = false; break;
        }
        uint32_t a = (uint32_t)in->a, b = (uint32_t)in->b, c = (uint32_t)in->c;
        switch (in->op) {
        case IR_CONST: /* a=reg, b=imm40 */
            code[addr++] = wc_encode(OP_CONST, a, (uint32_t)(in->b >> 20),
                                     (uint32_t)(in->b & 0xFFFFF));
            continue;
        case IR_JMP: case IR_JZ: case IR_JNZ:
            if (in->a < 0 || (size_t)in->a >= nlabels) { ok = false;
                diag_add(dg, D_ERROR, "<emit>", 0, 0, "jump to undefined label %ld", in->a); break; }
            a = (uint32_t)laddr[in->a];
            break;
        case IR_CALL: case IR_SPAWN: { /* a=func label, b=argc */
            const FuncEnt *f = func_by_label(ft, in->a);
            if (!f) { ok = false;
                diag_add(dg, D_ERROR, "<emit>", 0, 0, "call to unresolved function '%s'", in->note); break; }
            a = (uint32_t)laddr[in->a];
            c = (uint32_t)f->frame_size;
            break; }
        case IR_ALT: /* c = timeout label -> rel offset */
            if (in->c < 0 || (size_t)in->c >= nlabels) { ok = false;
                diag_add(dg, D_ERROR, "<emit>", 0, 0, "ALT timeout label undefined"); break; }
            c = (uint32_t)(laddr[in->c] - (long)addr - 1);
            break;
        default: break;
        }
        if (!ok) break;
        code[addr++] = wc_encode((uint8_t)wop, a, b, c);
    }
    free(laddr);
    if (!ok) { free(code); return false; }

    int mi = functab_lookup(ft, "main");
    if (mi < 0) { free(code);
        diag_add(dg, D_ERROR, "<emit>", 0, 0, "no main function"); return false; }

    wc_image_free(img);
    img->code = code; img->code_size = code_words;
    img->data = comp->data ? malloc(comp->len * sizeof(Word)) : NULL;
    if (comp->len) memcpy(img->data, comp->data, comp->len * sizeof(Word));
    img->data_size = comp->len;
    img->entry = 0;
    /* entry address: find main's label */
    for (size_t i = 0; i < m->count; i++)
        if (m->items[i].op == IR_LABEL && m->items[i].a == ft->fns[mi].label)
            img->entry = 0; /* patched below */
    /* recompute via laddr would be cleaner; do a mini pass: */
    {
        size_t ad = 0;
        for (size_t i = 0; i < m->count; i++) {
            if (m->items[i].op == IR_LABEL) {
                if (m->items[i].a == ft->fns[mi].label) { img->entry = ad; break; }
            } else ad++;
        }
    }
    img->entry_frame_size = ft->fns[mi].frame_size;
    if (img->entry >= img->code_size) {
        diag_add(dg, D_ERROR, "<emit>", 0, 0, "main entry out of range");
        return false;
    }
    return true;
}

#include "ir.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* Block 17: COMMON IR — a growable instruction vector independent of
 * any frontend AST. Labels are dense integer ids resolved by the
 * emitter; CALL/SPAWN reference functions by label. */

void ir_module_init(IRModule *m) {
    m->items = NULL; m->count = 0; m->cap = 0;
    m->entry = -1; m->entry_frame_size = 0;
}

void ir_module_free(IRModule *m) {
    free(m->items);
    m->items = NULL; m->count = 0; m->cap = 0;
}

static bool ir_grow(IRModule *m) {
    if (m->count < m->cap) return true;
    size_t ncap = m->cap ? m->cap * 2 : 64;
    IRInstr *n = realloc(m->items, ncap * sizeof(IRInstr));
    if (!n) return false;
    m->items = n; m->cap = ncap;
    return true;
}

size_t ir_emit(IRModule *m, IROp op, long a, long b, long c, const char *note) {
    if (!ir_grow(m)) return (size_t)-1;
    IRInstr *in = &m->items[m->count];
    in->op = op; in->a = a; in->b = b; in->c = c;
    snprintf(in->note, sizeof(in->note), "%s", note ? note : "");
    return m->count++;
}

size_t ir_emit_label(IRModule *m, long label_id) {
    return ir_emit(m, IR_LABEL, label_id, 0, 0, "label");
}

size_t ir_count(const IRModule *m) { return m->count; }

static const char *ir_op_name(IROp op) {
    static const char *names[] = {
        "NOP","LABEL","CONST","LOAD","STORE","PUSH","POP","DROP","DUP",
        "ADD","SUB","MUL","DIV","MOD","AND","OR","XOR","NOT","SHL","SHR","BOOL",
        "EQ","NE","LT","LE","GT","GE",
        "JMP","JZ","JNZ","CALL","RET","SPAWN","SEND","RECV",
        "ALT","WAIT","YIELD","ALLOC","FREE","IN","OUT","OUTS","CHAN","HALT"
    };
    if (op < 0 || op > IR_HALT) return "?";
    return names[op];
}

void ir_dump(FILE *out, const IRModule *m) {
    for (size_t i = 0; i < m->count; i++) {
        const IRInstr *in = &m->items[i];
        fprintf(out, "%04zu %-6s %ld %ld %ld %s\n", i, ir_op_name(in->op),
                in->a, in->b, in->c, in->note);
    }
}

/* tests/test_channels.c */
#include "channel.h"
#include "process.h"
#include <stdio.h>
#include <string.h>
static int fails = 0;
#define CHECK(cond) do { if (!(cond)) { \
    printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); fails++; } } while (0)

static Process *woken_pid;
static Process *wake_cb(ProcessID pid, void *ctx) {
    (void)pid; (void)ctx;
    return woken_pid; /* test stubs return the pre-set process */
}

int main(void) {
    ChannelTable *t = chtab_create(8, 2); /* cap-2 queues */
    int c = chan_create(t);
    CHECK(c >= 0);

    /* simple enqueue/dequeue without processes */
    CHECK(chan_send(t, c, 111, NULL, NULL, NULL) == CHAN_OK);
    CHECK(chan_send(t, c, 222, NULL, NULL, NULL) == CHAN_OK);
    Word v = 0;
    CHECK(chan_recv(t, c, &v, NULL, NULL, NULL) == CHAN_OK && v == 111);
    CHECK(chan_recv(t, c, &v, NULL, NULL, NULL) == CHAN_OK && v == 222);

    /* queue full -> sender blocks; staged value lives in R1 */
    Process *sender = proc_create(1, "s", 64);
    sender->regs[R1] = 333;
    CHECK(chan_send(t, c, 111, NULL, NULL, NULL) == CHAN_OK);
    CHECK(chan_send(t, c, 222, NULL, NULL, NULL) == CHAN_OK);
    CHECK(chan_send(t, c, 333, sender, wake_cb, NULL) == CHAN_BLOCKED);
    /* recv refills from blocked sender and wakes it */
    Process *r = proc_create(2, "r", 64);
    woken_pid = sender;
    CHECK(chan_recv(t, c, &v, NULL, wake_cb, NULL) == CHAN_OK && v == 111);
    CHECK(sender->status == PS_READY || sender->status == PS_RUNNING);
    CHECK(chan_recv(t, c, &v, NULL, NULL, NULL) == CHAN_OK && v == 222);
    CHECK(chan_recv(t, c, &v, NULL, NULL, NULL) == CHAN_OK && v == 333);

    /* closed channel: send fails, recv-on-empty fails */
    int c2 = chan_create(t);
    CHECK(chan_close(t, c2) == 0);
    CHECK(chan_send(t, c2, 1, NULL, NULL, NULL) == CHAN_ERROR);
    CHECK(chan_recv(t, c2, &v, NULL, NULL, NULL) == CHAN_ERROR);

    /* invalid channel */
    CHECK(chan_send(t, 77, 1, NULL, NULL, NULL) == CHAN_ERROR);
    CHECK(chan_ready(t, c) == false);

    proc_destroy(sender); proc_destroy(r);
    chtab_destroy(t);
    printf("test_channels: %s\n", fails ? "FAIL" : "PASS");
    return fails ? 1 : 0;
}

/* tests/test_compiler.c */
#include "compiler.h"
#include "vm.h"
#include <stdio.h>
#include <string.h>
static int fails = 0;
#define CHECK(cond) do { if (!(cond)) { \
    printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); fails++; } } while (0)

static int compile_ok(const char *src) {
    Compiler c; compiler_init(&c);
    WcImage img; wc_image_init(&img);
    bool ok = compile_source(&c, src, "test.b", &img);
    int errs = c.diags.error_count;
    wc_image_free(&img); compiler_free(&c);
    return ok && errs == 0;
}

static char *run_src(const char *src, int *rc) {
    Compiler c; compiler_init(&c);
    WcImage img; wc_image_init(&img);
    static char buf[8192];
    if (!compile_source(&c, src, "test.b", &img)) {
        *rc = -1; strcpy(buf, "<compile error>");
        wc_image_free(&img); compiler_free(&c);
        return buf;
    }
    VM *vm = vm_create(65536);
    FILE *f = tmpfile();
    vm_set_output(vm, f);
    vm_load_image(vm, &img);
    *rc = vm_run(vm);
    vm_destroy(vm);
    rewind(f);
    size_t r = fread(buf, 1, sizeof(buf) - 1, f);
    buf[r] = 0; fclose(f);
    wc_image_free(&img); compiler_free(&c);
    return buf;
}

int main(void) {
    int rc;
    /* arithmetic */
    char *o = run_src("main() { x = 10; y = 20; z = x + y; out(z); }", &rc);
    CHECK(rc == 0 && strcmp(o, "30\n") == 0);

    /* recursion: factorial(5) = 120 */
    o = run_src("fact(n) { if (n < 2) { return 1; } return n * fact(n - 1); }"
                "main() { out(fact(5)); }", &rc);
    CHECK(rc == 0 && strcmp(o, "120\n") == 0);

    /* iteration: fib(10) = 55 */
    o = run_src("fib(n) { a = 0; b = 1; i = 0; while (i < n) { t = a + b; "
                "a = b; b = t; i = i + 1; } return a; }"
                "main() { out(fib(10)); }", &rc);
    CHECK(rc == 0 && strcmp(o, "55\n") == 0);

    /* channels + spawn + wait, deterministic output */
    o = run_src(
        "producer(c) { i = 0; while (i < 5) { send(c, i * 10); i = i + 1; } }\n"
        "main() { c = chan(); p = spawn producer(c); i = 0; "
        "while (i < 5) { out(recv(c)); i = i + 1; } wait(p); }", &rc);
    CHECK(rc == 0 && strcmp(o, "0\n10\n20\n30\n40\n") == 0);

    /* alt2 deterministic left-first selection */
    o = run_src("main() { a = chan(); b = chan(); send(a, 11); send(b, 22);"
                " r = alt2(a, b); out(r >> 32); out(r & 4294967295); }", &rc);
    CHECK(rc == 0 && strcmp(o, "0\n11\n") == 0);

    /* BSCL structured control */
    o = run_src("main() { i = 0; loop { i = i + 1; } until (i >= 4); out(i);"
                " when (i == 4) { out(99); } }", &rc);
    CHECK(rc == 0 && strcmp(o, "4\n99\n") == 0);

    /* strings */
    o = run_src("main() { print(\"hello, wordcode\"); out(42); }", &rc);
    CHECK(rc == 0 && strcmp(o, "hello, wordcode\n42\n") == 0);

    /* ---- negative tests: compiler must fail closed ---- */
    CHECK(!compile_ok("main() { x = y + 1; }")); /* undefined var */
    CHECK(!compile_ok("main() { x = 1; send(x, 2); }")); /* send on word */
    CHECK(!compile_ok("main() { x = 1; y = recv(x); }")); /* recv on word */
    CHECK(!compile_ok("f(a) { return a; } main() { out(f(1, 2)); }")); /* argc */
    CHECK(!compile_ok("main() { out(nosuch()); }")); /* unknown fn */
    CHECK(!compile_ok("main() { x = ; }")); /* syntax */
    CHECK(!compile_ok("f() { return 1; } g() { return 2; }"))/* no main */;

    /* runtime fault: division by zero */
    o = run_src("main() { x = 1; y = 0; out(x / y); }", &rc);
    CHECK(rc == 4);

    /* explicit wait join ordering */
    o = run_src("child() { return 7; } main() { p = spawn child();"
                " wait(p); print(\"joined\"); }", &rc);
    CHECK(rc == 0 && strcmp(o, "joined\n") == 0);

    printf("test_compiler: %s\n", fails ? "FAIL" : "PASS");
    return fails ? 1 : 0;
}

/* tests/test_ir.c */
#include "ir.h"
#include <stdio.h>
static int fails = 0;
#define CHECK(cond) do { if (!(cond)) { \
    printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); fails++; } } while (0)

int main(void) {
    IRModule m;
    ir_module_init(&m);
    ir_emit(&m, IR_CONST, R0, 42, 0, NULL);
    ir_emit_label(&m, 0);
    ir_emit(&m, IR_OUT, R0, 0, 0, NULL);
    ir_emit(&m, IR_HALT, 0, 0, 0, NULL);
    CHECK(ir_count(&m) == 4);
    /* growth beyond initial capacity */
    for (int i = 0; i < 1000; i++) ir_emit(&m, IR_NOP, 0, 0, 0, NULL);
    CHECK(ir_count(&m) == 1004);
    /* labels are recorded as IR items */
    bool saw_label = false;
    for (size_t i = 0; i < m.count; i++)
