    FILE *f = tmpfile();
    ir_dump(f, &m);
    fclose(f);
    ir_module_free(&m);
    CHECK(m.items == NULL);
    printf("test_ir: %s\n", fails ? "FAIL" : "PASS");
    return fails ? 1 : 0;
}

