struct Tensor4Bit {
    const uint8_t* packed;
    const uint16_t* scales;
    size_t N;
    size_t K;
    size_t G;
};

inline void assert_shape(const Tensor4Bit& t) {
    assert(t.packed != nullptr && t.scales != nullptr);
    assert(t.K % 2 == 0);
    assert(t.K % t.G == 0);
    assert(t.N > 0 && t.K > 0);
}

inline float dequant(const Tensor4Bit& t, size_t n, size_t k) {
    assert(n < t.N);
    assert(k < t.K);
    size_t byte_idx = n * (t.K / 2) + (k >> 1);
    uint8_t b = t.packed[byte_idx];
    int nib = (k & 1u) ? (int)(b >> 4) : (int)(b & 0x0F);
    if (nib >= 8) nib -= 16;
    float s = (float)t.scales[n * (t.K / t.G) + (k / t.G)];
    return (float)nib * s;
}

}  // namespace afm::safety

/*
 * TLM JXCL ISA — ALU function contracts
 * Frama-C / ACSL formal specification  (Frama-C 26+ / E-ACSL)
 *
 * This is a contract-only header.  No implementation is provided here;
 * the contracts serve as checked specifications for the ALU implementation.
 *
 * Flag register layout (packed into Flags struct):
 *   z  — zero:             result == 0
 *   n  — negative:         MSB of result is 1 (i.e. >= 0x8000000000000000)
 *   c  — carry / borrow:   unsigned overflow for add; borrow for sub
 *   v  — signed overflow:  the signed result does not fit in int64_t
 *
 * ACSL integer arithmetic in ensures clauses uses mathematical integers
 * (unbounded), so expressions like  a + b > 0xFFFFFFFFFFFFFFFF  are well
 * formed and detect 64-bit unsigned overflow without wrapping.
 */

#ifndef ALU_CONTRACTS_H
#define ALU_CONTRACTS_H

#include <stdint.h>
#include <stdbool.h>

/* -------------------------------------------------------------------------
 * Flag register
 * --------------------------------------------------------------------- */

typedef struct {
    int z;   /* zero flag           */
    int n;   /* negative flag       */
    int c;   /* carry / borrow flag */
    int v;   /* signed overflow flag */
} Flags;

/* -------------------------------------------------------------------------
 * alu_add  —  64-bit unsigned addition
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a + b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == (a + b > (uint64_t)0xFFFFFFFFFFFFFFFFULL);
  @ ensures  out_flags->v ==
  @   (((int64_t)a >= 0 && (int64_t)b >= 0 && (int64_t)\result <  0) ||
  @    ((int64_t)a <  0 && (int64_t)b <  0 && (int64_t)\result >= 0));
  @*/
uint64_t alu_add(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_sub  —  64-bit subtraction  (a - b)
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a - b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == (a < b);
  @ ensures  out_flags->v ==
  @   (((int64_t)a >= 0 && (int64_t)b <  0 && (int64_t)\result <  0) ||
  @    ((int64_t)a <  0 && (int64_t)b >= 0 && (int64_t)\result >= 0));
  @*/
uint64_t alu_sub(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_mul  —  64-bit unsigned multiplication  (low 64 bits of product)
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a * b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == (a * b > (uint64_t)0xFFFFFFFFFFFFFFFFULL);
  @ ensures  out_flags->v == out_flags->c;
  @*/
uint64_t alu_mul(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_div  —  64-bit unsigned division  (a / b)
 *   Caller must ensure b != 0 (architectural invariant — divide-by-zero is
 *   trapped by the fetch-decode stage before reaching the ALU).
 * --------------------------------------------------------------------- */

/*@ requires b != 0;
  @ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == a / b;
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_div(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_shl  —  logical shift left   (6-bit count mask, so count & 63)
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a << (count & 63u));
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_shl(uint64_t a, uint64_t count, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_shr  —  logical shift right  (6-bit count mask)
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a >> (count & 63u));
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_shr(uint64_t a, uint64_t count, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_rol  —  rotate left  (6-bit count mask)
 *   When (count & 63) == 0 the value is unchanged.
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ behavior zero_count:
  @   assumes (count & 63u) == 0;
  @   ensures \result == a;
  @ behavior nonzero_count:
  @   assumes (count & 63u) != 0;
  @   ensures \result ==
  @     (uint64_t)((a << (count & 63u)) | (a >> (64u - (count & 63u))));
  @ complete behaviors;
  @ disjoint behaviors;
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_rol(uint64_t a, uint64_t count, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_ror  —  rotate right  (6-bit count mask)
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ behavior zero_count:
  @   assumes (count & 63u) == 0;
  @   ensures \result == a;
  @ behavior nonzero_count:
  @   assumes (count & 63u) != 0;
  @   ensures \result ==
  @     (uint64_t)((a >> (count & 63u)) | (a << (64u - (count & 63u))));
  @ complete behaviors;
  @ disjoint behaviors;
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_ror(uint64_t a, uint64_t count, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_and  —  bitwise AND
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a & b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_and(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_or   —  bitwise OR
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a | b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_or(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_xor  —  bitwise XOR
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(a ^ b);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_xor(uint64_t a, uint64_t b, Flags *out_flags);

/* -------------------------------------------------------------------------
 * alu_not  —  bitwise NOT  (unary, single operand)
 *   Carry and overflow are architecturally undefined for NOT; both cleared.
 * --------------------------------------------------------------------- */

/*@ requires \valid(out_flags);
  @ assigns  *out_flags;
  @ ensures  \result == (uint64_t)(~a);
  @ ensures  out_flags->z == (\result == 0);
  @ ensures  out_flags->n == (\result >= (uint64_t)0x8000000000000000ULL);
  @ ensures  out_flags->c == 0;
  @ ensures  out_flags->v == 0;
  @*/
uint64_t alu_not(uint64_t a, Flags *out_flags);

#endif /* ALU_CONTRACTS_H */

/*
 * TLM JXCL ISA — Binary parser
 * Frama-C / ACSL formal specification  (Frama-C 26+ / E-ACSL)
 *
 * Magic bytes: 'J' 'X' 'C' 'L'  (0x4A 0x58 0x43 0x4C)
 * Architecture code: 0x4A58
 */

#ifndef BINARY_PARSER_H
#define BINARY_PARSER_H

#include <stdint.h>
#include <stddef.h>

/* On-disk header is exactly 56 bytes (two uint16s + padding + five uint64s + uint32).
 * With natural alignment, sizeof(BinaryHeader) == 56 == HEADER_SIZE.            */
#define HEADER_SIZE 56

typedef struct {
    uint16_t version;        /*  0: must be 1                         */
    uint16_t architecture;   /*  2: must be 0x4A58                    */
                             /*  4: 4 bytes implicit padding           */
    uint64_t entry_point;    /*  8                                    */
    uint64_t code_offset;    /* 16                                    */
    uint64_t code_size;      /* 24                                    */
    uint64_t data_offset;    /* 32                                    */
    uint64_t data_size;      /* 40                                    */
    uint32_t reserved;       /* 48: must be 0                         */
                             /* 52: 4 bytes implicit trailing padding  */
} BinaryHeader;

/* -------------------------------------------------------------------------
 * Predicates
 * --------------------------------------------------------------------- */

/*@ predicate BinaryHeaderValid(BinaryHeader *h, uint64_t total_len) =
  @   \valid(h) &&
  @   h->version      == 1       &&
  @   h->architecture == 0x4A58  &&
  @   h->reserved     == 0       &&
  @   // code section: no overflow, fully within file
  @   h->code_offset  <= total_len                              &&
  @   h->code_size    <= total_len - h->code_offset            &&
  @   // data section: no overflow, fully within file
  @   h->data_offset  <= total_len                              &&
  @   h->data_size    <= total_len - h->data_offset            &&
  @   // entry point is within the code section
  @   h->entry_point  >= h->code_offset                        &&
  @   h->entry_point  <  h->code_offset + h->code_size;
  @*/

/* -------------------------------------------------------------------------
 * parse_header
 *   Deserialises the first HEADER_SIZE bytes of `bytes` into `*out`.
 *   Returns 0 on success, non-zero on any validation failure.
 * --------------------------------------------------------------------- */

/*@ requires \valid(bytes + (0 .. len - 1));
  @ requires len >= HEADER_SIZE;
  @ requires \valid(out);
  @ assigns  *out;
  @ behavior valid_header:
  @   assumes bytes[0] == 'J' && bytes[1] == 'X' &&
  @           bytes[2] == 'C' && bytes[3] == 'L';
  @   ensures \result == 0;
  @   ensures BinaryHeaderValid(out, len);
  @ behavior invalid_magic:
  @   assumes bytes[0] != 'J' || bytes[1] != 'X' ||
  @           bytes[2] != 'C' || bytes[3] != 'L';
  @   ensures \result != 0;
  @ complete behaviors;
  @ disjoint behaviors;
  @*/
int parse_header(const uint8_t *bytes, uint64_t len, BinaryHeader *out);

/* -------------------------------------------------------------------------
 * validate_section_bounds
 *   Returns 1 if the section [offset, offset+size) is wholly within
 *   a file of `total_len` bytes and the arithmetic does not overflow.
 *   Returns 0 otherwise.
 * --------------------------------------------------------------------- */

/*@ requires total_len <= (uint64_t)0xFFFFFFFFFFFFFFFFULL;
  @ assigns  \nothing;
  @ behavior fits:
  @   assumes offset <= total_len && size <= total_len - offset;
  @   ensures \result == 1;
  @ behavior overflow_or_oob:
  @   assumes offset > total_len || size > total_len - offset;
  @   ensures \result == 0;
  @ complete behaviors;
  @ disjoint behaviors;
  @*/
int validate_section_bounds(uint64_t offset, uint64_t size, uint64_t total_len);

/* -------------------------------------------------------------------------
 * read_le16 / read_le32 / read_le64
 *   Helper decoders used by parse_header.  Separated so WP can verify them
 *   independently.
 * --------------------------------------------------------------------- */

/*@ requires \valid(p + (0 .. 1));
  @ assigns  \nothing;
  @ ensures  \result == (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
  @*/
uint16_t read_le16(const uint8_t *p);

/*@ requires \valid(p + (0 .. 3));
  @ assigns  \nothing;
  @ ensures  \result ==
  @   (uint32_t)((uint32_t)p[0]       |
  @              ((uint32_t)p[1] << 8)  |
  @              ((uint32_t)p[2] << 16) |
  @              ((uint32_t)p[3] << 24));
  @*/
uint32_t read_le32(const uint8_t *p);

/*@ requires \valid(p + (0 .. 7));
  @ assigns  \nothing;
  @ ensures  \result ==
  @   (uint64_t)((uint64_t)p[0]       |
  @              ((uint64_t)p[1] << 8)  |
  @              ((uint64_t)p[2] << 16) |
  @              ((uint64_t)p[3] << 24) |
  @              ((uint64_t)p[4] << 32) |
  @              ((uint64_t)p[5] << 40) |
  @              ((uint64_t)p[6] << 48) |
  @              ((uint64_t)p[7] << 56));
  @*/
uint64_t read_le64(const uint8_t *p);

#endif /* BINARY_PARSER_H */

/*
 * TLM JXCL ISA — Execution stack and machine state
 * Frama-C / ACSL formal specification  (Frama-C 26+ / E-ACSL)
 *
 * Covers: ValidStack, exec_push, exec_pop, exec_call, addr_of,
 *         and the CycleCountMonotone axiomatic.
 */

#ifndef EXECUTION_STACK_H
#define EXECUTION_STACK_H

#include <stdint.h>
#include "memory.h"

/* -------------------------------------------------------------------------
 * Machine register file
 * --------------------------------------------------------------------- */

#define JXCL_NUM_REGS 16

typedef struct {
    uint64_t r[JXCL_NUM_REGS]; /* general-purpose r0 … r15 */
    uint64_t sp;                /* stack pointer             */
    uint64_t pc;                /* program counter           */
    uint64_t flags;             /* packed flag register      */
} Registers;

/* -------------------------------------------------------------------------
 * Full machine state
 * --------------------------------------------------------------------- */

typedef struct {
    Registers regs;
    Memory    memory;
    int       halted;
    uint64_t  cycle_count;
} MachineState;

/* -------------------------------------------------------------------------
 * Stack predicate
 *   The stack grows downward; sp is always 8-byte aligned and within the
 *   address space described by the embedded Memory.
 * --------------------------------------------------------------------- */

/*@ predicate ValidStack(MachineState *s) =
  @   \valid(s) &&
  @   s->regs.sp % 8 == 0 &&
  @   s->regs.sp <= s->memory.size;
  @*/

/* -------------------------------------------------------------------------
 * Cycle-count monotonicity axiom
 *   Each non-halted step increments cycle_count by exactly 1.
 *   Captured as an axiomatic so WP can use it as a lemma during proofs.
 * --------------------------------------------------------------------- */

/*@ axiomatic CycleCountMonotone {
  @   predicate StepOf(MachineState *before, MachineState *after) =
  @     \valid(before) && \valid(after) &&
  @     !before->halted &&
  @     after->cycle_count == before->cycle_count + 1;
  @
  @   axiom step_increments_count:
  @     \forall MachineState *s1, *s2;
  @       StepOf(s1, s2) ==> s2->cycle_count > s1->cycle_count;
  @ }
  @*/

/* -------------------------------------------------------------------------
 * exec_push  —  PUSH value onto stack
 *   Decrements sp by 8, then writes value in little-endian at new sp.
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp >= 8;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp - 8, 8);
  @ requires InBounds(&state->memory, state->regs.sp - 8, 8);
  @ assigns  state->regs.sp,
  @          state->memory.data[state->regs.sp - 8 .. state->regs.sp - 1];
  @ ensures  state->regs.sp == \old(state->regs.sp) - 8;
  @ ensures  ValidStack(state);
  @ ensures  ValidMemory(&state->memory);
  @ ensures  state->memory.data[state->regs.sp]     == (uint8_t)(value);
  @ ensures  state->memory.data[state->regs.sp + 1] == (uint8_t)(value >> 8);
  @ ensures  state->memory.data[state->regs.sp + 2] == (uint8_t)(value >> 16);
  @ ensures  state->memory.data[state->regs.sp + 3] == (uint8_t)(value >> 24);
  @ ensures  state->memory.data[state->regs.sp + 4] == (uint8_t)(value >> 32);
  @ ensures  state->memory.data[state->regs.sp + 5] == (uint8_t)(value >> 40);
  @ ensures  state->memory.data[state->regs.sp + 6] == (uint8_t)(value >> 48);
  @ ensures  state->memory.data[state->regs.sp + 7] == (uint8_t)(value >> 56);
  @*/
void exec_push(MachineState *state, uint64_t value);

/* -------------------------------------------------------------------------
 * exec_pop  —  POP 8 bytes from stack into *out
 *   Reads little-endian 64-bit word at current sp, then increments sp by 8.
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp + 8 <= state->memory.size;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp, 8);
  @ requires InBounds(&state->memory, state->regs.sp, 8);
  @ requires \valid(out);
  @ assigns  state->regs.sp, *out;
  @ ensures  state->regs.sp == \old(state->regs.sp) + 8;
  @ ensures  ValidStack(state);
  @ ensures  *out ==
  @   (uint64_t)(
  @     (uint64_t)\old(state->memory.data[\old(state->regs.sp)])       |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 1]) << 8)  |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 2]) << 16) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 3]) << 24) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 4]) << 32) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 5]) << 40) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 6]) << 48) |
  @     ((uint64_t)\old(state->memory.data[\old(state->regs.sp) + 7]) << 56));
  @*/
void exec_pop(MachineState *state, uint64_t *out);

/* -------------------------------------------------------------------------
 * exec_call  —  CALL target
 *   Pushes the return address (the instruction after the CALL site), then
 *   sets pc = target.
 *   The caller computes return_addr = pc_after_fetch before calling.
 * --------------------------------------------------------------------- */

/*@ requires ValidMemory(&state->memory);
  @ requires ValidStack(state);
  @ requires state->regs.sp >= 8;
  @ requires NoCodeOverlap(&state->memory, state->regs.sp - 8, 8);
  @ requires InBounds(&state->memory, state->regs.sp - 8, 8);
  @ assigns  state->regs.sp,
  @          state->regs.pc,
  @          state->memory.data[state->regs.sp - 8 .. state->regs.sp - 1];
  @ ensures  state->regs.sp == \old(state->regs.sp) - 8;
  @ ensures  state->regs.pc == target;
  @ ensures  ValidStack(state);
  @ ensures  ValidMemory(&state->memory);
  @ // Return address stored in little-endian at new sp:
  @ ensures  state->memory.data[state->regs.sp]     == (uint8_t)(return_addr);
  @ ensures  state->memory.data[state->regs.sp + 1] == (uint8_t)(return_addr >> 8);
  @ ensures  state->memory.data[state->regs.sp + 2] == (uint8_t)(return_addr >> 16);
  @ ensures  state->memory.data[state->regs.sp + 3] == (uint8_t)(return_addr >> 24);
  @ ensures  state->memory.data[state->regs.sp + 4] == (uint8_t)(return_addr >> 32);
  @ ensures  state->memory.data[state->regs.sp + 5] == (uint8_t)(return_addr >> 40);
  @ ensures  state->memory.data[state->regs.sp + 6] == (uint8_t)(return_addr >> 48);
  @ ensures  state->memory.data[state->regs.sp + 7] == (uint8_t)(return_addr >> 56);
  @*/
void exec_call(MachineState *state, uint64_t target, uint64_t return_addr);

/* -------------------------------------------------------------------------
 * addr_of  —  signed displacement + unsigned base (wrapping semantics)
 *   Models addressing modes such as  [rN + imm16].
 *   The cast path (int64_t)base + disp uses 64-bit signed arithmetic whose
 *   result is reinterpreted as uint64_t, giving well-defined wrap-around.
 * --------------------------------------------------------------------- */

/*@ assigns  \nothing;
  @ ensures  \result == (uint64_t)((int64_t)base + disp);
  @*/
uint64_t addr_of(uint64_t base, int64_t disp);

#endif /* EXECUTION_STACK_H */

/*
 * TLM JXCL ISA — Memory subsystem
 * Frama-C / ACSL formal specification  (Frama-C 26+ / E-ACSL)
 *
 * All predicates and function contracts are written in ACSL.
 * Arithmetic inside ACSL logic uses mathematical integers (unbounded),
 * so additions / subtractions in predicate bodies do NOT wrap.
 */

#ifndef MEMORY_H
#define MEMORY_H

#include <stdint.h>
#include <stddef.h>

/* -------------------------------------------------------------------------
 * Core types
 * --------------------------------------------------------------------- */

typedef struct {
    uint8_t  *data;
    uint64_t  size;
    uint64_t  code_start;
    uint64_t  code_end;
} Memory;

typedef enum {
    MEM_OK = 0,
    MEM_INVALID_ADDRESS,
    MEM_ALIGNMENT_FAULT,
    MEM_READ_VIOLATION,
    MEM_WRITE_VIOLATION,
    MEM_EXECUTE_VIOLATION
} MemResult;

/* -------------------------------------------------------------------------
 * Global ACSL predicates
 * --------------------------------------------------------------------- */

/*@ predicate ValidMemory(Memory *m) =
