fn collect_term_variables(terms: &[Term], vars: &mut HashSet<String>) {
    for term in terms {
        if term.name.chars().next().map_or(false, |c| c.is_uppercase()) {
            vars.insert(term.name.clone());
        }
        collect_term_variables(&term.children, vars);
    }
}

