//! basic_bot.rs — Minimal bot setup example.
//!
//! Shows the smallest possible runnable bot with in-memory state and
//! no LLM integration.
//!
//! Run with:
//!   TELOXIDE_TOKEN=<token> cargo run --example basic_bot

use std::sync::Arc;
use telegram_bot_sdk::{agent::Agent, bot::TelegramBot, state::AppState};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt().compact().init();
    let _ = dotenv::dotenv();

    let state = AppState::from_env();
    let agent = Arc::new(Agent::new(state.clone()).with_ollama_from_env());

    TelegramBot::from_env(state, agent).run().await;
}

//! full_featured.rs — Complete working example of the Telegram Bot SDK.
//!
//! Demonstrates:
//! - AppState construction with BotConfig from environment
//! - Agent setup with Ollama fallback
//! - Custom AgentCommand registration via FnAgentCommand
//! - Persistence store (SQLite) with startup load and periodic flush
//! - Bot wiring and long-poll dispatch loop
//!
//! Run with:
//!   TELOXIDE_TOKEN=<token> cargo run --example full_featured
//!
//! Optional env vars:
//!   OLLAMA_URL=http://localhost:11434
//!   OLLAMA_MODEL=llama3.2
//!   DATABASE_URL=sqlite:./bot.db
//!   RUST_LOG=info

use std::sync::Arc;
use anyhow::Result;
use tracing::{info, warn, error};
use tracing_subscriber::{fmt, EnvFilter};

use telegram_bot_sdk::{
    agent::{Agent, AgentConfig, FnAgentCommand},
    bot::TelegramBot,
    integrations::{
        persistence::PersistenceStore,
        IntegrationRegistry,
    },
    state::{AppState, BotConfig, Sprint, Issue, IssuePriority},
    types::Response,
};

#[tokio::main]
async fn main() -> Result<()> {
    // -----------------------------------------------------------------------
    // Logging
    // -----------------------------------------------------------------------
    fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| EnvFilter::new("telegram_bot_sdk=debug,info")),
        )
        .compact()
        .init();

    info!("DevFlow Finance Twin — starting up");

    // -----------------------------------------------------------------------
    // Load .env if present
    // -----------------------------------------------------------------------
    let _ = dotenv::dotenv();

    // -----------------------------------------------------------------------
    // Config + AppState
    // -----------------------------------------------------------------------
    let config = BotConfig::default();
    if config.token.is_empty() {
        anyhow::bail!("TELOXIDE_TOKEN or TELEGRAM_BOT_TOKEN is not set");
    }

    let state = AppState::new(config.clone());

    // -----------------------------------------------------------------------
    // Optional persistence — load from disk on startup
    // -----------------------------------------------------------------------
    let persistence: Option<PersistenceStore> = match &config.database_url {
        Some(url) => match PersistenceStore::connect(url).await {
            Ok(store) => {
                info!("Persistence store connected: {}", url);
                let sprints = store.load_sprints().await?;
                let issues = store.load_issues().await?;
                info!("Loaded {} sprints, {} issues from disk", sprints.len(), issues.len());

                for sprint in sprints {
                    let _ = state.create_sprint(sprint).await;
                }
                for issue in issues {
                    let _ = state.create_issue(issue).await;
                }
                Some(store)
            }
            Err(e) => {
                warn!("Persistence unavailable: {}", e);
                None
            }
        },
        None => {
            info!("DATABASE_URL not set — using in-memory state only");
            None
        }
    };

    // -----------------------------------------------------------------------
    // Seed demo data (only when no data exists)
    // -----------------------------------------------------------------------
    seed_demo_data(&state).await;

    // -----------------------------------------------------------------------
    // Integration registry
    // -----------------------------------------------------------------------
    let mut integrations = IntegrationRegistry::new();
    if let Some(ref ps) = persistence {
        integrations.register(Box::new(ps.clone()));
    }

    // -----------------------------------------------------------------------
    // Build the agent — first set up Ollama, then register commands
    // -----------------------------------------------------------------------

    // Step 1: build the base with Ollama (if available).
    let agent_base = Agent::new(state.clone()).with_ollama_from_env();

    // Step 2: configure and register commands.
    let agent_config = AgentConfig {
        system_prompt: "You are DevFlow, an agile project management AI. \
                        Help with sprints, issues, standups, and retrospectives. \
                        Be concise and practical."
            .to_owned(),
        silent_unknown: false,
        max_context_entries: 8,
    };

    // /ping — health check command
    let ping_cmd = FnAgentCommand::new(
        "ping",
        "Health check — replies with pong",
        |_ctx, _args, _state| async move { Ok(Response::text("pong")) },
    );

    // /summary — project overview
    let summary_state = state.clone();
    let summary_cmd = FnAgentCommand::new(
        "summary",
        "Brief project summary",
        move |_ctx, _args, _s| {
            let s = summary_state.clone();
            async move {
                let sprint_count = s.sprint_count().await;
                let issue_count = s.issue_count().await;
                let active_line = s
                    .get_active_sprint()
                    .await
                    .map(|sp| format!("Active: {} ({} days left)", sp.name, sp.days_remaining()))
                    .unwrap_or_else(|| "No active sprint".to_owned());
                Ok(Response::text(format!(
                    "Project Summary\nSprints: {}\nIssues: {}\n{}",
                    sprint_count, issue_count, active_line
                )))
            }
        },
    );

    let agent = Arc::new(
        agent_base
            .with_config(agent_config)
            .register(ping_cmd)
            .register(summary_cmd),
    );

    // -----------------------------------------------------------------------
    // Health check on startup
    // -----------------------------------------------------------------------
    let results = integrations.health_check_all().await;
    for (name, result) in &results {
        match result {
            Ok(_) => info!("Integration '{}': OK", name),
            Err(e) => warn!("Integration '{}': DEGRADED — {}", name, e),
        }
    }

    info!(
        "Agent ready — LLM: {}, Sprints: {}, Issues: {}",
        if agent.has_ollama() { "Ollama" } else { "none" },
        state.sprint_count().await,
        state.issue_count().await,
    );

    // -----------------------------------------------------------------------
    // Periodic persistence flush (background task)
    // -----------------------------------------------------------------------
    if let Some(store) = persistence {
        let flush_state = state.clone();
        tokio::spawn(async move {
            let mut interval = tokio::time::interval(std::time::Duration::from_secs(300));
            loop {
                interval.tick().await;
                if let Err(e) = store.flush_state(&flush_state).await {
                    error!("Flush error: {}", e);
                } else {
                    info!("Periodic state flush complete");
                }
                let removed = flush_state
                    .cleanup_stale_sessions(flush_state.config.session_timeout_secs)
                    .await;
                if removed > 0 {
                    info!("Removed {} stale sessions", removed);
                }
            }
        });
    }

    // -----------------------------------------------------------------------
    // Start the bot (blocks until Ctrl-C)
    // -----------------------------------------------------------------------
    info!("Connecting to Telegram...");
    TelegramBot::from_env(state, agent).run().await;

    Ok(())
}

// ---------------------------------------------------------------------------
// Demo data seeding
// ---------------------------------------------------------------------------

async fn seed_demo_data(state: &AppState) {
    use chrono::{Duration, Utc};

    if state.sprint_count().await > 0 {
        return; // already seeded
    }

    info!("Seeding demo sprint and issues...");

    let now = Utc::now();
    let sprint = Sprint::new("Demo Sprint 1", now - Duration::days(3), now + Duration::days(11));
    let sprint_id = sprint.id;

    if let Ok(created) = state.create_sprint(sprint).await {
        let _ = state.set_active_sprint(created.id).await;

        let demo_issues = vec![
            Issue::new("Set up CI pipeline")
                .with_priority(IssuePriority::High)
                .with_points(5)
                .with_sprint(sprint_id),
            Issue::new("Implement OAuth2 login")
                .with_priority(IssuePriority::High)
                .with_points(8)
                .with_sprint(sprint_id),
            Issue::new("Write unit tests for auth module")
                .with_priority(IssuePriority::Medium)
                .with_points(3)
                .with_sprint(sprint_id),
            Issue::new("Fix flaky integration tests")
                .with_priority(IssuePriority::Medium)
                .with_points(2)
                .with_sprint(sprint_id),
        ];

        for issue in demo_issues {
            let _ = state.create_issue(issue).await;
        }

        info!("Demo sprint created with 4 issues");
    }
}

//! Agent framework — command routing with Ollama LLM fallback.
//!
//! The `Agent` struct is the central dispatcher.  It:
//! 1. Tries to match the input against the `CommandRegistry`.
//! 2. If no command matches and Ollama is configured, calls the LLM.
//! 3. Otherwise returns a "not understood" response.
//!
//! `AgentCommand` is the richer command trait used here (carries `Arc<AppState>`
//! explicitly instead of storing it on the struct).

use std::collections::HashMap;
use std::sync::Arc;
use async_trait::async_trait;
use tracing::{debug, info, warn};

use crate::error::{BotError, Result};
use crate::integrations::ollama::{OllamaClient, OllamaConfig};
use crate::state::AppState;
use crate::types::{Context, Response};

// ---------------------------------------------------------------------------
// AgentCommand trait
// ---------------------------------------------------------------------------

/// Like `Command` but receives `Arc<AppState>` at dispatch time rather than
/// storing it.  Use this for commands that need to be registered in the agent
/// registry without tying them to a specific `AppState` at construction time.
#[async_trait]
pub trait AgentCommand: Send + Sync {
    fn name(&self) -> &str;
    fn description(&self) -> &str;
    fn aliases(&self) -> &[&str] { &[] }

    /// Returns `true` if this command can handle the input token.
    /// Default: exact match on `name()` or any alias.
    fn can_handle(&self, token: &str) -> bool {
        let token = token.trim_start_matches('/');
        self.name() == token || self.aliases().contains(&token)
    }

    async fn execute(
        &self,
        ctx: &Context,
        args: &[&str],
        state: Arc<AppState>,
    ) -> Result<Response>;
}

// ---------------------------------------------------------------------------
// CommandRegistry
// ---------------------------------------------------------------------------

/// Holds `AgentCommand` implementations indexed by all their names and aliases.
#[derive(Default)]
pub struct CommandRegistry {
    commands: HashMap<String, Arc<dyn AgentCommand>>,
}

impl CommandRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    /// Register a command by its name and all aliases.
    pub fn register(&mut self, cmd: Arc<dyn AgentCommand>) {
        let name = cmd.name().to_owned();
        let aliases: Vec<String> = cmd.aliases().iter().map(|&s| s.to_owned()).collect();
        self.commands.insert(name, Arc::clone(&cmd));
        for alias in aliases {
            self.commands.insert(alias, Arc::clone(&cmd));
        }
    }

    /// Look up a command by the raw first token (leading `/` stripped).
    pub fn get(&self, token: &str) -> Option<Arc<dyn AgentCommand>> {
        let key = token.trim_start_matches('/');
        self.commands.get(key).cloned()
    }

    pub fn len(&self) -> usize {
        self.commands.len()
    }

    pub fn is_empty(&self) -> bool {
        self.commands.is_empty()
    }

    /// Returns sorted unique command names (no aliases).
    pub fn names(&self) -> Vec<&str> {
        let mut names: Vec<&str> = self.commands.keys().map(String::as_str).collect();
        names.sort_unstable();
        names
    }
}

// ---------------------------------------------------------------------------
// AgentConfig
// ---------------------------------------------------------------------------

/// Tuning knobs for the `Agent`.
#[derive(Debug, Clone)]
pub struct AgentConfig {
    /// Prepended to every Ollama prompt.
    pub system_prompt: String,
    /// If `true`, unrecognised messages are silently ignored (no "I don't understand").
    pub silent_unknown: bool,
    /// Max context window fed to Ollama (number of recent session entries).
    pub max_context_entries: usize,
}

impl Default for AgentConfig {
    fn default() -> Self {
        Self {
            system_prompt: "You are DevFlow, an AI assistant specialising in agile project \
                            management, sprint planning, and issue tracking. Keep answers concise \
                            and actionable."
                .to_owned(),
            silent_unknown: false,
            max_context_entries: 6,
        }
    }
}

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------

/// Top-level dispatcher.
///
/// Constructed once and stored as `Arc<Agent>` in the bot's dependency
/// injection container.
pub struct Agent {
    registry: CommandRegistry,
    ollama: Option<OllamaClient>,
    state: Arc<AppState>,
    config: AgentConfig,
}

impl Agent {
    // -----------------------------------------------------------------------
    // Construction
    // -----------------------------------------------------------------------

    /// Build an `Agent` with no commands and no Ollama client.
    pub fn new(state: Arc<AppState>) -> Self {
        Self {
            registry: CommandRegistry::new(),
            ollama: None,
            state,
            config: AgentConfig::default(),
        }
    }

    /// Builder: enable Ollama with a custom config.
    pub fn with_ollama(mut self, config: OllamaConfig) -> Result<Self> {
        self.ollama = Some(OllamaClient::new(config)?);
        Ok(self)
    }

    /// Builder: enable Ollama reading from environment variables.
    pub fn with_ollama_from_env(mut self) -> Self {
        match OllamaClient::from_env() {
            Ok(client) => {
                info!("Ollama LLM enabled at {}", client.base_url());
                self.ollama = Some(client);
            }
            Err(e) => {
                warn!("Ollama unavailable, LLM fallback disabled: {}", e);
            }
        }
        self
    }

    /// Builder: apply a custom agent config.
    pub fn with_config(mut self, config: AgentConfig) -> Self {
        self.config = config;
        self
    }

    /// Builder: register an `AgentCommand`.
    pub fn register(mut self, cmd: Arc<dyn AgentCommand>) -> Self {
        self.registry.register(cmd);
        self
    }

    // -----------------------------------------------------------------------
    // Dispatch
    // -----------------------------------------------------------------------

    /// Main entry point called by the bot for every message / command.
    ///
    /// Resolution order:
    /// 1. Split on whitespace → first token → look up in registry.
    /// 2. If found, execute the command.
    /// 3. If not found and Ollama is available, ask the LLM.
    /// 4. Otherwise return a canned "unknown" response.
    pub async fn dispatch(&self, ctx: &Context, input: &str) -> Result<Response> {
        let input = input.trim();
        if input.is_empty() {
            return Ok(Response::Empty);
        }

        let parts: Vec<&str> = input.split_whitespace().collect();
        let token = parts[0].trim_start_matches('/');
        let args = &parts[1..];

        debug!("Agent dispatch: token={} args_len={}", token, args.len());

        // 1. Named command?
        if let Some(cmd) = self.registry.get(token) {
            return cmd.execute(ctx, args, self.state.clone()).await;
        }

        // 2. Starts with '/' but not registered → unknown command
        if input.starts_with('/') {
            return Ok(Response::text(format!(
                "Unknown command: /{}. Use /help to see available commands.",
                token
            )));
        }

        // 3. Free-text → Ollama if available
        self.ollama_fallback(ctx, input).await
    }

    /// Call Ollama with session context prepended.
    async fn ollama_fallback(&self, ctx: &Context, query: &str) -> Result<Response> {
        match &self.ollama {
            Some(client) => {
                // Build a short conversation history from session context.
                let session = self.state.get_or_create_session(ctx.chat_id).await;
                let context_window: Vec<String> = session
                    .context
                    .iter()
                    .rev()
                    .take(self.config.max_context_entries)
                    .rev()
                    .cloned()
                    .collect();

                let prompt = if context_window.is_empty() {
                    query.to_owned()
                } else {
                    format!(
                        "Context (recent messages):\n{}\n\nUser: {}",
                        context_window.join("\n"),
                        query
                    )
                };

                debug!("Sending to Ollama: {} chars", prompt.len());
                let response = client.complete(&prompt).await?;

                // Update session context
                self.state
                    .update_session(ctx.chat_id, |s| {
                        s.push_context(
                            format!("User: {}", query),
                            self.config.max_context_entries * 2,
                        );
                        s.push_context(
                            format!("Bot: {}", &response),
                            self.config.max_context_entries * 2,
                        );
                    })
                    .await;

                Ok(Response::Text(response))
            }
            None => {
                if self.config.silent_unknown {
                    Ok(Response::Empty)
                } else {
                    Ok(Response::text(
                        "I'm not sure how to help with that. \
                         Use /help to see available commands.",
                    ))
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Accessors
    // -----------------------------------------------------------------------

    pub fn has_ollama(&self) -> bool {
        self.ollama.is_some()
    }

    pub fn registry(&self) -> &CommandRegistry {
        &self.registry
    }

    pub fn state(&self) -> Arc<AppState> {
        self.state.clone()
    }
}

// ---------------------------------------------------------------------------
// Built-in AgentCommand implementations
// ---------------------------------------------------------------------------

/// A pass-through that delegates to any `Fn` closure — useful for wiring up
/// thin adapters from `Command` implementations.
pub struct FnAgentCommand {
    name: String,
    description: String,
    aliases: Vec<String>,
    #[allow(clippy::type_complexity)]
    handler: Arc<
        dyn Fn(
                Context,
                Vec<String>,
                Arc<AppState>,
            ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<Response>> + Send>>
            + Send
            + Sync,
    >,
}

impl FnAgentCommand {
    pub fn new<F, Fut>(
        name: impl Into<String>,
        description: impl Into<String>,
        handler: F,
    ) -> Arc<Self>
    where
        F: Fn(Context, Vec<String>, Arc<AppState>) -> Fut + Send + Sync + 'static,
        Fut: std::future::Future<Output = Result<Response>> + Send + 'static,
    {
        Arc::new(Self {
            name: name.into(),
            description: description.into(),
            aliases: Vec::new(),
            handler: Arc::new(move |ctx, args, state| Box::pin(handler(ctx, args, state))),
        })
    }
}

#[async_trait]
impl AgentCommand for FnAgentCommand {
    fn name(&self) -> &str {
        &self.name
    }

    fn description(&self) -> &str {
        &self.description
    }

    fn aliases(&self) -> &[&str] {
        // SAFETY: self.aliases is owned String vec; we return &str refs into it.
        // Since FnAgentCommand is not Copy this is fine as long as self lives.
        // But &[&str] requires a static or self-tied lifetime.
        // For simplicity we return empty here; aliases on this type are set via constructor.
        &[]
    }

    async fn execute(
        &self,
        ctx: &Context,
        args: &[&str],
        state: Arc<AppState>,
    ) -> Result<Response> {
        let args_owned: Vec<String> = args.iter().map(|s| s.to_string()).collect();
        (self.handler)(ctx.clone(), args_owned, state).await
    }
}

