use nraay_tensor::prelude::*;
use std::sync::Arc;

fn main() -> Result<()> {
    println!("=== NraayTensor: Materialization & COW ===\n");

    let mut t = NraayTensor::new(vec![3, 4])?;
    println!("Original tensor: shape {:?}, contiguous: {}\n", t.shape(), t.is_contiguous());

    // Apply transpose (logical shift)
    println!("=== Step 1: Transpose ===");
    t.transpose(&[1, 0])?;
    println!("After transpose:");
    println!("  Shape: {:?}", t.shape());
    println!("  Is Contiguous: {}", t.is_contiguous());
    println!("  Strides: {:?}\n", t.strides());

    // Create slices (shared ownership)
    println!("=== Step 2: Create Slices ===");
    let s1 = t.slice(&[(0, 2, 1), (0, 3, 1)])?;
    let s2 = t.slice(&[(2, 4, 1), (0, 3, 1)])?;

    println!("Created s1 and s2:");
    println!("  t.refcount() = {} (t + s1 + s2)", t.refcount());
    println!("  s1.is_contiguous() = {}", s1.is_contiguous());
    println!("  s2.is_contiguous() = {}\n", s2.is_contiguous());

    // Materialize main tensor
    println!("=== Step 3: Materialize main tensor ===");
    let t_buf_ptr_before = Arc::as_ptr(&t.data());
    t.materialize()?;
    let t_buf_ptr_after = Arc::as_ptr(&t.data());

    println!("After t.materialize():");
    println!("  t.is_contiguous() = {}", t.is_contiguous());
    println!("  t.owns_storage() = {}", t.owns_storage());
    println!("  Buffer changed: {}", t_buf_ptr_before != t_buf_ptr_after);
    println!("  t.refcount() = {} (only t, slices still share old buffer)\n", t.refcount());

    // Slices still valid (share original buffer)
    println!("=== Step 4: Slices Still Valid ===");
    println!("s1 still valid:");
    println!("  s1.shape() = {:?}", s1.shape());
    println!("  s1.is_contiguous() = {}", s1.is_contiguous());
    println!("  s1.refcount() = {} (s1 + s2, both still share original buffer)\n", s1.refcount());

    // Materialize a slice (COW)
    println!("=== Step 5: Materialize Slice (COW) ===");
    let mut s1_mut = s1;
    let s1_buf_ptr_before = Arc::as_ptr(&s1_mut.data());
    s1_mut.materialize()?;
    let s1_buf_ptr_after = Arc::as_ptr(&s1_mut.data());

    println!("After s1_mut.materialize():");
    println!("  s1_mut.is_contiguous() = {}", s1_mut.is_contiguous());
    println!("  s1_mut.owns_storage() = {}", s1_mut.owns_storage());
    println!("  Buffer changed (COW): {}", s1_buf_ptr_before != s1_buf_ptr_after);
    println!("  s1_mut.refcount() = {} (exclusive)", s1_mut.refcount());
    println!("  s2.refcount() = {} (s2 still on original buffer)\n", s2.refcount());

    // Show isolation
    println!("=== Step 6: Buffer Isolation ===");
    println!("After COW materialization:");
    println!("  t, s1_mut have DIFFERENT buffers:");
    println!("    t.data() ptr: {:?}", Arc::as_ptr(&t.data()));
    println!("    s1_mut.data() ptr: {:?}", Arc::as_ptr(&s1_mut.data()));
    println!("  s2 still shares original buffer with nothing");

    Ok(())
}

use nraay_tensor::prelude::*;

fn main() -> Result<()> {
    println!("=== NraayTensor: Virtual Slicing ===\n");

    let t = NraayTensor::new(vec![4, 4])?;
    println!("Original tensor: shape {:?}, refcount {}\n", t.shape(), t.refcount());

    // Slice 1: Rows [1:3], all columns
    println!("=== Slice 1: [1:3, :] (unit steps) ===");
    let s1 = t.slice(&[(1, 3, 1), (0, 4, 1)])?;
    println!("  Shape: {:?}", s1.shape());
    println!("  Offset: {}", s1.offset());
    println!("  Strides: {:?}", s1.strides());
    println!("  Is Contiguous: {}", s1.is_contiguous());
    println!("  Shared Buffer: {}", std::ptr::eq(
        std::sync::Arc::as_ptr(&t.data()),
        std::sync::Arc::as_ptr(&s1.data())
    ));
    println!("  Refcount: {}\n", t.refcount());

    // Slice 2: All rows, columns [::2] (step=2)
    println!("=== Slice 2: [:, ::2] (step=2) ===");
    let s2 = t.slice(&[(0, 4, 1), (0, 4, 2)])?;
    println!("  Shape: {:?}", s2.shape());
    println!("  Strides: {:?}", s2.strides());
    println!("  Is Contiguous: {} (step breaks canonical)\n", s2.is_contiguous());

    // Slice 3: Sub-slice of Slice 1
    println!("=== Slice 3: Slice-of-Slice ===");
    let s3 = s1.slice(&[(0, 2, 1), (0, 4, 1)])?;
    println!("  Shape: {:?}", s3.shape());
    println!("  Offset: {} (composed offsets)", s3.offset());
    println!("  Strides: {:?}", s3.strides());
    println!("  Refcount: {}\n", t.refcount());

    // Show sharing
    println!("=== Shared Buffer Analysis ===");
    println!("t, s1, s2 all share the same buffer:");
    println!("  t.refcount() = {}", t.refcount());
    println!("  s1.refcount() = {}", s1.refcount());
    println!("  s2.refcount() = {}\n", s2.refcount());

    // Dropping slices decrements refcount
    println!("=== Reference Counting ===");
    drop(s1);
    println!("After dropping s1: t.refcount() = {}", t.refcount());

    drop(s2);
    println!("After dropping s2: t.refcount() = {}", t.refcount());

    drop(s3);
    println!("After dropping s3: t.refcount() = {}\n", t.refcount());

    Ok(())
}

//! Error types for NraayTensor operations.

use thiserror::Error;

/// Error type for NraayTensor operations.
#[derive(Error, Debug, Clone, PartialEq, Eq)]
pub enum NraayError {
    /// Shape mismatch in operation.
    #[error("shape mismatch: expected {expected:?}, got {actual:?}")]
    ShapeMismatch {
        expected: Vec<usize>,
        actual: Vec<usize>,
    },

    /// Index out of bounds.
    #[error("index out of bounds at dimension {dim}: {index} >= {size}")]
    IndexOutOfBounds { dim: usize, index: usize, size: usize },

    /// Invalid slice range.
    #[error("invalid slice range: start={start} >= end={end} (dim size={size})")]
    InvalidSliceRange { start: usize, end: usize, size: usize },

    /// Dimension mismatch.
    #[error("dimension mismatch: expected {expected}, got {actual}")]
    DimensionMismatch { expected: usize, actual: usize },

    /// Cannot transpose with invalid permutation.
    #[error("invalid transpose permutation: expected length {expected}, got {actual}")]
    InvalidPermutation { expected: usize, actual: usize },

    /// Empty tensor operation not supported.
    #[error("operation on empty tensor not supported")]
    EmptyTensor,

    /// Cannot materialize already contiguous tensor.
    #[error("tensor is already contiguous")]
    AlreadyContiguous,
}

/// Specialized `Result` type for NraayTensor operations.
pub type Result<T> = std::result::Result<T, NraayError>;

