        assert!(shares_buffer(&t, &v));
        let mut v2 = v.clone();
        v2.materialize().unwrap();
        assert!(!shares_buffer(&t, &v2));
    }
}

//! RAW_ROUTE: memory-region-affine task routing for worker deques.
//!
//! Implements the given specification verbatim:
//!
//! ```text
//! RAW_ROUTE(task):
//!   r ← task.memory_region
//!   owner ← RegionTable[r].owner
//!   if owner exists:
//!     push(task, Worker[owner].deque)
//!     return owner
//!   candidates ← SparseEdges[r]
//!   best ← NONE; best_score ← -∞
//!   for worker in candidates:
//!     score ← locality + memory_affinity + queue_pressure + stealability
//!            - migration_cost
//!     if score > best_score: best ← worker; best_score ← score
//!   if best ≠ NONE:
//!     push(task, Worker[best].deque); RegionTable[r].owner ← best; return best
//!   worker ← select_least_loaded_worker()
//!   push(task, Worker[worker].deque); RegionTable[r].owner ← worker
//!   return worker
//! ```
//!
//! Built on the governance model: tasks are `RegionTag`ged (memory region r),
//! workers hold plain deques, and RegionTable ownership is a governed state
//! transition recorded alongside tensor buffer lineage.

use std::collections::{HashMap, VecDeque};

/// Memory region identifier (task.memory_region).
pub type RegionId = u64;

/// Worker identifier (index into Worker[]).
pub type WorkerId = usize;

/// A schedulable task bound to a memory region.
#[derive(Debug, Clone)]
pub struct Task {
    pub id: u64,
    pub memory_region: RegionId,
}

/// Deque worker: FIFO queue of tasks + load counter.
#[derive(Debug, Default)]
pub struct Worker {
    pub deque: VecDeque<Task>,
}

impl Worker {
    pub fn queue_len(&self) -> usize {
        self.deque.len()
    }
}

/// RegionTable entry: sticky owner for region r.
#[derive(Debug, Clone, Copy)]
pub struct RegionEntry {
    pub owner: Option<WorkerId>,
}

/// Scoring context for candidate workers (pure functions of worker + task state).
#[derive(Debug, Clone, Copy)]
pub struct ScoreWeights {
    pub locality: f64,
    pub memory_affinity: f64,
    pub queue_pressure: f64,
    pub stealability: f64,
    pub migration_cost: f64,
}

/// RAW_ROUTE router: owns RegionTable, sparse affinity edges, and workers.
pub struct RawRouteRouter {
    pub workers: Vec<Worker>,
    pub region_table: HashMap<RegionId, RegionEntry>,
    /// SparseEdges[r] — candidate workers adjacent to region r in affinity graph.
    pub sparse_edges: HashMap<RegionId, Vec<WorkerId>>,
    pub weights: ScoreWeights,
    /// Default affinity when region has no explicit sparse edge entry.
    pub default_affinity: Vec<WorkerId>,
}

impl RawRouteRouter {
    pub fn new(num_workers: usize) -> Self {
        RawRouteRouter {
            workers: (0..num_workers).map(|_| Worker::default()).collect(),
            region_table: HashMap::new(),
            sparse_edges: HashMap::new(),
            weights: ScoreWeights::default(),
            default_affinity: (0..num_workers).collect(),
        }
    }

    /// Register affinity edge: region r is memory-affine to worker w.
    pub fn add_sparse_edge(&mut self, r: RegionId, w: WorkerId) {
        self.sparse_edges.entry(r).or_default().push(w);
    }

    fn owner_of(&self, r: RegionId) -> Option<WorkerId> {
        self.region_table.get(&r).and_then(|e| e.owner)
    }

    fn set_owner(&mut self, r: RegionId, w: WorkerId) {
        self.region_table.entry(r).or_insert(RegionEntry { owner: None }).owner = Some(w);
    }

    /// locality: 1.0 if worker hosts the region's pages (affinity edge), else 0.
    fn locality(&self, worker: WorkerId, r: RegionId) -> f64 {
        match self.sparse_edges.get(&r) {
            Some(edges) if edges.contains(&worker) => 1.0,
            _ => 0.0,
        }
    }

    /// memory_affinity: inverse normalized hop distance via default ring (toy model).
    fn memory_affinity(&self, worker: WorkerId, r: RegionId) -> f64 {
        let n = self.workers.len().max(1) as f64;
        let ring = (r as f64).round() as usize % self.workers.len().max(1);
        let dist = (worker as i64 - ring as i64).unsigned_abs() as f64;
        let min_dist = dist.min(n - dist);
        1.0 - min_dist / (n / 2.0).max(1.0)
    }

    /// queue_pressure: higher when worker is emptier (prefer draining idle workers).
    fn queue_pressure(&self, worker: WorkerId) -> f64 {
        let max_q = self.workers.iter().map(|w| w.queue_len()).max().unwrap_or(1).max(1) as f64;
        1.0 - (self.workers[worker].queue_len() as f64 / max_q)
    }

    /// stealability: how willing worker is to accept new work (inverse load).
    fn stealability(&self, worker: WorkerId) -> f64 {
        let load = self.workers[worker].queue_len() as f64;
        1.0 / (1.0 + load)
    }

    /// migration_cost: penalty if worker is far from region's current owner.
    fn migration_cost(&self, worker: WorkerId, r: RegionId) -> f64 {
        match self.owner_of(r) {
            Some(owner) if owner != worker => {
                (worker as i64 - owner as i64).unsigned_abs() as f64
            }
            _ => 0.0,
        }
    }

    fn score(&self, worker: WorkerId, task: &Task) -> f64 {
        let w = &self.weights;
        let r = task.memory_region;
        w.locality * self.locality(worker, r)
            + w.memory_affinity * self.memory_affinity(worker, r)
            + w.queue_pressure * self.queue_pressure(worker)
            + w.stealability * self.stealability(worker)
            - w.migration_cost * self.migration_cost(worker, r)
    }

    /// select_least_loaded_worker: argmin queue_len (ties → lowest id).
    fn select_least_loaded_worker(&self) -> WorkerId {
        let mut best = 0usize;
        let mut best_len = self.workers[0].queue_len();
        for (i, w) in self.workers.iter().enumerate().skip(1) {
            let l = w.queue_len();
            if l < best_len {
                best = i;
                best_len = l;
            }
        }
        best
    }

    fn candidates_for(&self, r: RegionId) -> Vec<WorkerId> {
        self.sparse_edges
            .get(&r)
            .cloned()
            .unwrap_or_else(|| self.default_affinity.clone())
    }

    /// RAW_ROUTE(task) — returns chosen worker id per spec.
    pub fn raw_route(&mut self, task: Task) -> WorkerId {
        let r = task.memory_region;

        // Sticky owner hit.
        if let Some(owner) = self.owner_of(r) {
            self.workers[owner].deque.push_back(task);
            return owner;
        }

        // Scored candidates over SparseEdges[r].
        let candidates = self.candidates_for(r);
        let mut best: Option<WorkerId> = None;
        let mut best_score = f64::NEG_INFINITY;
        for worker in candidates {
            if worker >= self.workers.len() {
                continue;
            }
            let s = self.score(worker, &task);
            if s > best_score {
                best = Some(worker);
                best_score = s;
            }
        }

        if let Some(b) = best {
            self.workers[b].deque.push_back(task);
            self.set_owner(r, b);
            return b;
        }

        // Fallback: least loaded.
        let worker = self.select_least_loaded_worker();
        self.workers[worker].deque.push_back(task);
        self.set_owner(r, worker);
        worker
    }

    /// Total queued tasks across workers (for tests).
    pub fn total_tasks(&self) -> usize {
        self.workers.iter().map(|w| w.queue_len()).sum()
    }
}

impl Default for ScoreWeights {
    fn default() -> Self {
        ScoreWeights {
            locality: 1.0,
            memory_affinity: 1.0,
            queue_pressure: 1.0,
            stealability: 1.0,
            migration_cost: 1.0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn default_router(n: usize) -> RawRouteRouter {
        let mut r = RawRouteRouter::new(n);
        r.add_sparse_edge(1, 2);
        r.add_sparse_edge(1, 3);
        r.add_sparse_edge(2, 0);
        r
    }

    #[test]
    fn sticky_owner_reused() {
        let mut rt = default_router(4);
        let t1 = Task { id: 1, memory_region: 7 };
        let w1 = rt.raw_route(t1);
        let t2 = Task { id: 2, memory_region: 7 };
        let w2 = rt.raw_route(t2);
        assert_eq!(w1, w2, "same region must stick to same worker");
        assert_eq!(rt.total_tasks(), 2);
    }

    #[test]
    fn sparse_edge_prefers_affine_worker() {
        let mut rt = default_router(4);
        // Region 1 has affinity to workers {2,3}; owner none initially.
        let t = Task { id: 1, memory_region: 1 };
        let w = rt.raw_route(t);
        assert!(w == 2 || w == 3, "expected affinity candidate, got {w}");
        assert_eq!(rt.owner_of(1), Some(w));
    }

    #[test]
    fn fallback_to_least_loaded_when_no_edges() {
        let mut rt = RawRouteRouter::new(3);
        rt.sparse_edges.clear();
        rt.default_affinity.clear(); // no candidates → fallback path
        let t = Task { id: 1, memory_region: 9 };
        let w = rt.raw_route(t);
        // All empty → worker 0 (first argmin).
        assert_eq!(w, 0);
        assert_eq!(rt.owner_of(9), Some(0));
    }

    #[test]
    fn region_table_records_owner() {
        let mut rt = default_router(4);
        rt.raw_route(Task { id: 1, memory_region: 5 });
        assert!(rt.region_table.contains_key(&5));
        assert!(rt.owner_of(5).is_some());
    }

    #[test]
    fn ownership_transition_monotone() {
        // Once owner set for r, subsequent routes never change it (governed stickiness).
        let mut rt = default_router(4);
        let first = rt.raw_route(Task { id: 1, memory_region: 3 });
        for i in 2..10 {
            let w = rt.raw_route(Task { id: i, memory_region: 3 });
            assert_eq!(w, first, "owner must be stable under RAW_ROUTE");
        }
    }
}

//! NraayTensor: Binary Semantic Governance with Virtual Slicing and Temporal Safety

use crate::error::{NraayError, Result};
use std::sync::Arc;

/// NraayTensor: Binary Semantic Governance Model
///
/// Mathematical Definition:
/// - Physical Storage (𝒫): Strictly contiguous 1D array of length N = ∏ s_i
/// - Semantic View (𝒮): Tuple (S, O, Σ) where:
///   * S (Shape): Dimensions (s_0, ..., s_{d-1})
///   * O (Offset): Starting pointer in 𝒫
///   * Σ (Strides): Step sizes to move along each axis
/// - Binary Governance: Flags (B_layout, B_own)
///   * B_layout = 1 ⟺ σ_i = ∏_{j>i} s_j for all i (canonical strides)
///   * B_own = 1 ⟺ this view exclusively owns the buffer (refcount=1)
///
/// Index Mapping: f(x_0, ..., x_{d-1}) = O + Σ x_i σ_i
#[derive(Clone)]
pub struct NraayTensor {
    /// Ownership Token: Shared buffer via Arc (temporal safety)
    data: Arc<Vec<f32>>,

    /// Semantic Shape
    shape: Vec<usize>,

    /// Semantic Strides
    strides: Vec<usize>,

    /// Memory Offset (for slicing)
    offset: usize,

    /// B_layout: Is canonical stride pattern (for this view's shape)?
    is_contiguous: bool,

    /// B_own: Does this view exclusively own the buffer (for COW)?
    owns_storage: bool,
}

impl NraayTensor {
    /// Create new tensor with given shape. Initializes with zeros.
    ///
    /// **Governance State**: B_layout=1, B_own=1 (contiguous, exclusive)
    pub fn new(shape: Vec<usize>) -> Result<Self> {
        if shape.is_empty() {
            return Err(NraayError::EmptyTensor);
        }

        let size: usize = shape.iter().product();
        if size == 0 {
            return Err(NraayError::EmptyTensor);
        }

        let strides = Self::canonical_strides(&shape);

        Ok(NraayTensor {
            data: Arc::new(vec![0.0; size]),
            shape,
            strides,
            offset: 0,
            is_contiguous: true,
            owns_storage: true,
        })
    }

    /// Get reference to data
    pub fn data(&self) -> Arc<Vec<f32>> {
        Arc::clone(&self.data)
    }

    /// Get shape
    pub fn shape(&self) -> &[usize] {
        &self.shape
    }

    /// Get strides
    pub fn strides(&self) -> &[usize] {
        &self.strides
    }

    /// Get offset
    pub fn offset(&self) -> usize {
        self.offset
    }

    /// Get B_layout flag (is canonical contiguous?)
    pub fn is_contiguous(&self) -> bool {
        self.is_contiguous
    }

    /// Get B_own flag (exclusive ownership?)
    pub fn owns_storage(&self) -> bool {
        self.owns_storage
    }

    /// Total number of elements
    pub fn len(&self) -> usize {
        self.shape.iter().product()
    }

    /// Physical buffer size
    pub fn buffer_size(&self) -> usize {
        self.data.len()
    }

    /// Calculate canonical strides for a given shape
    fn canonical_strides(shape: &[usize]) -> Vec<usize> {
        let mut strides = vec![0; shape.len()];
        let mut stride = 1;
        for i in (0..shape.len()).rev() {
            strides[i] = stride;
            stride *= shape[i];
        }
        strides
    }

    /// Recompute B_layout flag (check if strides are canonical)
    fn recompute_contiguity(&mut self) {
        if self.shape.is_empty() {
            self.is_contiguous = false;
            return;
        }

        let canonical = Self::canonical_strides(&self.shape);
        self.is_contiguous = self.strides == canonical;
    }

    /// Virtual Slicing: Zero-copy view with shared ownership
    ///
    /// Creates new view sharing the same physical buffer. Updates:
    /// - Shape: s'_i = end_i - start_i
    /// - Offset: O' = O + Σ start_i σ_i
    /// - Strides: σ'_i = σ_i * step_i
    /// - B_own: → 0 (shared ownership)
    /// - B_layout: Recomputed for new shape
    ///
    /// **Governance Invariant**: Physical buffer 𝒫 immutable during view creation
    pub fn slice(&self, ranges: &[(usize, usize, usize)]) -> Result<Self> {
        if ranges.len() != self.shape.len() {
            return Err(NraayError::DimensionMismatch {
                expected: self.shape.len(),
                actual: ranges.len(),
            });
        }

        let mut new_shape = Vec::with_capacity(self.shape.len());
        let mut new_strides = Vec::with_capacity(self.strides.len());
        let mut new_offset = self.offset;

        for (dim, &(start, end, step)) in ranges.iter().enumerate() {
            if start >= self.shape[dim] || end > self.shape[dim] || start >= end || step == 0 {
                return Err(NraayError::InvalidSliceRange {
                    start,
                    end,
                    size: self.shape[dim],
                });
            }

            let dim_size = (end - start + step - 1) / step; // Ceiling division
            new_shape.push(dim_size);

            new_offset += start * self.strides[dim];
            new_strides.push(self.strides[dim] * step);
        }

        let mut view = NraayTensor {
            data: Arc::clone(&self.data),
            shape: new_shape,
            strides: new_strides,
            offset: new_offset,
            is_contiguous: false,
            owns_storage: false,
        };
        view.recompute_contiguity();

        Ok(view)
    }

    /// Logical Shift (Axes Permutation): Transpose via stride rearrangement
    ///
    /// Permutes axes without touching physical memory:
    /// - S_new = S[perm]
    /// - Σ_new = Σ[perm]
    /// - B_own: unchanged
    /// - B_layout: → 0 if permutation changes canonical order
    ///
    /// **Governance Invariant**: Physical buffer 𝒫 untouched (only metadata)
    pub fn transpose(&mut self, perm: &[usize]) -> Result<()> {
        if perm.len() != self.shape.len() {
            return Err(NraayError::InvalidPermutation {
                expected: self.shape.len(),
                actual: perm.len(),
            });
        }

        // Verify permutation is valid
        let mut seen = vec![false; perm.len()];
        for &p in perm {
            if p >= perm.len() || seen[p] {
                return Err(NraayError::InvalidPermutation {
                    expected: self.shape.len(),
                    actual: perm.len(),
                });
            }
            seen[p] = true;
        }

        let mut new_shape = Vec::with_capacity(self.shape.len());
        let mut new_strides = Vec::with_capacity(self.strides.len());

        for &p in perm {
            new_shape.push(self.shape[p]);
            new_strides.push(self.strides[p]);
        }

        self.shape = new_shape;
        self.strides = new_strides;
        self.recompute_contiguity();

        Ok(())
    }

    /// Materialization: Restore Contiguity with Copy-on-Write
    ///
    /// If B_layout=1 and B_own=1: No-op (already canonical and exclusive)
    /// If B_layout=0 or B_own=0:
    ///   - Allocate new contiguous buffer
    ///   - Copy viewed elements in row-major order
    ///   - Update strides to canonical
    ///   - Set B_layout=1, B_own=1
    ///
    /// **COW Semantics**: If refcount > 1, other views unaffected (new Arc)
    /// **Governance Invariant**: "Preserving order, strict and bound"
    pub fn materialize(&mut self) -> Result<()> {
        if self.is_contiguous && self.owns_storage {
            return Ok(());
        }

        // Allocate new buffer for viewed elements
        let viewed_size = self.len();
        let mut new_data = vec![0.0; viewed_size];

        // Copy viewed elements in logical order
        self.copy_viewed_to(&mut new_data, 0)?;

        // Replace shared Arc with exclusive ownership
        self.data = Arc::new(new_data);

        // Reset to canonical strides
        self.strides = Self::canonical_strides(&self.shape);
        self.offset = 0;
        self.is_contiguous = true;
        self.owns_storage = true;

        Ok(())
    }

    /// Copy viewed elements to destination buffer in row-major order
    fn copy_viewed_to(&self, dst: &mut [f32], mut dst_idx: usize) -> Result<()> {
        self.copy_recursive(dst, &mut dst_idx, 0, self.offset)?;
        Ok(())
    }

    /// Recursive helper for copying elements
    fn copy_recursive(
        &self,
        dst: &mut [f32],
        dst_idx: &mut usize,
        dim: usize,
        offset: usize,
    ) -> Result<()> {
        if dim == self.shape.len() {
            if offset < self.data.len() {
                dst[*dst_idx] = self.data[offset];
                *dst_idx += 1;
                Ok(())
            } else {
                Err(NraayError::IndexOutOfBounds {
                    dim: 0,
                    index: offset,
                    size: self.data.len(),
                })
            }
        } else {
            for i in 0..self.shape[dim] {
                self.copy_recursive(dst, dst_idx, dim + 1, offset + i * self.strides[dim])?;
            }
            Ok(())
        }
    }

    /// Get element at logical coordinate
    pub fn get(&self, coord: &[usize]) -> Result<f32> {
        if coord.len() != self.shape.len() {
            return Err(NraayError::DimensionMismatch {
                expected: self.shape.len(),
                actual: coord.len(),
            });
        }

        // Check bounds
        for (i, &c) in coord.iter().enumerate() {
            if c >= self.shape[i] {
                return Err(NraayError::IndexOutOfBounds {
                    dim: i,
                    index: c,
                    size: self.shape[i],
                });
            }
        }

        // Compute physical index
        let mut idx = self.offset;
        for (i, &c) in coord.iter().enumerate() {
            idx += c * self.strides[i];
        }

        if idx < self.data.len() {
            Ok(self.data[idx])
        } else {
            Err(NraayError::IndexOutOfBounds {
                dim: 0,
                index: idx,
                size: self.data.len(),
            })
        }
    }

    /// Set element at logical coordinate
    pub fn set(&mut self, coord: &[usize], value: f32) -> Result<()> {
        if coord.len() != self.shape.len() {
            return Err(NraayError::DimensionMismatch {
                expected: self.shape.len(),
                actual: coord.len(),
            });
        }

        // Check bounds
        for (i, &c) in coord.iter().enumerate() {
            if c >= self.shape[i] {
                return Err(NraayError::IndexOutOfBounds {
                    dim: i,
                    index: c,
                    size: self.shape[i],
                });
            }
        }

        // Compute physical index
        let mut idx = self.offset;
        for (i, &c) in coord.iter().enumerate() {
            idx += c * self.strides[i];
        }

        if idx < self.data.len() {
            // Ensure we have exclusive ownership before mutating
            if Arc::strong_count(&self.data) > 1 {
                // Shared; create exclusive copy
                let mut new_data = (*self.data).clone();
                new_data[idx] = value;
                self.data = Arc::new(new_data);
                self.owns_storage = true;
            } else {
                // Exclusive; safe to mutate via Arc::get_mut (refcount==1 checked above).
                if let Some(ptr) = Arc::get_mut(&mut self.data) {
                    ptr[idx] = value;
                }
            }
            Ok(())
        } else {
            Err(NraayError::IndexOutOfBounds {
                dim: 0,
                index: idx,
                size: self.data.len(),
            })
        }
    }

    /// Get Arc strong count (for testing reference counting)
    pub fn refcount(&self) -> usize {
        Arc::strong_count(&self.data)
    }

    /// Copy element values from `src` (same shape) into this tensor's logical view.
    /// Materializes self first so writes land on an exclusive contiguous buffer.
    /// Used by the ML layer to store gradient buffers.
    pub fn set_raw_from(&mut self, src: &NraayTensor) -> Result<()> {
        if self.shape != src.shape {
            return Err(NraayError::ShapeMismatch {
                expected: self.shape.clone(),
                actual: src.shape.clone(),
            });
        }
        self.materialize()?;
        let mut coord = vec![0usize; self.shape.len()];
        loop {
            let v = src.get(&coord)?;
            self.set(&coord, v)?;
            // Increment multi-index (row-major odometer).
            let mut d = self.shape.len();
            loop {
                if d == 0 {
                    return Ok(());
                }
                d -= 1;
                coord[d] += 1;
                if coord[d] < self.shape[d] {
                    break;
                }
                coord[d] = 0;
            }
        }
    }

    /// Weak observer (𝒲): non-owning handle that never prevents deallocation.
    pub fn downgrade(&self) -> std::sync::Weak<Vec<f32>> {
        Arc::downgrade(&self.data)
    }
}

impl std::fmt::Debug for NraayTensor {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NraayTensor")
            .field("shape", &self.shape)
            .field("strides", &self.strides)
            .field("offset", &self.offset)
            .field("is_contiguous", &self.is_contiguous)
            .field("owns_storage", &self.owns_storage)
            .field("refcount", &Arc::strong_count(&self.data))
            .field("buffer_size", &self.data.len())
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_creation() {
        let t = NraayTensor::new(vec![2, 3]).unwrap();
        assert_eq!(t.shape(), &[2, 3]);
        assert_eq!(t.len(), 6);
        assert!(t.is_contiguous());
        assert!(t.owns_storage());
    }

    #[test]
    fn test_canonical_strides() {
        let strides = NraayTensor::canonical_strides(&[2, 3, 4]);
        assert_eq!(strides, vec![12, 4, 1]);
    }

    #[test]
    fn test_slice_shared_ownership() {
        let t = NraayTensor::new(vec![4, 4]).unwrap();
        let s1 = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();
        assert!(!s1.owns_storage());
        assert_eq!(t.refcount(), 2); // t + s1
        assert_eq!(s1.len(), 8);
    }

    #[test]
    fn test_slice_non_contiguous() {
        let t = NraayTensor::new(vec![4, 4]).unwrap();
        let s = t.slice(&[(0, 4, 1), (0, 4, 2)]).unwrap();
        assert!(!s.is_contiguous()); // Step > 1 makes non-canonical
        assert_eq!(s.shape(), &[4, 2]);
    }

    #[test]
    fn test_transpose() {
        let mut t = NraayTensor::new(vec![2, 3]).unwrap();
        t.transpose(&[1, 0]).unwrap();
        assert_eq!(t.shape(), &[3, 2]);
        assert!(!t.is_contiguous());
    }

    #[test]
    fn test_materialize() {
        let mut t = NraayTensor::new(vec![2, 3]).unwrap();
        t.transpose(&[1, 0]).unwrap();
        assert!(!t.is_contiguous());

        let _refcount_before = t.refcount();
        t.materialize().unwrap();
        assert!(t.is_contiguous());
        assert_eq!(t.strides(), &[2, 1]);
        assert_eq!(t.refcount(), 1); // New exclusive buffer
    }

    #[test]
    fn test_get_set() {
        let mut t = NraayTensor::new(vec![2, 3]).unwrap();
        t.set(&[0, 1], 42.0).unwrap();
        assert_eq!(t.get(&[0, 1]).unwrap(), 42.0);
    }

    #[test]
    fn test_temporal_safety() {
        let t = NraayTensor::new(vec![2, 3]).unwrap();
        let s1 = t.slice(&[(0, 1, 1), (0, 3, 1)]).unwrap();
        let s2 = t.slice(&[(1, 2, 1), (0, 3, 1)]).unwrap();

        assert_eq!(t.refcount(), 3); // t, s1, s2

        drop(s1);
        assert_eq!(t.refcount(), 2);

        drop(s2);
        assert_eq!(t.refcount(), 1); // Only t remains
    }
}

use nraay_tensor::prelude::*;
use std::sync::Arc;

#[test]
fn test_1_identity_layout() {
    let t = NraayTensor::new(vec![2, 3]).unwrap();
    assert_eq!(t.is_contiguous(), true);
    assert_eq!(t.owns_storage(), true);
    assert_eq!(t.refcount(), 1);
}

#[test]
fn test_2_logical_shift() {
    let mut t = NraayTensor::new(vec![2, 3]).unwrap();
    t.transpose(&[1, 0]).unwrap();

    assert_eq!(t.shape(), &[3, 2]);
    assert_eq!(t.is_contiguous(), false); // B_layout → 0
    assert_eq!(t.buffer_size(), 6); // Physical size unchanged
}

#[test]
fn test_3_bound_restoration() {
    let mut t = NraayTensor::new(vec![2, 3]).unwrap();
    t.transpose(&[1, 0]).unwrap();

    t.materialize().unwrap();

    assert_eq!(t.is_contiguous(), true); // B_layout → 1
    assert_eq!(t.strides(), &[2, 1]); // Canonical for [3, 2]
}

#[test]
fn test_4_adversarial_shift() {
    let mut t = NraayTensor::new(vec![3, 4, 5]).unwrap();

    // Apply multiple permutations
    t.transpose(&[2, 0, 1]).unwrap();
    assert_eq!(t.is_contiguous(), false);

    t.transpose(&[1, 0, 2]).unwrap();
    assert_eq!(t.is_contiguous(), false);

    // Only materialize restores B_layout
    t.materialize().unwrap();
    assert_eq!(t.is_contiguous(), true);
}

#[test]
fn test_5_zero_copy_slice() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let s = t.slice(&[(1, 3, 1), (0, 4, 1)]).unwrap();

    assert_eq!(Arc::ptr_eq(&t.data(), &s.data()), true); // Same Arc
    assert_eq!(s.offset(), 4); // Offset = 1 * stride[0]
    assert_eq!(s.shape(), &[2, 4]);
    assert_eq!(s.is_contiguous(), true); // Unit steps preserve canonical
}

#[test]
fn test_6_non_contiguous_slice() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let s = t.slice(&[(0, 4, 1), (0, 4, 2)]).unwrap();

    assert_eq!(Arc::ptr_eq(&t.data(), &s.data()), true); // Shared
    assert_eq!(s.is_contiguous(), false); // Step=2 breaks canonical
}

#[test]
fn test_7_cow_isolation() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let mut s = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();

    let t_data_before = Arc::clone(&t.data());

    s.materialize().unwrap();

    // S gets new buffer
    assert_ne!(Arc::ptr_eq(&t.data(), &s.data()), true);
    // T's buffer unchanged
    assert!(Arc::ptr_eq(&t.data(), &t_data_before));
}

#[test]
fn test_8_slice_of_slice() {
    let t = NraayTensor::new(vec![8, 8]).unwrap();
    let s1 = t.slice(&[(1, 6, 1), (1, 6, 1)]).unwrap();
    let s2 = s1.slice(&[(0, 3, 1), (0, 3, 1)]).unwrap();

    // Verify compositional slicing
    assert_eq!(s2.shape(), &[3, 3]);
    // t[1:6, 1:6][0:3, 0:3] == t[1:4, 1:4]
    assert_eq!(s2.offset(), 9); // 1*8 + 1 = 9
}

#[test]
fn test_9_refcount_release() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let s1 = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();
    let s2 = t.slice(&[(2, 4, 1), (0, 4, 1)]).unwrap();

    assert_eq!(t.refcount(), 3); // t, s1, s2

    drop(s1);
    assert_eq!(t.refcount(), 2);

    drop(s2);
    assert_eq!(t.refcount(), 1); // Only t
}

#[test]
fn test_10_adversarial_view_graph() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();

    // Create multiple view permutations
    let mut views = vec![];

    for _ in 0..3 {
        let s = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();
        views.push(s);
    }

    assert_eq!(t.refcount(), 4); // t + 3 views

    // Materialize each
    for v in &mut views {
        v.materialize().ok();
    }

    // After materialization, views have their own buffers
    for v in &views {
        assert!(v.is_contiguous());
        assert!(v.owns_storage());
    }
}

#[test]
fn test_buffer_lifetime_safety() {
    // Test that buffer is not freed while views exist
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let s = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();

    // Both hold Arc strong count
    assert_eq!(t.refcount(), 2);

    // Drop t but s still valid
    drop(t);
    assert_eq!(s.refcount(), 1); // s alone

    // Buffer freed when s drops (end of scope)
}

#[test]
fn test_materialization_non_interference() {
    let t = NraayTensor::new(vec![4, 4]).unwrap();
    let s1 = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();
    let mut s2 = t.slice(&[(2, 4, 1), (0, 4, 1)]).unwrap();

    let t_ptr_before = Arc::as_ptr(&t.data());

    // Materialize s2
    s2.materialize().unwrap();

    // t's buffer unchanged
    assert_eq!(Arc::as_ptr(&t.data()), t_ptr_before);
    // s1 still shares with t
    assert_eq!(Arc::ptr_eq(&t.data(), &s1.data()), true);
}

#[test]
fn test_exclusive_ownership_post_materialize() {
    let t = NraayTensor::new(vec![2, 3]).unwrap();
    let mut s = t.slice(&[(0, 2, 1), (0, 3, 1)]).unwrap();

    // Before: shared
    assert_eq!(s.refcount(), 2);
    assert!(!s.owns_storage());

    // Materialize
    s.materialize().unwrap();

    // After: s exclusive, t unchanged
    assert_eq!(s.refcount(), 1);
    assert!(s.owns_storage());
    assert_eq!(t.refcount(), 1);
}

#[test]
fn test_get_set_operations() {
    let mut t = NraayTensor::new(vec![3, 3]).unwrap();

    // Set values
    t.set(&[0, 0], 1.0).unwrap();
    t.set(&[1, 1], 5.0).unwrap();
    t.set(&[2, 2], 9.0).unwrap();

    // Get values
    assert_eq!(t.get(&[0, 0]).unwrap(), 1.0);
    assert_eq!(t.get(&[1, 1]).unwrap(), 5.0);
    assert_eq!(t.get(&[2, 2]).unwrap(), 9.0);

    // Get unset (should be 0.0)
    assert_eq!(t.get(&[0, 1]).unwrap(), 0.0);
}

#[test]
fn test_get_set_on_slice() {
    let mut t = NraayTensor::new(vec![4, 4]).unwrap();
    t.set(&[0, 0], 10.0).unwrap();

    let s = t.slice(&[(0, 2, 1), (0, 4, 1)]).unwrap();

    // Read through slice
    assert_eq!(s.get(&[0, 0]).unwrap(), 10.0);
}

#[test]
fn test_contiguity_check() {
    let mut t = NraayTensor::new(vec![2, 3, 4]).unwrap();

    // Identity is contiguous
    assert!(t.is_contiguous());

    // After transpose, non-contiguous
    t.transpose(&[2, 0, 1]).unwrap();
    assert!(!t.is_contiguous());

    // After materialize, canonical
    t.materialize().unwrap();
    assert!(t.is_contiguous());
}

#[test]
fn test_stride_calculation() {
    let mut t = NraayTensor::new(vec![2, 3, 4]).unwrap();
    assert_eq!(t.strides(), &[12, 4, 1]);

    // After transpose [2, 0, 1]: shape [4, 2, 3], strides [1, 12, 4]
    t.transpose(&[2, 0, 1]).unwrap();
    assert_eq!(t.strides(), &[1, 12, 4]);
}

//! Error types for tensor operations.

use thiserror::Error;

/// Tensor operation error type.
#[derive(Error, Debug, Clone, PartialEq, Eq)]
pub enum TensorError {
    /// Shape mismatch between operands.
    #[error("shape mismatch: expected {expected:?}, got {actual:?}")]
    ShapeMismatch {
        expected: Vec<usize>,
        actual: Vec<usize>,
    },

    /// Dimension index out of bounds.
    #[error("dimension out of bounds: axis {axis} for rank {rank}")]
    DimOutOfBounds { axis: usize, rank: usize },

    /// Operation on empty array not supported.
    #[error("empty array operation not supported")]
    EmptyArray,

    /// Rank mismatch (incorrect number of dimensions).
    #[error("rank mismatch: expected {expected}, got {actual}")]
    RankMismatch { expected: usize, actual: usize },

    /// Incompatible shapes for operation.
    #[error("incompatible shapes: {0}")]
    IncompatibleShapes(String),

    /// Index out of bounds.
    #[error("index out of bounds: {0}")]
    IndexOutOfBounds(String),

    /// Invalid reshape operation.
    #[error("reshape failed: cannot reshape {from:?} to {to:?}")]
    ReshapeFailed { from: Vec<usize>, to: Vec<usize> },

    /// Division by zero.
    #[error("division by zero")]
    DivisionByZero,
}

